window.CGDD_DATA = {"flow":"%% cgdd_game_2 script flow\n%% Generated by CGDD/Export Trace Docs. Do not edit by hand.\nflowchart TD\n  AmbientAudio(\"<b>AmbientAudio</b><br/>Level background drone, danger layer and sudden-silence ducking, plus 2D one-shot playback.\")\n  AudioSynth(\"<b>AudioSynth</b><br/>Procedural audio library: synthesizes every loop and one-shot clip in code.\")\n  BlinkingLight(\"<b>BlinkingLight</b><br/>Recording LED on cameras and speakers: blinks on and off.\")\n  BlockoutSeat(\"<b>BlockoutSeat</b><br/>Blockout chair: one seat point, a runtime occupancy probe and a clamped seated head turn.\")\n  BlockoutWalker(\"<b>BlockoutWalker</b><br/>Blockout first-person walker for playtesting: walk, run, jump, look and sit on BlockoutSeat chairs.\")\n  BlockoutWaypoint(\"<b>BlockoutWaypoint</b><br/>Blockout patrol stop: wait time and the facing the watcher holds while waiting.\")\n  DangerFX(\"<b>DangerFX</b><br/>URP danger feedback: red vignette and chromatic aberration while seen, plus a hard warning flash.\")\n  DeskPuzzle(\"<b>DeskPuzzle</b><br/>Photos-app desk puzzle: lay the phone in the scratched outline and rotate it until the digits light.\")\n  EndScreen(\"<b>EndScreen</b><br/>End-of-chapter page: caught / chapter complete / final ending, with Continue, Retry and Title.\")\n  Fluorescent(\"<b>Fluorescent</b><br/>Ceiling fluorescent fixture: light, glowing tube and 3D buzz, with optional flicker.\")\n  Footsteps(\"<b>Footsteps</b><br/>3D footsteps for walkers, with an optional key jingle every few steps.\")\n  GameFlow(\"<b>GameFlow</b><br/>Scene-to-scene flow, chapter progress, endings and the player's saved name.\")\n  GameInput(\"<b>GameInput</b><br/>One input facade for the old Input Manager and the new Input System.\")\n  HumSource(\"<b>HumSource</b><br/>The student who hums an off-key anthem: a positional sound you find her by.\")\n  Interactable(\"<b>Interactable</b><br/>Something the player can look at and use with E: prompt, active flag and use callback.\")\n  LessonLine(\"<b>LessonLine</b><br/>Lesson text data: what the teacher says and the questions he may ask about it.\")\n  Level01Director(\"<b>Level01Director</b><br/>Chapter 1 The Lesson: walk in, roll call, search the desk, decode the phone and tap the triangle student.\")\n  Level02Director(\"<b>Level02Director</b><br/>Chapter 2 Lunch: camera and monitor threat, find the hummer, forward the message and reach the STAFF door.\")\n  Level03Director(\"<b>Level03Director</b><br/>Chapter 3 Lights Out: listen for the warden, lie down for bed checks, reply and flash the window three times.\")\n  Level04Director(\"<b>Level04Director</b><br/>Chapter 4 Inspection Day: recover the phone, answer questions, find the 1979 photo and choose an ending.\")\n  LevelDirectorBase(\"<b>LevelDirectorBase</b><br/>Shared chapter rules: subtitles, HUD, look-at interaction, danger and warnings, cards and fades.\")\n  PatrolAI(\"<b>PatrolAI</b><br/>NavMesh watcher: roams random points, follows level routes, approaches or holds to look at you.\")\n  PhoneController(\"<b>PhoneController</b><br/>The inherited phone: lock codes, apps, photos, messages, contacts, tasks and danger shake.\")\n  PixelSprites(\"<b>PixelSprites</b><br/>Pixel-art heart, broken heart and eye sprites generated in code.\")\n  PlayerRig(\"<b>PlayerRig</b><br/>First-person body with walk, pulled, seated, inspect, placing, lying and locked modes.\")\n  RichText(\"<b>RichText</b><br/>Typewriter reveal that keeps Unity rich-text tags intact and closes any tag left open.\")\n  SeatedLook(\"<b>SeatedLook</b><br/>Seated head turn with clamped yaw and pitch, so you cannot look straight behind you.\")\n  SweepRotate(\"<b>SweepRotate</b><br/>Sweeps an object left and right around its starting yaw, used by the cafeteria security camera.\")\n  TeacherAI(\"<b>TeacherAI</b><br/>NavMesh teacher routine: lecture, board writing and wandering, with call-on and approach interrupts.\")\n  TeacherPatrol(\"<b>TeacherPatrol</b><br/>Blockout-only patrol between waypoints with pauses and facing, with no AI or detection.\")\n  TeacherVision(\"<b>TeacherVision</b><br/>Line-of-sight watcher: range, view cone and solid cover checks for teacher, monitor, warden and cameras.\")\n  TitleScreen(\"<b>TitleScreen</b><br/>Title page: CCTV overlay, New Game name entry, Continue, chapter select and Quit.\")\n  TypewriterFont(\"<b>TypewriterFont</b><br/>Swaps UI Text under this object to the monospace typewriter font at runtime.\")\n  UIFactory(\"<b>UIFactory</b><br/>uGUI construction helpers for canvases, rects, images, text and buttons.\")\n  WallClock(\"<b>WallClock</b><br/>Institutional wall clock: hour and minute hands turn at a configurable game speed.\")\n\n  AmbientAudio --> AudioSynth\n  BlockoutWalker --> BlockoutSeat\n  DeskPuzzle --> GameInput\n  EndScreen --> GameFlow\n  EndScreen --> UIFactory\n  EndScreen --> AmbientAudio\n  EndScreen --> AudioSynth\n  EndScreen --> GameInput\n  Fluorescent --> AudioSynth\n  Footsteps --> AudioSynth\n  HumSource --> AudioSynth\n  Level01Director --> LevelDirectorBase\n  Level01Director --> TeacherAI\n  Level01Director --> TeacherVision\n  Level01Director --> PlayerRig\n  Level01Director --> PhoneController\n  Level01Director --> Interactable\n  Level01Director --> LessonLine\n  Level01Director --> GameInput\n  Level02Director --> LevelDirectorBase\n  Level02Director --> PatrolAI\n  Level02Director --> TeacherVision\n  Level02Director --> HumSource\n  Level02Director --> PhoneController\n  Level02Director --> PlayerRig\n  Level02Director --> Interactable\n  Level02Director --> AudioSynth\n  Level02Director --> GameInput\n  Level03Director --> LevelDirectorBase\n  Level03Director --> PatrolAI\n  Level03Director --> TeacherVision\n  Level03Director --> Footsteps\n  Level03Director --> PlayerRig\n  Level03Director --> PhoneController\n  Level03Director --> GameInput\n  Level03Director --> AudioSynth\n  Level04Director --> LevelDirectorBase\n  Level04Director --> TeacherAI\n  Level04Director --> TeacherVision\n  Level04Director --> PlayerRig\n  Level04Director --> PhoneController\n  Level04Director --> Interactable\n  Level04Director --> LessonLine\n  Level04Director --> GameInput\n  Level04Director --> AudioSynth\n  LevelDirectorBase --> PlayerRig\n  LevelDirectorBase --> PhoneController\n  LevelDirectorBase --> AmbientAudio\n  LevelDirectorBase --> DangerFX\n  LevelDirectorBase --> AudioSynth\n  LevelDirectorBase --> UIFactory\n  LevelDirectorBase --> GameInput\n  LevelDirectorBase --> Interactable\n  LevelDirectorBase --> RichText\n  LevelDirectorBase --> GameFlow\n  PhoneController --> UIFactory\n  PhoneController --> GameInput\n  PlayerRig --> GameInput\n  SeatedLook --> GameInput\n  TeacherAI --> LessonLine\n  TeacherPatrol --> BlockoutWaypoint\n  TitleScreen --> GameFlow\n  TitleScreen --> UIFactory\n  TitleScreen --> AmbientAudio\n  TitleScreen --> AudioSynth\n  TitleScreen --> GameInput\n  TypewriterFont --> UIFactory\n\n  classDef manager fill:#f0a202,stroke:#1a140e,color:#1a140e,stroke-width:2.5px\n  classDef actor fill:#fff8ea,stroke:#1a140e,color:#1a140e,stroke-width:2px\n  classDef world fill:#9cba6a,stroke:#1a140e,color:#1a140e,stroke-width:2px\n  classDef ui fill:#efe6cf,stroke:#c4841a,color:#1a140e,stroke-width:2px\n  classDef other fill:#efe6cf,stroke:#1a140e,color:#1a140e,stroke-width:2px\n  class PhoneController manager\n  class PlayerRig,UIFactory actor\n  class LevelDirectorBase world\n  class AmbientAudio,AudioSynth,BlinkingLight,BlockoutSeat,BlockoutWalker,BlockoutWaypoint,DangerFX,DeskPuzzle,EndScreen,Fluorescent,Footsteps,GameFlow,GameInput,HumSource,Interactable,LessonLine,Level01Director,Level02Director,Level03Director,Level04Director,PatrolAI,PixelSprites,RichText,SeatedLook,SweepRotate,TeacherAI,TeacherPatrol,TeacherVision,TitleScreen,TypewriterFont,WallClock other\n","tunables":"# Tunables\n\nGenerated from `@tune` headers by the menu `CGDD/Export Trace Docs`. Hand edits are overwritten on the next export.\n\n| Script | Field | Type | Range | Default | Note |\n| --- | --- | --- | --- | --- | --- |\n| AmbientAudio | droneVolume | float | 0-0.4 | 0.16 | Background drone level. |\n| AmbientAudio | ventVolume | float | 0-0.3 | 0.09 | Ventilation hum level. |\n| BlinkingLight | period | float | 0.2-5 | 1.2 | Seconds per blink cycle. |\n| BlinkingLight | onFraction | float | 0-1 | 0.5 | Fraction of each cycle the LED is on. |\n| BlockoutSeat | eyeHeight | float | 0.8-1.8 | 1.25 | Eye height above the floor while seated. |\n| BlockoutSeat | maxHeadTurn | float | 0-180 | 110 | Degrees the head can turn left or right from the chair's facing. |\n| BlockoutWalker | walkSpeed | float | 1-8 | 4 | Walking speed. |\n| BlockoutWalker | runSpeed | float | 1-12 | 6.5 | Running speed with Shift. |\n| BlockoutWalker | jumpHeight | float | 0-3 | 1 | Jump height in metres. |\n| BlockoutWalker | gravity | float | -40--5 | -20 | Gravity while walking. |\n| BlockoutWalker | eyeStanding | float | 0.8-2 | 1.5 | Standing eye height. |\n| BlockoutWalker | lookSensitivity | float | 1-15 | 5 | Mouse look sensitivity. |\n| BlockoutWalker | interactDistance | float | 0.5-5 | 2.5 | Metres for the look-at chair interaction. |\n| BlockoutWaypoint | waitSeconds | float | 0-60 | 0 | Seconds the watcher stands here. |\n| DeskPuzzle | tolerance | float | 1-20 | 4 | Degrees from perfect that still counts as aligned. |\n| DeskPuzzle | keyRotateSpeed | float | 10-180 | 60 | Phone rotation speed with A or D. |\n| DeskPuzzle | mouseRotate | float | 0.5-10 | 3 | Phone rotation per unit of mouse movement. |\n| Fluorescent | buzzVolume | float | 0-0.2 | 0.07 | Tube buzz level. |\n| Fluorescent | master | float | 0-1 | 1 | Level dimmer for this fixture, 0 = off. |\n| Footsteps | stepLength | float | 0.2-1.5 | 0.7 | Metres travelled per footstep. |\n| Footsteps | volume | float | 0-1 | 0.55 | Footstep volume. |\n| Footsteps | pitch | float | 0.5-1.5 | 1 | Pitch of the footsteps. |\n| Footsteps | minDistance | float | 0-5 | 1.5 | Distance where footsteps are at full volume. |\n| Footsteps | maxDistance | float | 2-30 | 18 | Distance where footsteps fade out. |\n| Footsteps | keysEverySteps | int | 0-10 | 0 | Steps between key jingles, 0 = never. |\n| HumSource | volume | float | 0-1 | 0.8 | Humming volume. |\n| HumSource | maxDistance | float | 1-15 | 6.5 | Distance where the humming fades out. |\n| Level01Director | answerSeconds | float | 5-30 | 10 | Seconds to answer a question. |\n| Level01Director | callInterval | Vector2 | 20-90 | — | Seconds between questions (x to y). |\n| Level01Director | firstCallAtBootSecond | float | 1-10 | 3 | Seconds into the phone boot for the first question. |\n| Level02Director | reachDistance | float | 1-10 | 4 | Distance at which the phone can signal her phone. |\n| Level03Director | lightNoticeSeconds | float | 0.5-4 | 1.6 | Seconds of phone light before the warden notices. |\n| Level03Director | awakeNoticeSeconds | float | 1-6 | 3.2 | Seconds sitting up during a bed check before he notices. |\n| Level04Director | answerSeconds | float | 5-30 | 10 | Seconds to answer a question. |\n| Level04Director | callInterval | Vector2 | 10-60 | — | Seconds between questions (x to y). |\n| Level04Director | inspectionFallbackSeconds | float | 30-240 | 100 | Seconds after taking the phone before inspection starts if the photo is missed. |\n| Level04Director | choiceSeconds | float | 5-30 | 14 | Seconds to choose an ending. |\n| LevelDirectorBase | chances | int | 1-5 | 3 | Warnings before the phone is taken. |\n| LevelDirectorBase | noticeSeconds | float | 0.5-6 | 2.5 | Seconds seen with the phone before danger is full. |\n| LevelDirectorBase | dangerDecayPerSecond | float | 0.05-2 | 0.35 | How fast danger drains when nobody is looking. |\n| LevelDirectorBase | graceAfterWarning | float | 0-10 | 3 | Seconds of safety after a warning. |\n| LevelDirectorBase | interactDistance | float | 0.5-4 | 1.8 | Metres for the look-at interaction ray. |\n| LevelDirectorBase | teacherLineSeconds | float | 2-15 | 7.5 | Default seconds for an authority line. |\n| LevelDirectorBase | thoughtSeconds | float | 2-15 | 7.5 | Default seconds for a thought line. |\n| LevelDirectorBase | gapBetweenLines | float | 0-5 | 1.4 | Silence between subtitle lines. |\n| LevelDirectorBase | typeCharsPerSecond | float | 10-150 | 55 | Typewriter speed for subtitles. |\n| PatrolAI | waitTime | Vector2 | 0-10 | — | Seconds waiting at a roam point (x to y). |\n| PatrolAI | scanAngle | float | 0-120 | 55 | Degrees the head sweeps while waiting. |\n| PatrolAI | scanSpeed | float | 0.1-2 | 0.6 | Head sweep speed. |\n| PhoneController | bootSeconds | float | 1-15 | 5 | Seconds the old phone takes to start up. |\n| PhoneController | raiseSeconds | float | 0.05-1 | 0.25 | Seconds to raise the phone. |\n| PhoneController | lowerSeconds | float | 0.05-1 | 0.3 | Seconds to lower the phone. |\n| PhoneController | readCharsPerSecond | float | 5-80 | 22 | Message typewriter speed. |\n| PhoneController | glowIntensity | float | 0-5 | 1.6 | Screen glow light intensity in the dark. |\n| PlayerRig | walkSpeed | float | 1-5 | 2.8 | Walking speed. |\n| PlayerRig | runSpeed | float | 1-8 | 4.2 | Running speed with Shift. |\n| PlayerRig | gravity | float | -40--5 | -20 | Gravity while walking. |\n| PlayerRig | standingEye | float | 0.8-2 | 1.5 | Eye height when standing. |\n| PlayerRig | pullSpeed | float | 0.5-4 | 1.3 | Speed when pulled to the seat. |\n| PlayerRig | sensitivity | float | 1-15 | 5 | Mouse look sensitivity. |\n| PlayerRig | inspectPitch | float | -30-45 | 8 | Pitch when looking into the desk. |\n| PlayerRig | placingPitch | float | 0-90 | 55 | Pitch when looking at the desk top. |\n| PlayerRig | lyingPitch | float | -60-10 | -28 | Pitch when lying in bed. |\n| SeatedLook | sensitivity | float | 1-15 | 5 | Mouse look sensitivity. |\n| SeatedLook | maxYaw | float | 0-180 | 100 | Maximum head turn from centre. |\n| SeatedLook | minPitch | float | -90-0 | -55 | Maximum look down. |\n| SeatedLook | maxPitch | float | 0-90 | 60 | Maximum look up. |\n| SweepRotate | amplitude | float | 0-180 | 35 | Degrees swept to each side of the starting direction. |\n| SweepRotate | period | float | 1-60 | 10 | Seconds for one full left-right-left sweep. |\n| TeacherAI | lectureTime | Vector2 | 3-20 | — | Lecture duration range (x to y). |\n| TeacherAI | boardTime | Vector2 | 2-15 | — | Board-writing duration range (x to y). |\n| TeacherAI | lookAroundTime | Vector2 | 1-8 | — | Look-around duration range (x to y). |\n| TeacherAI | lectureWeight | float | 0-1 | 0.35 | Chance the next activity is lecturing. |\n| TeacherAI | boardWeight | float | 0-1 | 0.3 | Chance the next activity is writing on the board. |\n| TeacherPatrol | walkSpeed | float | 0.2-4 | 1.2 | Metres per second along the route. |\n| TeacherPatrol | turnSpeed | float | 30-720 | 240 | Degrees per second when turning. |\n| TeacherVision | viewAngle | float | 20-180 | 90 | Full width of the view cone in degrees. |\n| TeacherVision | viewRange | float | 2-30 | 12 | How far the watcher can see. |\n| TeacherVision | eyeHeight | float | 0-3 | 1.6 | Eye height above the watcher's feet. |\n| WallClock | startHour | float | 0-24 | 8.9167 | Hour shown when the level starts. |\n| WallClock | minutesPerSecond | float | 0-2 | 1 | Game minutes per real second, 1/60 = real time. |\n\n","challenge":"# How the challenge changes\n\nLook first at whether win and loss change, then at whether the player's verb changes. If neither changes, it is the same game, just tighter or looser.\n\n| Change | Win/loss changed | Verb changed | Data | Script.field |\n| --- | --- | --- | --- | --- |\n| Start: (describe baseline feel) | — (baseline) | — (player verb) | field=default | ScriptName.field |\n","devlog":"# DEVLOG\n\nOnly append. Do not edit old sections. Two samples stay so students can see the format.\n\nOnly changes to the game itself are logged: the verb, win and loss, pressure, and what the player can feel.\nSite language, diagram styling, and click-to-read-script do not go into an Interaction or a Stage Reflection.\n\nEach gameplay change should add a section `## Interaction NNN — title` (the Agent can append this when it changes the game).\nAdd `## Stage Reflection NNN — title` only when you ask for one: Keep / Change / Cut, and which AI suggestions you accepted or rejected. That reflection stays on the game.\n\n## Interaction 000 — EXAMPLE (sample, do not delete)\n\n- Date: —\n- Who asked: teacher (sample)\n- Request: Tighten one tunable and see if it is still the same game.\n- What changed: Sample only. The current code was not changed. A real change would touch only one `@tune` field.\n- Result: The player's verb did not change. Win and loss did not change. Pressure changed, not the skeleton.\n\n## Stage Reflection 000 — EXAMPLE (sample, do not delete)\n\n### Keep\n- A core verb you can say in one sentence, and a clear win/loss.\n\n### Change\n- To make it harder, turn an existing `@tune` first. Do not add a new system yet.\n\n### Cut\n- No shop, no deep inventory, no optimization that is off-lesson.\n\n### AI\n- Accept: tune feel with existing fields; avoid opening new scripts.\n- Reject: GraphView, object pools, long hand-written scene YAML. This class is about script relationships and tunable numbers.\n","scripts":{"AmbientAudio":{"path":"Assets/Game/Scripts/AmbientAudio.cs","role":"Level background drone, danger layer and sudden-silence ducking, plus 2D one-shot playback.","source":"// @role Level background drone, danger layer and sudden-silence ducking, plus 2D one-shot playback.\n// @calls AudioSynth\n// @tune droneVolume:float:0-0.4:Background drone level.\n// @tune ventVolume:float:0-0.3:Ventilation hum level.\n\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// The level's background sound: a slow drone + ventilation hum, a dissonant layer that rises with danger,\n    /// and \"sudden silence\" (Duck) when a rule is broken. Also plays 2D one-shots (chimes, stingers, ticks).\n    /// Created at runtime by the level director.\n    /// </summary>\n    public class AmbientAudio : MonoBehaviour\n    {\n        public float droneVolume = 0.16f;\n        public float ventVolume = 0.09f;\n        public float extraVolume = 0f;\n        [Range(0f, 1f)] public float dangerLevel;\n\n        AudioSource drone, vent, danger, extra, sfx, voice;\n        float duck = 1f, duckHold;\n\n        public static AmbientAudio Create(Transform parent)\n        {\n            GameObject g = new GameObject(\"AmbientAudio\");\n            g.transform.SetParent(parent, false);\n            return g.AddComponent<AmbientAudio>();\n        }\n\n        AudioSource Loop(AudioClip clip)\n        {\n            AudioSource s = gameObject.AddComponent<AudioSource>();\n            s.clip = clip;\n            s.loop = true;\n            s.spatialBlend = 0f;\n            s.playOnAwake = false;\n            s.volume = 0f;\n            if (clip != null) { s.time = Random.Range(0f, clip.length * 0.9f); s.Play(); }\n            return s;\n        }\n\n        void Awake()\n        {\n            drone = Loop(AudioSynth.Drone());\n            vent = Loop(AudioSynth.Ventilation());\n            danger = Loop(AudioSynth.DangerLayer());\n            extra = gameObject.AddComponent<AudioSource>();\n            extra.loop = true;\n            extra.playOnAwake = false;\n            sfx = gameObject.AddComponent<AudioSource>();\n            sfx.playOnAwake = false;\n            voice = gameObject.AddComponent<AudioSource>();\n            voice.playOnAwake = false;\n        }\n\n        /// <summary>An extra 2D loop for the level (e.g. sleeping students breathing).</summary>\n        public void SetExtraLoop(AudioClip clip, float volume)\n        {\n            extra.clip = clip;\n            extraVolume = volume;\n            if (clip != null) extra.Play(); else extra.Stop();\n        }\n\n        /// <summary>Everything goes silent for a moment.</summary>\n        public void Duck(float seconds) { duckHold = Mathf.Max(duckHold, seconds); }\n\n        public void Play(AudioClip clip, float volume, float pitch = 1f)\n        {\n            if (clip == null) return;\n            if (Mathf.Abs(pitch - 1f) < 0.001f) { sfx.PlayOneShot(clip, volume); return; }\n            voice.pitch = pitch;\n            voice.PlayOneShot(clip, volume);\n        }\n\n        void Update()\n        {\n            if (duckHold > 0f) duckHold -= Time.unscaledDeltaTime;\n            duck = Mathf.MoveTowards(duck, duckHold > 0f ? 0f : 1f, Time.unscaledDeltaTime * (duckHold > 0f ? 6f : 0.6f));\n            drone.volume = droneVolume * duck;\n            vent.volume = ventVolume * duck;\n            danger.volume = Mathf.Clamp01(dangerLevel) * 0.32f * duck;\n            extra.volume = extraVolume * duck;\n            AudioListener.volume = Mathf.Lerp(0.35f, 1f, duck);   // the whole room goes quiet, not only the music\n        }\n\n        void OnDestroy() { AudioListener.volume = 1f; }\n    }\n}\n"},"AudioSynth":{"path":"Assets/Game/Scripts/AudioSynth.cs","role":"Procedural audio library: synthesizes every loop and one-shot clip in code.","source":"// @role Procedural audio library: synthesizes every loop and one-shot clip in code.\n\nusing System.Collections.Generic;\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Every sound in the game is made here, in code - no audio files needed.\n    /// Loops are built with a whole number of cycles (or a cross-fade), so they repeat without a click.\n    /// Audio identity (from our style sheet): fluorescent buzzing, ventilation hum, footsteps in quiet halls,\n    /// sparse repetitive drones, polite chimes, sudden silence when a rule is broken.\n    /// </summary>\n    public static class AudioSynth\n    {\n        const int SR = 22050;\n        static readonly Dictionary<string, AudioClip> cache = new Dictionary<string, AudioClip>();\n        static System.Random rng = new System.Random(1952);\n\n        static AudioClip Make(string name, float[] data)\n        {\n            AudioClip c = AudioClip.Create(name, data.Length, 1, SR, false);\n            c.SetData(data, 0);\n            cache[name] = c;\n            return c;\n        }\n\n        static bool Cached(string name, out AudioClip c) { return cache.TryGetValue(name, out c) && c != null; }\n        static float Noise() { return (float)(rng.NextDouble() * 2.0 - 1.0); }\n        static float TwoPi { get { return Mathf.PI * 2f; } }\n\n        /// <summary>Joins the end of a longer buffer onto its start, so it loops seamlessly.</summary>\n        static float[] CrossfadeLoop(float[] raw, int length, int fade)\n        {\n            float[] o = new float[length];\n            for (int i = 0; i < length; i++) o[i] = raw[i];\n            for (int i = 0; i < fade; i++)\n            {\n                float a = i / (float)fade;\n                o[i] = raw[i] * a + raw[length + i] * (1f - a);\n            }\n            return o;\n        }\n\n        static void Normalize(float[] d, float peak)\n        {\n            float m = 0.0001f;\n            for (int i = 0; i < d.Length; i++) m = Mathf.Max(m, Mathf.Abs(d[i]));\n            float k = peak / m;\n            for (int i = 0; i < d.Length; i++) d[i] *= k;\n        }\n\n        // ------------------------------------------------------------------ loops\n        /// <summary>Fluorescent tube: 120 Hz mains hum with harmonics and a faint crackle. 2 s loop.</summary>\n        public static AudioClip FluorescentHum()\n        {\n            AudioClip c; if (Cached(\"hum\", out c)) return c;\n            int n = SR * 2;\n            float[] d = new float[n];\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float s = Mathf.Sin(TwoPi * 120f * t) * 0.5f + Mathf.Sin(TwoPi * 240f * t) * 0.3f + Mathf.Sin(TwoPi * 360f * t) * 0.12f\n                        + Mathf.Sin(TwoPi * 1080f * t) * 0.04f;\n                d[i] = s + Noise() * 0.035f;\n            }\n            Normalize(d, 0.5f);\n            return Make(\"hum\", d);\n        }\n\n        /// <summary>Ventilation: soft low-passed noise. 4 s loop.</summary>\n        public static AudioClip Ventilation()\n        {\n            AudioClip c; if (Cached(\"vent\", out c)) return c;\n            int n = SR * 4, f = SR / 4;\n            float[] raw = new float[n + f];\n            float lp = 0f, lp2 = 0f;\n            for (int i = 0; i < raw.Length; i++)\n            {\n                lp += (Noise() - lp) * 0.06f;\n                lp2 += (lp - lp2) * 0.08f;\n                raw[i] = lp2;\n            }\n            float[] d = CrossfadeLoop(raw, n, f);\n            Normalize(d, 0.6f);\n            return Make(\"vent\", d);\n        }\n\n        /// <summary>Sparse institutional drone (A1 + E2 + a slightly sour A2), slow swell. 8 s loop.</summary>\n        public static AudioClip Drone()\n        {\n            AudioClip c; if (Cached(\"drone\", out c)) return c;\n            int n = SR * 8;\n            float[] d = new float[n];\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float swell = 0.65f + 0.35f * Mathf.Sin(TwoPi * t / 8f);\n                float s = Mathf.Sin(TwoPi * 55f * t) * 0.55f\n                        + Mathf.Sin(TwoPi * 82.5f * t) * 0.3f * (0.5f + 0.5f * Mathf.Sin(TwoPi * t / 4f))\n                        + Mathf.Sin(TwoPi * 110.375f * t) * 0.18f\n                        + Mathf.Sin(TwoPi * 164.875f * t) * 0.07f;\n                d[i] = s * swell;\n            }\n            Normalize(d, 0.55f);\n            return Make(\"drone\", d);\n        }\n\n        /// <summary>Dissonant beating layer that fades in with danger. 4 s loop.</summary>\n        public static AudioClip DangerLayer()\n        {\n            AudioClip c; if (Cached(\"danger\", out c)) return c;\n            int n = SR * 4;\n            float[] d = new float[n];\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float trem = 0.6f + 0.4f * Mathf.Sin(TwoPi * 6f * t);\n                d[i] = (Mathf.Sin(TwoPi * 233.25f * t) + Mathf.Sin(TwoPi * 246.75f * t) * 0.9f + Mathf.Sin(TwoPi * 58.25f * t) * 0.7f) * trem;\n            }\n            Normalize(d, 0.55f);\n            return Make(\"danger\", d);\n        }\n\n        /// <summary>Someone humming an off-key anthem. 7.5 s loop.</summary>\n        public static AudioClip HumMelody()\n        {\n            AudioClip c; if (Cached(\"melody\", out c)) return c;\n            float[] notes = { 261.6f, 329.6f, 392f, 329.6f, 349.2f, 293.7f, 261.6f, 0f, 293.7f, 311f, 0f };\n            float noteLen = 0.68f;\n            int n = (int)(SR * noteLen * notes.Length);\n            float[] d = new float[n];\n            float phase = 0f;\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                int k = Mathf.Min(notes.Length - 1, (int)(t / noteLen));\n                float local = t - k * noteLen;\n                float f = notes[k];\n                if (f <= 0f) { d[i] = 0f; continue; }\n                f *= (k % 3 == 1) ? 0.985f : 1f;                                   // a little flat, sometimes\n                f *= 1f + 0.012f * Mathf.Sin(TwoPi * 5.2f * t);                    // vibrato\n                phase += TwoPi * f / SR;\n                float env = Mathf.Clamp01(local / 0.08f) * Mathf.Clamp01((noteLen - local) / 0.12f);\n                d[i] = (Mathf.Sin(phase) + 0.35f * Mathf.Sin(phase * 2f) + 0.1f * Mathf.Sin(phase * 3f)) * env;\n            }\n            Normalize(d, 0.6f);\n            return Make(\"melody\", d);\n        }\n\n        /// <summary>Slow breathing of sleeping students. 4 s loop.</summary>\n        public static AudioClip Breathing()\n        {\n            AudioClip c; if (Cached(\"breath\", out c)) return c;\n            int n = SR * 4;\n            float[] d = new float[n];\n            float lp = 0f;\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                lp += (Noise() - lp) * 0.12f;\n                float env = Mathf.Pow(Mathf.Sin(Mathf.PI * t / 4f), 2f);\n                d[i] = lp * env;\n            }\n            Normalize(d, 0.5f);\n            return Make(\"breath\", d);\n        }\n\n        // ------------------------------------------------------------------ one-shots\n        /// <summary>Two-tone PA chime (\"ding-dong\").</summary>\n        public static AudioClip Chime()\n        {\n            AudioClip c; if (Cached(\"chime\", out c)) return c;\n            int n = (int)(SR * 1.8f);\n            float[] d = new float[n];\n            Bell(d, 659.25f, 0f, 1.2f);\n            Bell(d, 523.25f, 0.55f, 1.25f);\n            Normalize(d, 0.6f);\n            return Make(\"chime\", d);\n        }\n\n        /// <summary>Bright confirmation chime (message sent, door open...).</summary>\n        public static AudioClip Confirm()\n        {\n            AudioClip c; if (Cached(\"confirm\", out c)) return c;\n            int n = (int)(SR * 0.9f);\n            float[] d = new float[n];\n            Bell(d, 1046.5f, 0f, 0.6f);\n            Bell(d, 1568f, 0.12f, 0.7f);\n            Normalize(d, 0.45f);\n            return Make(\"confirm\", d);\n        }\n\n        static void Bell(float[] d, float f, float start, float len)\n        {\n            int s0 = (int)(start * SR), s1 = Mathf.Min(d.Length, s0 + (int)(len * SR));\n            for (int i = s0; i < s1; i++)\n            {\n                float t = (i - s0) / (float)SR;\n                float env = Mathf.Exp(-3.2f * t) * Mathf.Clamp01(t / 0.004f);\n                d[i] += (Mathf.Sin(TwoPi * f * t) + 0.35f * Mathf.Sin(TwoPi * f * 2.76f * t) * Mathf.Exp(-6f * t) + 0.2f * Mathf.Sin(TwoPi * f * 2f * t)) * env;\n            }\n        }\n\n        static AudioClip[] steps;\n        /// <summary>Three variations of a footstep on hard floor.</summary>\n        public static AudioClip[] Steps()\n        {\n            if (steps != null && steps[0] != null) return steps;\n            steps = new AudioClip[3];\n            for (int v = 0; v < 3; v++)\n            {\n                int n = (int)(SR * 0.16f);\n                float[] d = new float[n];\n                float lp = 0f, cut = 0.18f + v * 0.05f;\n                for (int i = 0; i < n; i++)\n                {\n                    float t = i / (float)SR;\n                    lp += (Noise() - lp) * cut;\n                    d[i] = lp * Mathf.Exp(-t * 38f) * 1.4f + Mathf.Sin(TwoPi * (68f + v * 9f) * t) * Mathf.Exp(-t * 28f) * 0.8f;\n                }\n                Normalize(d, 0.8f);\n                steps[v] = Make(\"step\" + v, d);\n            }\n            return steps;\n        }\n\n        /// <summary>A ring of keys.</summary>\n        public static AudioClip Keys()\n        {\n            AudioClip c; if (Cached(\"keys\", out c)) return c;\n            int n = (int)(SR * 0.5f);\n            float[] d = new float[n];\n            float[] onsets = { 0f, 0.07f, 0.16f, 0.21f };\n            for (int o = 0; o < onsets.Length; o++)\n            {\n                float f1 = 2600f + o * 530f, f2 = 4100f + o * 370f;\n                int s0 = (int)(onsets[o] * SR);\n                for (int i = s0; i < n; i++)\n                {\n                    float t = (i - s0) / (float)SR;\n                    float env = Mathf.Exp(-t * 22f);\n                    d[i] += (Mathf.Sin(TwoPi * f1 * t) + 0.6f * Mathf.Sin(TwoPi * f2 * t) + Noise() * 0.3f) * env;\n                }\n            }\n            Normalize(d, 0.45f);\n            return Make(\"keys\", d);\n        }\n\n        /// <summary>A creaking door.</summary>\n        public static AudioClip Creak()\n        {\n            AudioClip c; if (Cached(\"creak\", out c)) return c;\n            int n = (int)(SR * 1.0f);\n            float[] d = new float[n];\n            float phase = 0f, lp = 0f;\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float f = 170f + 130f * t + 25f * Mathf.Sin(TwoPi * 7f * t) + Noise() * 20f;\n                phase += f / SR;\n                float saw = (phase % 1f) * 2f - 1f;\n                lp += (saw - lp) * 0.25f;\n                d[i] = lp * Mathf.Sin(Mathf.PI * t) * (0.6f + 0.4f * Mathf.Sin(TwoPi * 13f * t));\n            }\n            Normalize(d, 0.5f);\n            return Make(\"creak\", d);\n        }\n\n        /// <summary>Low hit used when a warning is given.</summary>\n        public static AudioClip Stinger()\n        {\n            AudioClip c; if (Cached(\"stinger\", out c)) return c;\n            int n = (int)(SR * 1.2f);\n            float[] d = new float[n];\n            float phase = 0f;\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float f = 70f * Mathf.Exp(-t * 1.5f) + 32f;\n                phase += TwoPi * f / SR;\n                d[i] = Mathf.Sin(phase) * Mathf.Exp(-t * 2.2f) * 1.2f\n                     + Noise() * Mathf.Exp(-t * 18f) * 0.5f\n                     + (Mathf.Sin(TwoPi * 466f * t) + Mathf.Sin(TwoPi * 493f * t)) * 0.12f * Mathf.Exp(-t * 3f);\n            }\n            Normalize(d, 0.8f);\n            return Make(\"stinger\", d);\n        }\n\n        /// <summary>Phone vibrating in a drawer.</summary>\n        public static AudioClip Vibrate()\n        {\n            AudioClip c; if (Cached(\"vibrate\", out c)) return c;\n            int n = (int)(SR * 0.35f);\n            float[] d = new float[n];\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float env = Mathf.Sin(Mathf.PI * t / 0.35f);\n                d[i] = Mathf.Sign(Mathf.Sin(TwoPi * 160f * t)) * 0.3f * env;\n            }\n            return Make(\"vibrate\", d);\n        }\n\n        /// <summary>Typewriter tick.</summary>\n        public static AudioClip Tick()\n        {\n            AudioClip c; if (Cached(\"tick\", out c)) return c;\n            int n = (int)(SR * 0.025f);\n            float[] d = new float[n];\n            float prev = 0f;\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float x = Noise();\n                d[i] = (x - prev) * Mathf.Exp(-t * 260f);\n                prev = x;\n            }\n            Normalize(d, 0.5f);\n            return Make(\"tick\", d);\n        }\n\n        /// <summary>A short \"voice\" syllable. Pitch it per speaker (Animal-Crossing style mumble).</summary>\n        public static AudioClip Blip()\n        {\n            AudioClip c; if (Cached(\"blip\", out c)) return c;\n            int n = (int)(SR * 0.085f);\n            float[] d = new float[n];\n            float f0 = 150f;\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float s = 0f;\n                for (int h = 1; h <= 12; h++)\n                {\n                    float fh = f0 * h;\n                    float w = Mathf.Exp(-Mathf.Pow((fh - 700f) / 260f, 2f)) + 0.6f * Mathf.Exp(-Mathf.Pow((fh - 1200f) / 300f, 2f)) + 0.25f / h;\n                    s += Mathf.Sin(TwoPi * fh * t) * w;\n                }\n                d[i] = s * Mathf.Sin(Mathf.PI * t / 0.085f);\n            }\n            Normalize(d, 0.5f);\n            return Make(\"blip\", d);\n        }\n\n        /// <summary>\n        /// Many people talking at a normal volume behind a door (muffled). 6 s seamless loop.\n        /// The one sound in the game that is not polite, not monitored, not quiet.\n        /// </summary>\n        public static AudioClip Murmur()\n        {\n            AudioClip c; if (Cached(\"murmur\", out c)) return c;\n            int n = SR * 6, fade = SR / 2;\n            float[] raw = new float[n + fade];\n            System.Random r = new System.Random(304);\n            for (int v = 0; v < 7; v++)\n            {\n                float f0 = 105f + (float)r.NextDouble() * 170f;\n                float pan = 0.6f + (float)r.NextDouble() * 0.6f;\n                int i = (int)(r.NextDouble() * SR * 0.5);\n                while (i < raw.Length)\n                {\n                    // one syllable, then a short gap (or a longer pause between phrases)\n                    int len = (int)(SR * (0.09 + r.NextDouble() * 0.16));\n                    float fa = 450f + (float)r.NextDouble() * 500f, fb = 1000f + (float)r.NextDouble() * 900f;\n                    float bend = 1f + ((float)r.NextDouble() - 0.5f) * 0.25f;\n                    for (int k = 0; k < len && i + k < raw.Length; k++)\n                    {\n                        float t = k / (float)SR;\n                        float env = Mathf.Sin(Mathf.PI * k / len);\n                        float f = f0 * Mathf.Lerp(1f, bend, k / (float)len);\n                        float sum = 0f;\n                        for (int h = 1; h <= 8; h++)\n                        {\n                            float fh = f * h;\n                            float w = Mathf.Exp(-Mathf.Pow((fh - fa) / 220f, 2f)) + 0.5f * Mathf.Exp(-Mathf.Pow((fh - fb) / 280f, 2f)) + 0.15f / h;\n                            sum += Mathf.Sin(TwoPi * fh * t) * w;\n                        }\n                        raw[i + k] += sum * env * 0.12f * pan;\n                    }\n                    i += len + (int)(SR * (r.NextDouble() < 0.18 ? 0.35 + r.NextDouble() * 0.6 : 0.03 + r.NextDouble() * 0.08));\n                }\n            }\n            // muffled: through a door\n            float y = 0f;\n            for (int i = 0; i < raw.Length; i++) { y += (raw[i] - y) * 0.18f; raw[i] = y + Noise() * 0.004f; }\n            float[] d = CrossfadeLoop(raw, n, fade);\n            Normalize(d, 0.5f);\n            return Make(\"murmur\", d);\n        }\n\n        /// <summary>Screen flash click.</summary>\n        public static AudioClip Click()\n        {\n            AudioClip c; if (Cached(\"click\", out c)) return c;\n            int n = (int)(SR * 0.06f);\n            float[] d = new float[n];\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                d[i] = (Mathf.Sin(TwoPi * 2200f * t) * 0.6f + Noise() * 0.4f) * Mathf.Exp(-t * 90f);\n            }\n            Normalize(d, 0.4f);\n            return Make(\"click\", d);\n        }\n\n        /// <summary>Glitchy PA - the system stuttering.</summary>\n        public static AudioClip Glitch()\n        {\n            AudioClip c; if (Cached(\"glitch\", out c)) return c;\n            int n = (int)(SR * 0.8f);\n            float[] d = new float[n];\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                bool on = ((int)(t * 23f)) % 3 != 0;\n                d[i] = on ? (Mathf.Sign(Mathf.Sin(TwoPi * (300f + 900f * Mathf.Repeat(t * 7f, 1f)) * t)) * 0.4f + Noise() * 0.3f) * (1f - t / 0.8f) : 0f;\n            }\n            Normalize(d, 0.45f);\n            return Make(\"glitch\", d);\n        }\n    }\n}\n"},"BlinkingLight":{"path":"Assets/Game/Scripts/BlinkingLight.cs","role":"Recording LED on cameras and speakers: blinks on and off.","source":"// @role Recording LED on cameras and speakers: blinks on and off.\n// @tune period:float:0.2-5:Seconds per blink cycle.\n// @tune onFraction:float:0-1:Fraction of each cycle the LED is on.\n\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>Recording LED on a camera / speaker: blinks on and off.</summary>\n    public class BlinkingLight : MonoBehaviour\n    {\n        public Renderer target;\n        public float period = 1.2f;\n        [Range(0f, 1f)] public float onFraction = 0.5f;\n        float offset;\n\n        void Awake()\n        {\n            if (target == null) target = GetComponent<Renderer>();\n            offset = Random.Range(0f, period);\n        }\n\n        void Update()\n        {\n            if (target == null) return;\n            target.enabled = Mathf.Repeat(Time.time + offset, period) < period * onFraction;\n        }\n    }\n}\n"},"BlockoutSeat":{"path":"Assets/Blockout/Runtime/BlockoutSeat.cs","role":"Blockout chair: one seat point, a runtime occupancy probe and a clamped seated head turn.","source":"// @role Blockout chair: one seat point, a runtime occupancy probe and a clamped seated head turn.\n// @tune eyeHeight:float:0.8-1.8:Eye height above the floor while seated.\n// @tune maxHeadTurn:float:0-180:Degrees the head can turn left or right from the chair's facing.\n\nusing UnityEngine;\n\nnamespace Blockout\n{\n    /// <summary>\n    /// Makes a chair sittable by the BlockoutWalker. Each chair has exactly ONE seat point.\n    ///\n    /// Occupancy is detected at runtime with a small physics probe where a sitter's torso would be,\n    /// so if you move classmates around by hand, the chairs update automatically:\n    ///   - a classmate (or anything else solid) in the seat  -> \"Seat taken\"\n    ///   - the yellow Fig_Seated_Player placeholder          -> sittable; the placeholder hides while you sit\n    /// </summary>\n    public class BlockoutSeat : MonoBehaviour\n    {\n        [Tooltip(\"Where the sitter's feet/pivot go, in the chair's local space (floor level, centre of the seat).\")]\n        public Vector3 localSeatPoint = Vector3.zero;\n\n        [Tooltip(\"Eye height above the floor while seated. 1.25 m = the eye strip on every seated NPC figure.\")]\n        public float eyeHeight = 1.25f;\n\n        [Tooltip(\"How far (degrees) the head can turn left/right from the chair's facing while seated.\")]\n        public float maxHeadTurn = 110f;\n\n        const string PlaceholderPrefix = \"Fig_Seated_Player\";\n\n        public Vector3 SeatPosition { get { return transform.TransformPoint(localSeatPoint); } }\n        public float SeatYaw { get { return transform.eulerAngles.y; } }\n\n        /// <summary>True if someone else is sitting here. Returns the player placeholder (if any) so it can be hidden.</summary>\n        public bool IsTaken(Transform ignore, out GameObject placeholder)\n        {\n            placeholder = null;\n            Vector3 probe = SeatPosition + Vector3.up * 0.8f;   // torso height of a seated figure\n            foreach (Collider c in Physics.OverlapSphere(probe, 0.1f, ~0, QueryTriggerInteraction.Ignore))\n            {\n                if (c.transform.IsChildOf(transform)) continue;\n                if (ignore != null && c.transform.IsChildOf(ignore)) continue;\n                Transform ph = FindParentNamed(c.transform, PlaceholderPrefix);\n                if (ph != null) { placeholder = ph.gameObject; continue; }\n                return true;\n            }\n            return false;\n        }\n\n        static Transform FindParentNamed(Transform t, string prefix)\n        {\n            while (t != null)\n            {\n                if (t.name.StartsWith(prefix)) return t;\n                t = t.parent;\n            }\n            return null;\n        }\n\n        void OnDrawGizmos()\n        {\n            Vector3 p = SeatPosition;\n            Gizmos.color = new Color(1f, 0.8f, 0.1f);\n            Gizmos.DrawWireSphere(p + Vector3.up * 0.45f, 0.08f);\n            Gizmos.DrawLine(p + Vector3.up * 0.45f, p + Vector3.up * eyeHeight);\n            Gizmos.DrawLine(p + Vector3.up * eyeHeight, p + Vector3.up * eyeHeight + transform.forward * 0.4f);\n        }\n    }\n}\n"},"BlockoutWalker":{"path":"Assets/Blockout/Runtime/BlockoutWalker.cs","role":"Blockout first-person walker for playtesting: walk, run, jump, look and sit on BlockoutSeat chairs.","source":"// @role Blockout first-person walker for playtesting: walk, run, jump, look and sit on BlockoutSeat chairs.\n// @calls BlockoutSeat\n// @tune walkSpeed:float:1-8:Walking speed.\n// @tune runSpeed:float:1-12:Running speed with Shift.\n// @tune jumpHeight:float:0-3:Jump height in metres.\n// @tune gravity:float:-40--5:Gravity while walking.\n// @tune eyeStanding:float:0.8-2:Standing eye height.\n// @tune lookSensitivity:float:1-15:Mouse look sensitivity.\n// @tune interactDistance:float:0.5-5:Metres for the look-at chair interaction.\n\nusing UnityEngine;\n#if ENABLE_INPUT_SYSTEM && !ENABLE_LEGACY_INPUT_MANAGER\nusing UnityEngine.InputSystem;\n#endif\n\nnamespace Blockout\n{\n    /// <summary>\n    /// Minimal first-person walker for self-playtesting the blockout \"with full player gravity,\n    /// collision, and speed\" (Level Design Book - Blockout, step 3), instead of only flying.\n    ///\n    /// Collision is 1.0 m wide x 1.8 m tall (book's Unity metrics). Standing eye 1.5 m\n    /// (book: 1.5-1.7 m, games usually sit at the low end).\n    ///\n    /// Look at a chair and press E to SIT: you snap to the chair's single seat point and your eye drops\n    /// to the chair's eyeHeight (1.25 m) - the same height as every seated NPC. Press E again to stand up.\n    ///\n    /// Controls: hold right mouse (or click to lock) = look, Esc = unlock, WASD = move,\n    /// Shift = run, Space = jump, E = sit / stand.\n    /// Works with the old Input Manager or the new Input System package.\n    /// </summary>\n    [RequireComponent(typeof(CharacterController))]\n    public class BlockoutWalker : MonoBehaviour\n    {\n        public Transform eye;\n\n        [Header(\"Movement (m/s)\")]\n        public float walkSpeed = 4f;\n        public float runSpeed = 6.5f;\n        public float jumpHeight = 1.0f;\n        public float gravity = -20f;\n\n        [Header(\"View\")]\n        public float eyeStanding = 1.5f;\n        public float lookSensitivity = 5f;\n\n        [Header(\"Chairs\")]\n        public float interactDistance = 2.5f;\n\n        CharacterController cc;\n        float yaw, pitch, vy;\n\n        BlockoutSeat seat;              // chair we are sitting on (null = standing)\n        BlockoutSeat lookedAtSeat;      // chair under the crosshair\n        bool lookedAtSeatTaken;\n        GameObject hiddenPlaceholder;\n        Vector3 standPosition;\n\n        void Awake()\n        {\n            cc = GetComponent<CharacterController>();\n            yaw = transform.eulerAngles.y;\n            if (eye == null)\n            {\n                Camera c = GetComponentInChildren<Camera>();\n                if (c != null) eye = c.transform;\n            }\n        }\n\n        void OnDisable()\n        {\n            Cursor.lockState = CursorLockMode.None;\n            Cursor.visible = true;\n        }\n\n        void Update()\n        {\n            if (ClickPressed()) { Cursor.lockState = CursorLockMode.Locked; Cursor.visible = false; }\n            if (EscPressed()) { Cursor.lockState = CursorLockMode.None; Cursor.visible = true; }\n\n            // Look while the mouse is locked (click) OR while the right mouse button is held.\n            if (Cursor.lockState == CursorLockMode.Locked || RightHeld())\n            {\n                Vector2 look = LookDelta() * lookSensitivity;\n                yaw += look.x;\n                pitch = Mathf.Clamp(pitch - look.y, -85f, 85f);\n            }\n\n            if (seat != null) UpdateSeated();\n            else UpdateStanding();\n        }\n\n        // ------------------------------------------------------------------ seated\n        void UpdateSeated()\n        {\n            float rel = Mathf.Clamp(Mathf.DeltaAngle(seat.SeatYaw, yaw), -seat.maxHeadTurn, seat.maxHeadTurn);\n            yaw = seat.SeatYaw + rel;\n            transform.rotation = Quaternion.Euler(0f, yaw, 0f);\n            MoveEye(seat.eyeHeight);\n            if (InteractPressed()) StandUp();\n        }\n\n        void SitDown(BlockoutSeat target, GameObject placeholder)\n        {\n            seat = target;\n            standPosition = transform.position;\n            cc.enabled = false;                                   // no collisions while seated\n            transform.position = target.SeatPosition;\n            yaw = target.SeatYaw;\n            pitch = 0f;\n            transform.rotation = Quaternion.Euler(0f, yaw, 0f);\n            vy = 0f;\n            hiddenPlaceholder = placeholder;\n            if (hiddenPlaceholder != null) hiddenPlaceholder.SetActive(false);\n        }\n\n        void StandUp()\n        {\n            transform.position = standPosition;                   // back to where you stood before sitting\n            cc.enabled = true;\n            if (hiddenPlaceholder != null) hiddenPlaceholder.SetActive(true);\n            hiddenPlaceholder = null;\n            seat = null;\n        }\n\n        // ------------------------------------------------------------------ standing\n        void UpdateStanding()\n        {\n            transform.rotation = Quaternion.Euler(0f, yaw, 0f);\n            MoveEye(eyeStanding);\n\n            FindSeatUnderCrosshair();\n            if (InteractPressed() && lookedAtSeat != null && !lookedAtSeatTaken)\n            {\n                GameObject placeholder;\n                lookedAtSeat.IsTaken(transform, out placeholder);\n                SitDown(lookedAtSeat, placeholder);\n                return;\n            }\n\n            Vector2 mv = MoveInput();\n            Vector3 dir = transform.right * mv.x + transform.forward * mv.y;\n            if (dir.sqrMagnitude > 1f) dir.Normalize();\n            float speed = RunHeld() ? runSpeed : walkSpeed;\n\n            if (cc.isGrounded)\n            {\n                vy = -1f;\n                if (JumpPressed()) vy = Mathf.Sqrt(2f * jumpHeight * -gravity);\n            }\n            vy += gravity * Time.deltaTime;\n            cc.Move((dir * speed + Vector3.up * vy) * Time.deltaTime);\n        }\n\n        void FindSeatUnderCrosshair()\n        {\n            lookedAtSeat = null;\n            lookedAtSeatTaken = false;\n            if (eye == null) return;\n\n            RaycastHit hit;\n            if (!Physics.Raycast(eye.position, eye.forward, out hit, interactDistance, ~0, QueryTriggerInteraction.Ignore)) return;\n\n            BlockoutSeat s = hit.collider.GetComponentInParent<BlockoutSeat>();\n            if (s == null)\n            {\n                // Looking at the person sitting in the chair (or the desk)? Pick the nearest chair to the hit point.\n                float best = 0.8f;\n                foreach (Collider c in Physics.OverlapSphere(hit.point, 0.8f, ~0, QueryTriggerInteraction.Ignore))\n                {\n                    BlockoutSeat cand = c.GetComponentInParent<BlockoutSeat>();\n                    if (cand == null) continue;\n                    float d = Vector3.Distance(hit.point, cand.SeatPosition + Vector3.up * 0.6f);\n                    if (d < best) { best = d; s = cand; }\n                }\n            }\n            if (s == null) return;\n\n            GameObject placeholder;\n            lookedAtSeat = s;\n            lookedAtSeatTaken = s.IsTaken(transform, out placeholder);\n        }\n\n        void MoveEye(float height)\n        {\n            if (eye == null) return;\n            eye.localRotation = Quaternion.Euler(pitch, 0f, 0f);\n            Vector3 p = eye.localPosition;\n            p.y = Mathf.MoveTowards(p.y, height, 3f * Time.deltaTime);\n            eye.localPosition = p;\n        }\n\n        // ------------------------------------------------------------------ HUD\n        void OnGUI()\n        {\n            // crosshair\n            GUI.color = Color.white;\n            GUI.Label(new Rect(Screen.width * 0.5f - 5f, Screen.height * 0.5f - 11f, 20f, 22f), \"+\");\n\n            // interaction prompt\n            string prompt = null;\n            if (seat != null) prompt = \"[E] Stand up\";\n            else if (lookedAtSeat != null) prompt = lookedAtSeatTaken ? \"Seat taken\" : \"[E] Sit\";\n            if (prompt != null)\n                GUI.Box(new Rect(Screen.width * 0.5f - 70f, Screen.height * 0.5f + 20f, 140f, 24f), prompt);\n\n            // status (bottom-left, clear of FlyCamera's hint)\n            Camera cam = eye != null ? eye.GetComponent<Camera>() : null;\n            bool camOff = cam == null || !cam.enabled;\n            string status =\n                \"Player Walker (blockout playtest)\\n\" +\n                \"Look: hold RIGHT mouse (or click to lock)   Esc = release   WASD = move   Shift = run   Space = jump   E = sit/stand\\n\" +\n                \"Mouse locked: \" + (Cursor.lockState == CursorLockMode.Locked ? \"YES\" : \"no\") +\n                \"   Grounded: \" + (seat != null ? \"seated\" : (cc != null && cc.isGrounded ? \"yes\" : \"NO\")) +\n                \"   Eye height: \" + (eye != null ? eye.position.y.ToString(\"F2\") : \"-\") + \" m\" +\n                \"   Pos: \" + transform.position.ToString(\"F1\") +\n#if ENABLE_INPUT_SYSTEM && !ENABLE_LEGACY_INPUT_MANAGER\n                \"   Input: new Input System\";\n#else\n                \"   Input: legacy Input Manager\";\n#endif\n            if (camOff)\n                status += \"\\n!! My camera was switched off by another camera script (FlyCamera?). Untick FlyCamera in the Hierarchy.\";\n            float h = camOff ? 92f : 70f;\n            GUI.Box(new Rect(12f, Screen.height - h - 12f, 760f, h), status);\n        }\n\n        // ------------------------------------------------------------------ input\n#if ENABLE_INPUT_SYSTEM && !ENABLE_LEGACY_INPUT_MANAGER\n        static Vector2 MoveInput()\n        {\n            Keyboard k = Keyboard.current;\n            if (k == null) return Vector2.zero;\n            float x = (k.dKey.isPressed ? 1f : 0f) - (k.aKey.isPressed ? 1f : 0f);\n            float y = (k.wKey.isPressed ? 1f : 0f) - (k.sKey.isPressed ? 1f : 0f);\n            return new Vector2(x, y);\n        }\n        static Vector2 LookDelta()\n        {\n            Mouse m = Mouse.current;\n            return m == null ? Vector2.zero : m.delta.ReadValue() * 0.05f;\n        }\n        static bool JumpPressed() { Keyboard k = Keyboard.current; return k != null && k.spaceKey.wasPressedThisFrame; }\n        static bool InteractPressed() { Keyboard k = Keyboard.current; return k != null && k.eKey.wasPressedThisFrame; }\n        static bool RunHeld() { Keyboard k = Keyboard.current; return k != null && k.leftShiftKey.isPressed; }\n        static bool EscPressed() { Keyboard k = Keyboard.current; return k != null && k.escapeKey.wasPressedThisFrame; }\n        static bool ClickPressed() { Mouse m = Mouse.current; return m != null && m.leftButton.wasPressedThisFrame; }\n        static bool RightHeld() { Mouse m = Mouse.current; return m != null && m.rightButton.isPressed; }\n#else\n        static Vector2 MoveInput()\n        {\n            float x = (Input.GetKey(KeyCode.D) ? 1f : 0f) - (Input.GetKey(KeyCode.A) ? 1f : 0f);\n            float y = (Input.GetKey(KeyCode.W) ? 1f : 0f) - (Input.GetKey(KeyCode.S) ? 1f : 0f);\n            return new Vector2(x, y);\n        }\n        static Vector2 LookDelta() { return new Vector2(Input.GetAxis(\"Mouse X\"), Input.GetAxis(\"Mouse Y\")); }\n        static bool JumpPressed() { return Input.GetKeyDown(KeyCode.Space); }\n        static bool InteractPressed() { return Input.GetKeyDown(KeyCode.E); }\n        static bool RunHeld() { return Input.GetKey(KeyCode.LeftShift); }\n        static bool EscPressed() { return Input.GetKeyDown(KeyCode.Escape); }\n        static bool ClickPressed() { return Input.GetMouseButtonDown(0); }\n        static bool RightHeld() { return Input.GetMouseButton(1); }\n#endif\n    }\n}\n"},"BlockoutWaypoint":{"path":"Assets/Blockout/Runtime/BlockoutWaypoint.cs","role":"Blockout patrol stop: wait time and the facing the watcher holds while waiting.","source":"// @role Blockout patrol stop: wait time and the facing the watcher holds while waiting.\n// @tune waitSeconds:float:0-60:Seconds the watcher stands here.\n\nusing UnityEngine;\n\nnamespace Blockout\n{\n    /// <summary>\n    /// One stop on a watcher's patrol route.\n    /// Rotate the waypoint to set where the watcher LOOKS while waiting here.\n    /// A long wait facing away from the class = the player's \"safe window\" (Watch -> Peek -> Act -> Hide).\n    /// </summary>\n    public class BlockoutWaypoint : MonoBehaviour\n    {\n        [Tooltip(\"Seconds the watcher stands here, facing this waypoint's forward (blue Z arrow).\")]\n        public float waitSeconds = 0f;\n\n        [TextArea] public string note = \"\";\n\n        void OnDrawGizmos()\n        {\n            Vector3 p = transform.position + Vector3.up * 0.1f;\n            Gizmos.color = new Color(1f, 0.55f, 0.1f);\n            Gizmos.DrawWireSphere(p, 0.3f);\n            if (waitSeconds > 0f)\n            {\n                Gizmos.color = new Color(1f, 0.25f, 0.2f);\n                Gizmos.DrawLine(p, p + transform.forward * 1.2f);\n            }\n        }\n    }\n}\n"},"DangerFX":{"path":"Assets/Game/Scripts/DangerFX.cs","role":"URP danger feedback: red vignette and chromatic aberration while seen, plus a hard warning flash.","source":"// @role URP danger feedback: red vignette and chromatic aberration while seen, plus a hard warning flash.\n\nusing UnityEngine;\nusing UnityEngine.Rendering;\nusing UnityEngine.Rendering.Universal;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Screen-side danger feedback (URP post-processing, built at runtime):\n    /// a deep-red vignette + chromatic aberration that grow while you are being seen,\n    /// and a hard red flash when a warning is given. Also darkens the screen while lying down.\n    /// </summary>\n    public class DangerFX : MonoBehaviour\n    {\n        [Range(0f, 1f)] public float level;\n        Volume vol;\n        Vignette vig;\n        ChromaticAberration ca;\n        float flash;\n\n        public static DangerFX Create(Transform parent)\n        {\n            GameObject g = new GameObject(\"DangerFX\");\n            g.transform.SetParent(parent, false);\n            return g.AddComponent<DangerFX>();\n        }\n\n        void Awake()\n        {\n            vol = gameObject.AddComponent<Volume>();\n            vol.isGlobal = true;\n            vol.priority = 100f;\n            VolumeProfile p = ScriptableObject.CreateInstance<VolumeProfile>();\n            vig = p.Add<Vignette>(false);\n            vig.color.Override(new Color(0.55f, 0f, 0.02f));\n            vig.intensity.Override(0.52f);\n            vig.smoothness.Override(0.8f);\n            ca = p.Add<ChromaticAberration>(false);\n            ca.intensity.Override(0.75f);\n            vol.sharedProfile = p;\n            vol.weight = 0f;\n        }\n\n        public void Flash() { flash = 1f; }\n\n        void Update()\n        {\n            if (flash > 0f) flash -= Time.unscaledDeltaTime * 1.1f;\n            vol.weight = Mathf.Clamp01(level * level * 0.9f + Mathf.Max(0f, flash));\n        }\n    }\n}\n"},"DeskPuzzle":{"path":"Assets/Game/Scripts/DeskPuzzle.cs","role":"Photos-app desk puzzle: lay the phone in the scratched outline and rotate it until the digits light.","source":"// @role Photos-app desk puzzle: lay the phone in the scratched outline and rotate it until the digits light.\n// @calls GameInput\n// @tune tolerance:float:1-20:Degrees from perfect that still counts as aligned.\n// @tune keyRotateSpeed:float:10-180:Phone rotation speed with A or D.\n// @tune mouseRotate:float:0.5-10:Phone rotation per unit of mouse movement.\n\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Photos-app code puzzle. A phone-shaped outline (with a notch at one end) is scratched into the desk top.\n    /// Lay the phone on the desk and rotate it (A / D or mouse). Only when it sits exactly in the outline,\n    /// notch to notch, does the screen's glow catch the faint scratched digits next to it: 4 3 1 2.\n    /// While the phone lies on the desk the teacher can see it.\n    /// </summary>\n    public class DeskPuzzle : MonoBehaviour\n    {\n        public Transform phoneModel;\n        [Tooltip(\"Renderers of the scratched digits that light up when aligned.\")]\n        public Renderer[] digitRenderers;\n        public Color hiddenColor = new Color(0.62f, 0.52f, 0.38f);\n        public Color litColor = new Color(1f, 0.9f, 0.65f);\n        [Tooltip(\"Degrees from perfect that still counts as aligned.\")]\n        public float tolerance = 4f;\n        public float keyRotateSpeed = 60f;\n        public float mouseRotate = 3f;\n\n        public bool Active { get; private set; }\n        public bool Aligned { get; private set; }\n\n        float yaw;\n        Material digitMat;\n\n        void Awake()\n        {\n            if (phoneModel != null) phoneModel.gameObject.SetActive(false);\n            if (digitRenderers != null && digitRenderers.Length > 0 && digitRenderers[0] != null)\n            {\n                digitMat = new Material(digitRenderers[0].sharedMaterial);   // runtime copy, the asset is never changed\n                foreach (Renderer r in digitRenderers) if (r != null) r.sharedMaterial = digitMat;\n            }\n            SetGlow(0f);\n        }\n\n        public void Begin()\n        {\n            Active = true;\n            yaw = Random.Range(60f, 150f) * (Random.value < 0.5f ? -1f : 1f);\n            if (phoneModel != null) phoneModel.gameObject.SetActive(true);\n            Apply();\n        }\n\n        public void End()\n        {\n            Active = false;\n            Aligned = false;\n            if (phoneModel != null) phoneModel.gameObject.SetActive(false);\n            SetGlow(0f);\n        }\n\n        void Update()\n        {\n            if (!Active) return;\n            float d = 0f;\n            if (GameInput.LeftKeyHeld()) d -= keyRotateSpeed * Time.deltaTime;\n            if (GameInput.RightKeyHeld()) d += keyRotateSpeed * Time.deltaTime;\n            d += GameInput.MouseDelta().x * mouseRotate;\n            yaw = Mathf.Repeat(yaw + d + 180f, 360f) - 180f;\n            Apply();\n        }\n\n        void Apply()\n        {\n            if (phoneModel != null) phoneModel.localRotation = Quaternion.Euler(0f, yaw, 0f);\n            float err = Mathf.Abs(Mathf.DeltaAngle(yaw, 0f));\n            float glow = Mathf.Clamp01(1f - (err - 1f) / 8f);\n            SetGlow(glow * glow);\n            Aligned = err < tolerance;\n        }\n\n        void SetGlow(float t)\n        {\n            if (digitMat == null) return;\n            Color c = Color.Lerp(hiddenColor, litColor, t);\n            if (digitMat.HasProperty(\"_BaseColor\")) digitMat.SetColor(\"_BaseColor\", c);\n            if (digitMat.HasProperty(\"_Color\")) digitMat.SetColor(\"_Color\", c);\n            if (digitMat.HasProperty(\"_EmissionColor\"))\n            {\n                digitMat.EnableKeyword(\"_EMISSION\");\n                digitMat.SetColor(\"_EmissionColor\", litColor * (t * 1.5f));\n            }\n        }\n    }\n}\n"},"EndScreen":{"path":"Assets/Game/Scripts/EndScreen.cs","role":"End-of-chapter page: caught / chapter complete / final ending, with Continue, Retry and Title.","source":"// @role End-of-chapter page: caught / chapter complete / final ending, with Continue, Retry and Title.\n// @calls GameFlow, UIFactory, AmbientAudio, AudioSynth, GameInput\n\nusing System.Collections;\nusing UnityEngine;\nusing UnityEngine.UI;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// The page between chapters (builds its own UI). Reads GameFlow.lastResult / lastLevel / endingChoice.\n    ///  - Caught      -> what happened in that chapter. [Retry chapter] [Title]\n    ///  - Chapter won -> a short \"what you did\". [Continue] [Title]\n    ///  - Last chapter-> ENDING (The Seat / Lights) + epilogue + credits. [Play Again] [Title]\n    /// </summary>\n    public class EndScreen : MonoBehaviour\n    {\n        static readonly Color Paper = new Color(0.93f, 0.90f, 0.82f);\n        static readonly Color Red = new Color(0.86f, 0.18f, 0.14f);\n        static readonly Color Warm = new Color(1f, 0.85f, 0.55f);\n\n        static readonly string[] WinHead = { \"SOMEONE ANSWERED\", \"THE STAIRS GO DOWN\", \"SOMEONE FLASHED BACK\" };\n        static readonly string[] WinBody =\n        {\n            \"The one in front of you is one of them.\\nAfter the bell: the stairwell.\",\n            \"A message, passed hand to hand.\\nThe door marked STAFF was never locked.\\nIt was only watched.\",\n            \"Three lights across the yard.\\nOther dorms. Other rooms. Other phones.\\nYou are not the first. You are not the only.\",\n        };\n        static readonly string[] CaughtHead = { \"CAUGHT\", \"CONFISCATED\", \"LIGHTS OUT\", \"INSPECTED\" };\n        static readonly string[] CaughtBody =\n        {\n            \"Three warnings.\\nThe phone is his now.\",\n            \"The Lunch Monitor files a report.\\nThe stairs stay closed. Lunch continues.\",\n            \"He took it with the flashlight still on your face.\\nSweet dreams.\",\n            \"One item found.\\n\\\"You'll thank me. Just like I was.\\\"\",\n        };\n\n        Text head, body, small;\n        AmbientAudio audioOut;\n\n        void Start()\n        {\n            Time.timeScale = 1f;\n            Cursor.lockState = CursorLockMode.None;\n            Cursor.visible = true;\n            UIFactory.EnsureEventSystem();\n            audioOut = AmbientAudio.Create(transform);\n            audioOut.droneVolume = 0.08f;\n            audioOut.ventVolume = 0.03f;\n\n            int lvl = Mathf.Max(0, GameFlow.LevelIndex(GameFlow.lastLevel));\n            bool won = GameFlow.lastResult == LessonResult.Win;\n            bool final = won && GameFlow.IsLastLevel(GameFlow.lastLevel);\n\n            Canvas canvas = UIFactory.MakeCanvas(\"EndCanvas\", 10);\n            Transform root = canvas.transform;\n            UIFactory.AddImage(UIFactory.Stretch(\"BG\", root), final && GameFlow.endingChoice == 2 ? new Color(0.06f, 0.08f, 0.1f) : new Color(0.05f, 0.05f, 0.055f));\n            Color accent = won ? Warm : Red;\n            UIFactory.AddImage(UIFactory.Rect(\"Bar\", root, new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0.5f, 1f), Vector2.zero, new Vector2(0f, 10f)), accent);\n            Text label = UIFactory.AddText(UIFactory.Centered(\"Label\", root, 0f, 330f, 1600f, 40f), \"\", 24, new Color(0.6f, 0.6f, 0.6f), TextAnchor.MiddleCenter);\n            head = UIFactory.AddText(UIFactory.Centered(\"Headline\", root, 0f, 230f, 1700f, 140f), \"\", 96, accent, TextAnchor.MiddleCenter);\n            head.fontStyle = FontStyle.Bold;\n            body = UIFactory.AddText(UIFactory.Centered(\"Body\", root, 0f, 30f, 1500f, 260f), \"\", 32, Paper, TextAnchor.MiddleCenter);\n            small = UIFactory.AddText(UIFactory.Centered(\"Small\", root, 0f, -150f, 1500f, 110f), \"\", 22, new Color(0.62f, 0.62f, 0.64f), TextAnchor.MiddleCenter);\n            UIFactory.AddText(UIFactory.Rect(\"Footer\", root, new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0f, 30f), new Vector2(1600f, 34f)),\n                \"CLEARVIEW ACADEMY  -  WHAT IS SEEN, IS SAFE.\", 18, new Color(0.7f, 0.22f, 0.2f), TextAnchor.MiddleCenter);\n\n            string h, b, s = \"\";\n            Button primary;\n            if (final)\n            {\n                bool lights = GameFlow.endingChoice == 2;\n                label.text = \"ENDING \" + (lights ? \"2 / 2\" : \"1 / 2\");\n                h = lights ? \"LIGHTS\" : \"THE SEAT\";\n                b = lights\n                    ? \"Every hidden screen in the room lit up at once.\\nThat afternoon, the room at the bottom of the stairs was full.\\nHe closed the door. From the outside.\"\n                    : \"The phone stays behind the panel.\\nNext year, someone new sits in seat thirty-one.\\nThey will find it. They always do.\";\n                s = (lights ? \"The PA said nothing happened today. For once, it was lying.\" : \"What is seen, is safe. What is hidden, is passed on.\")\n                    + \"\\n\\nCOVER  -  a game by Ariel & Nina  -  CGDD 2026\";\n                primary = UIFactory.MakeButton(\"PrimaryButton\", root, \"Play Again\", -220f, -300f, 380f, 90f);\n                primary.onClick.AddListener(GameFlow.StartNewGame);\n                audioOut.Play(lights ? AudioSynth.Confirm() : AudioSynth.Chime(), 0.4f);\n            }\n            else if (won)\n            {\n                label.text = \"CHAPTER \" + (lvl + 1) + \"  COMPLETE\";\n                h = WinHead[Mathf.Clamp(lvl, 0, WinHead.Length - 1)];\n                b = WinBody[Mathf.Clamp(lvl, 0, WinBody.Length - 1)];\n                if (lvl + 1 < GameFlow.LevelTitles.Length) s = \"NEXT:  CHAPTER \" + GameFlow.LevelTitles[lvl + 1];\n                primary = UIFactory.MakeButton(\"PrimaryButton\", root, \"Continue\", -220f, -300f, 380f, 90f);\n                primary.onClick.AddListener(GameFlow.NextLevel);\n                audioOut.Play(AudioSynth.Confirm(), 0.35f);\n            }\n            else\n            {\n                label.text = \"CHAPTER \" + (lvl + 1) + \"  -  GAME OVER\";\n                h = CaughtHead[Mathf.Clamp(lvl, 0, CaughtHead.Length - 1)];\n                b = CaughtBody[Mathf.Clamp(lvl, 0, CaughtBody.Length - 1)];\n                s = \"Try again from the start of this chapter.\";\n                primary = UIFactory.MakeButton(\"PrimaryButton\", root, \"Retry\", -220f, -300f, 380f, 90f);\n                primary.onClick.AddListener(GameFlow.RetryLevel);\n                audioOut.Play(AudioSynth.Stinger(), 0.5f);\n            }\n            Button title = UIFactory.MakeButton(\"TitleButton\", root, \"Title\", 220f, -300f, 380f, 90f);\n            title.onClick.AddListener(GameFlow.GoToTitle);\n            StartCoroutine(Type(h, b, s));\n        }\n\n        IEnumerator Type(string h, string b, string s)\n        {\n            yield return TypeInto(head, h, 18f);\n            yield return new WaitForSeconds(0.25f);\n            yield return TypeInto(body, b, 60f);\n            small.text = s;\n        }\n\n        IEnumerator TypeInto(Text t, string s, float cps)\n        {\n            for (int i = 1; i <= s.Length; i++)\n            {\n                t.text = s.Substring(0, i);\n                if (char.IsLetterOrDigit(s[i - 1]) && i % 2 == 0) audioOut.Play(AudioSynth.Tick(), 0.08f, Random.Range(0.9f, 1.1f));\n                if (GameInput.AnyKeyDown()) { t.text = s; yield break; }\n                yield return new WaitForSeconds(1f / cps);\n            }\n        }\n    }\n}\n"},"Fluorescent":{"path":"Assets/Game/Scripts/Fluorescent.cs","role":"Ceiling fluorescent fixture: light, glowing tube and 3D buzz, with optional flicker.","source":"// @role Ceiling fluorescent fixture: light, glowing tube and 3D buzz, with optional flicker.\n// @calls AudioSynth\n// @tune buzzVolume:float:0-0.2:Tube buzz level.\n// @tune master:float:0-1:Level dimmer for this fixture, 0 = off.\n\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// A ceiling fluorescent fixture: light + glowing tube + 3D buzz.\n    /// \"Flicker\" fixtures (neglected areas) drop out at random, buzz louder and crackle.\n    /// </summary>\n    public class Fluorescent : MonoBehaviour\n    {\n        public Light lightSource;\n        public Renderer tube;\n        public bool flicker;\n        public Color emission = new Color(1.6f, 1.7f, 1.75f);\n        public float buzzVolume = 0.07f;\n        [Tooltip(\"0 = off. Lets a level dim or switch off the lights.\")]\n        [Range(0f, 1f)] public float master = 1f;\n\n        float baseIntensity, level = 1f, offUntil, nextEvent;\n        MaterialPropertyBlock mpb;\n        AudioSource buzz;\n\n        void Awake()\n        {\n            if (lightSource != null) baseIntensity = lightSource.intensity;\n            mpb = new MaterialPropertyBlock();\n            buzz = gameObject.AddComponent<AudioSource>();\n            buzz.clip = AudioSynth.FluorescentHum();\n            buzz.loop = true;\n            buzz.spatialBlend = 1f;\n            buzz.rolloffMode = AudioRolloffMode.Linear;\n            buzz.minDistance = 0.6f;\n            buzz.maxDistance = 7f;\n            buzz.dopplerLevel = 0f;\n            buzz.volume = buzzVolume;\n            buzz.pitch = Random.Range(0.97f, 1.03f);\n            buzz.playOnAwake = false;\n            buzz.time = Random.Range(0f, 1.9f);\n            buzz.Play();\n            nextEvent = Time.time + Random.Range(0.5f, 4f);\n        }\n\n        void Update()\n        {\n            float target = 1f;\n            if (flicker)\n            {\n                if (Time.time > nextEvent)\n                {\n                    // a burst of 1-4 quick drop-outs, then a pause\n                    offUntil = Time.time + Random.Range(0.04f, 0.18f);\n                    nextEvent = Time.time + (Random.value < 0.6f ? Random.Range(0.08f, 0.35f) : Random.Range(1.5f, 6f));\n                }\n                if (Time.time < offUntil) target = Random.value < 0.3f ? 0.25f : 0.02f;\n            }\n            level = target;\n            float k = level * master;\n            if (lightSource != null) lightSource.intensity = baseIntensity * k;\n            if (tube != null)\n            {\n                tube.GetPropertyBlock(mpb);\n                mpb.SetColor(\"_EmissionColor\", emission * k);\n                tube.SetPropertyBlock(mpb);\n            }\n            buzz.volume = buzzVolume * master * (flicker && level < 0.5f ? 2.2f : 1f);\n        }\n    }\n}\n"},"Footsteps":{"path":"Assets/Game/Scripts/Footsteps.cs","role":"3D footsteps for walkers, with an optional key jingle every few steps.","source":"// @role 3D footsteps for walkers, with an optional key jingle every few steps.\n// @calls AudioSynth\n// @tune stepLength:float:0.2-1.5:Metres travelled per footstep.\n// @tune volume:float:0-1:Footstep volume.\n// @tune pitch:float:0.5-1.5:Pitch of the footsteps.\n// @tune minDistance:float:0-5:Distance where footsteps are at full volume.\n// @tune maxDistance:float:2-30:Distance where footsteps fade out.\n// @tune keysEverySteps:int:0-10:Steps between key jingles, 0 = never.\n\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Footsteps (3D) for anyone who walks: you can hear where the teacher / monitor / warden is.\n    /// Optional key jingle every few steps (the night warden).\n    /// </summary>\n    public class Footsteps : MonoBehaviour\n    {\n        public float stepLength = 0.7f;\n        public float volume = 0.55f;\n        public float pitch = 1f;\n        public float minDistance = 1.5f;\n        public float maxDistance = 18f;\n        [Tooltip(\"0 = never. Otherwise a key jingle every N steps.\")]\n        public int keysEverySteps = 0;\n\n        AudioSource src;\n        AudioClip[] clips;\n        Vector3 last;\n        float acc;\n        int count;\n\n        void Awake()\n        {\n            src = gameObject.AddComponent<AudioSource>();\n            src.spatialBlend = 1f;\n            src.rolloffMode = AudioRolloffMode.Linear;\n            src.minDistance = minDistance;\n            src.maxDistance = maxDistance;\n            src.dopplerLevel = 0f;\n            src.playOnAwake = false;\n            clips = AudioSynth.Steps();\n            last = Flat(transform.position);\n        }\n\n        static Vector3 Flat(Vector3 v) { v.y = 0f; return v; }\n\n        void Update()\n        {\n            Vector3 p = Flat(transform.position);\n            float d = Vector3.Distance(p, last);\n            last = p;\n            if (d > 1f) return;   // teleported\n            acc += d;\n            if (acc < stepLength) return;\n            acc = 0f;\n            count++;\n            src.pitch = pitch * Random.Range(0.92f, 1.08f);\n            src.PlayOneShot(clips[Random.Range(0, clips.Length)], volume);\n            if (keysEverySteps > 0 && count % keysEverySteps == 0) src.PlayOneShot(AudioSynth.Keys(), volume * 0.6f);\n        }\n\n        /// <summary>Play a one-shot from this person's position (door creak, keys...).</summary>\n        public void PlayAt(AudioClip clip, float vol)\n        {\n            if (src != null && clip != null) src.PlayOneShot(clip, vol);\n        }\n    }\n}\n"},"GameFlow":{"path":"Assets/Game/Scripts/GameFlow.cs","role":"Scene-to-scene flow, chapter progress, endings and the player's saved name.","source":"// @role Scene-to-scene flow, chapter progress, endings and the player's saved name.\n\nusing UnityEngine;\nusing UnityEngine.SceneManagement;\n\nnamespace PhoneGame\n{\n    public enum LessonResult { None, Win, Caught, TimeUp }\n\n    /// <summary>\n    /// Scene-to-scene flow. Static, so it survives scene loads without a DontDestroyOnLoad object.\n    /// Title -> Chapter 1..4 -> End (after every chapter: win = Continue, caught = Retry this chapter).\n    /// The last chapter has two endings (endingChoice 1 = THE SEAT, 2 = LIGHTS).\n    /// Progress (highest chapter reached + the player's name) is saved in PlayerPrefs.\n    /// </summary>\n    public static class GameFlow\n    {\n        public const string TitleScene = \"Title\";\n        public const string EndScene = \"End\";\n        public static readonly string[] Levels = { \"Level01_Lesson\", \"Level02_Lunch\", \"Level03_LightsOut\", \"Level04_Inspector\" };\n        public static readonly string[] LevelTitles = { \"1   THE LESSON\", \"2   LUNCH\", \"3   LIGHTS OUT\", \"4   INSPECTION DAY\" };\n\n        public static bool skipIntro;\n        /// <summary>Typed on the title page. The teacher uses it in the roll call and when he calls on you.</summary>\n        public static string playerName = \"Student\";\n        public static LessonResult lastResult = LessonResult.None;\n        public static string lastLevel = \"Level01_Lesson\";\n        public static string lastReason = \"\";\n        /// <summary>0 = not finished, 1 = \"The Seat\" (hid it), 2 = \"Lights\" (sent it to everyone).</summary>\n        public static int endingChoice;\n\n        const string KeyReached = \"cover_reached\";\n        const string KeyName = \"cover_name\";\n        static bool nameLoaded;\n\n        public static void LoadSavedName()\n        {\n            if (nameLoaded) return;\n            nameLoaded = true;\n            string n = PlayerPrefs.GetString(KeyName, \"\");\n            if (!string.IsNullOrEmpty(n)) playerName = n;\n        }\n\n        /// <summary>Highest chapter index (0-based) the player may start from.</summary>\n        public static int ReachedLevel\n        {\n            get { return Mathf.Clamp(PlayerPrefs.GetInt(KeyReached, 0), 0, Levels.Length - 1); }\n            set { PlayerPrefs.SetInt(KeyReached, Mathf.Clamp(value, 0, Levels.Length - 1)); PlayerPrefs.Save(); }\n        }\n\n        public static void SaveName(string n)\n        {\n            playerName = string.IsNullOrEmpty(n) ? \"Student\" : n;\n            nameLoaded = true;\n            PlayerPrefs.SetString(KeyName, playerName);\n            PlayerPrefs.Save();\n        }\n\n        public static int LevelIndex(string scene) { return System.Array.IndexOf(Levels, scene); }\n        public static bool IsLastLevel(string scene) { return LevelIndex(scene) == Levels.Length - 1; }\n\n        public static void StartNewGame()\n        {\n            ReachedLevel = 0;\n            LoadLevel(0);\n        }\n\n        public static void ContinueGame() { LoadLevel(ReachedLevel); }\n\n        public static void LoadLevel(int i)\n        {\n            LoadSavedName();\n            skipIntro = false;\n            endingChoice = 0;\n            Load(Levels[Mathf.Clamp(i, 0, Levels.Length - 1)]);\n        }\n\n        /// <summary>After a win: the next chapter.</summary>\n        public static void NextLevel()\n        {\n            int i = LevelIndex(lastLevel);\n            if (i < 0 || i >= Levels.Length - 1) { GoToTitle(); return; }\n            LoadLevel(i + 1);\n        }\n\n        /// <summary>Inside-style: back to the start of the SAME chapter.</summary>\n        public static void RetryLevel()\n        {\n            skipIntro = true;\n            endingChoice = 0;\n            Load(lastLevel);\n        }\n\n        public static void GoToTitle() { Load(TitleScene); }\n\n        public static void EndLevel(LessonResult result, string reason)\n        {\n            lastResult = result;\n            lastReason = reason;\n            lastLevel = SceneManager.GetActiveScene().name;\n            int i = LevelIndex(lastLevel);\n            if (result == LessonResult.Win && i >= 0 && i + 1 < Levels.Length && ReachedLevel < i + 1) ReachedLevel = i + 1;\n            Load(EndScene);\n        }\n\n        static void Load(string scene)\n        {\n            Time.timeScale = 1f;\n            AudioListener.volume = 1f;\n            SceneManager.LoadScene(scene);\n        }\n    }\n}\n"},"GameInput":{"path":"Assets/Game/Scripts/GameInput.cs","role":"One input facade for the old Input Manager and the new Input System.","source":"// @role One input facade for the old Input Manager and the new Input System.\n\nusing UnityEngine;\n#if ENABLE_INPUT_SYSTEM && !ENABLE_LEGACY_INPUT_MANAGER\nusing UnityEngine.InputSystem;\nusing UnityEngine.InputSystem.Controls;\n#endif\n\nnamespace PhoneGame\n{\n    /// <summary>One place for all input, so it works with the old Input Manager or the new Input System.</summary>\n    public static class GameInput\n    {\n#if ENABLE_INPUT_SYSTEM && !ENABLE_LEGACY_INPUT_MANAGER\n        static Keyboard K { get { return Keyboard.current; } }\n        static Mouse Ms { get { return Mouse.current; } }\n        static bool Down(KeyControl k) { return k != null && k.wasPressedThisFrame; }\n        static bool Held(KeyControl k) { return k != null && k.isPressed; }\n\n        public static Vector2 MouseDelta() { return Ms == null ? Vector2.zero : Ms.delta.ReadValue() * 0.05f; }\n        public static bool RightHeld() { return Ms != null && Ms.rightButton.isPressed; }\n        public static bool LeftHeld() { return Ms != null && Ms.leftButton.isPressed; }\n        public static bool LeftDown() { return Ms != null && Ms.leftButton.wasPressedThisFrame; }\n        public static float Scroll() { return Ms == null ? 0f : Mathf.Clamp(Ms.scroll.ReadValue().y, -1f, 1f); }\n        public static Vector2 Move()\n        {\n            if (K == null) return Vector2.zero;\n            float x = (Held(K.dKey) ? 1f : 0f) - (Held(K.aKey) ? 1f : 0f);\n            float y = (Held(K.wKey) ? 1f : 0f) - (Held(K.sKey) ? 1f : 0f);\n            return new Vector2(x, y);\n        }\n        public static bool InteractDown() { return K != null && Down(K.eKey); }\n        public static bool BackDown() { return K != null && Down(K.qKey); }\n        public static bool SpaceDown() { return K != null && Down(K.spaceKey); }\n        public static bool SpaceHeld() { return K != null && Held(K.spaceKey); }\n        public static bool AnyKeyDown() { return (K != null && K.anyKey.wasPressedThisFrame) || LeftDown(); }\n        public static bool LeftKeyDown() { return K != null && (Down(K.aKey) || Down(K.leftArrowKey)); }\n        public static bool RightKeyDown() { return K != null && (Down(K.dKey) || Down(K.rightArrowKey)); }\n        public static bool LeftKeyHeld() { return K != null && (Held(K.aKey) || Held(K.leftArrowKey)); }\n        public static bool RightKeyHeld() { return K != null && (Held(K.dKey) || Held(K.rightArrowKey)); }\n        public static bool BackspaceDown() { return K != null && Down(K.backspaceKey); }\n        public static bool EnterDown() { return K != null && (Down(K.enterKey) || Down(K.numpadEnterKey)); }\n        public static bool EscDown() { return K != null && Down(K.escapeKey); }\n        public static bool RunHeld() { return K != null && Held(K.leftShiftKey); }\n        /// <summary>Playtest shortcut: skip the current chapter.</summary>\n        public static bool SkipDown() { return K != null && Down(K.f8Key); }\n\n        /// <summary>Digit pressed this frame (top row or numpad), or -1.</summary>\n        public static int DigitDown()\n        {\n            if (K == null) return -1;\n            KeyControl[] top = { K.digit0Key, K.digit1Key, K.digit2Key, K.digit3Key, K.digit4Key, K.digit5Key, K.digit6Key, K.digit7Key, K.digit8Key, K.digit9Key };\n            KeyControl[] pad = { K.numpad0Key, K.numpad1Key, K.numpad2Key, K.numpad3Key, K.numpad4Key, K.numpad5Key, K.numpad6Key, K.numpad7Key, K.numpad8Key, K.numpad9Key };\n            for (int i = 0; i < 10; i++) if (Down(top[i]) || Down(pad[i])) return i;\n            return -1;\n        }\n#else\n        public static Vector2 MouseDelta() { return new Vector2(Input.GetAxis(\"Mouse X\"), Input.GetAxis(\"Mouse Y\")); }\n        public static bool RightHeld() { return Input.GetMouseButton(1); }\n        public static bool LeftHeld() { return Input.GetMouseButton(0); }\n        public static bool LeftDown() { return Input.GetMouseButtonDown(0); }\n        public static float Scroll() { return Input.mouseScrollDelta.y; }\n        public static Vector2 Move()\n        {\n            float x = (Input.GetKey(KeyCode.D) ? 1f : 0f) - (Input.GetKey(KeyCode.A) ? 1f : 0f);\n            float y = (Input.GetKey(KeyCode.W) ? 1f : 0f) - (Input.GetKey(KeyCode.S) ? 1f : 0f);\n            return new Vector2(x, y);\n        }\n        public static bool InteractDown() { return Input.GetKeyDown(KeyCode.E); }\n        public static bool BackDown() { return Input.GetKeyDown(KeyCode.Q); }\n        public static bool SpaceDown() { return Input.GetKeyDown(KeyCode.Space); }\n        public static bool SpaceHeld() { return Input.GetKey(KeyCode.Space); }\n        public static bool AnyKeyDown() { return Input.anyKeyDown; }\n        public static bool LeftKeyDown() { return Input.GetKeyDown(KeyCode.A) || Input.GetKeyDown(KeyCode.LeftArrow); }\n        public static bool RightKeyDown() { return Input.GetKeyDown(KeyCode.D) || Input.GetKeyDown(KeyCode.RightArrow); }\n        public static bool LeftKeyHeld() { return Input.GetKey(KeyCode.A) || Input.GetKey(KeyCode.LeftArrow); }\n        public static bool RightKeyHeld() { return Input.GetKey(KeyCode.D) || Input.GetKey(KeyCode.RightArrow); }\n        public static bool BackspaceDown() { return Input.GetKeyDown(KeyCode.Backspace); }\n        public static bool EnterDown() { return Input.GetKeyDown(KeyCode.Return) || Input.GetKeyDown(KeyCode.KeypadEnter); }\n        public static bool EscDown() { return Input.GetKeyDown(KeyCode.Escape); }\n        public static bool RunHeld() { return Input.GetKey(KeyCode.LeftShift); }\n        /// <summary>Playtest shortcut: skip the current chapter.</summary>\n        public static bool SkipDown() { return Input.GetKeyDown(KeyCode.F8); }\n\n        /// <summary>Digit pressed this frame (top row or numpad), or -1.</summary>\n        public static int DigitDown()\n        {\n            for (int i = 0; i < 10; i++)\n            {\n                if (Input.GetKeyDown(KeyCode.Alpha0 + i) || Input.GetKeyDown(KeyCode.Keypad0 + i)) return i;\n            }\n            return -1;\n        }\n#endif\n    }\n}\n"},"HumSource":{"path":"Assets/Game/Scripts/HumSource.cs","role":"The student who hums an off-key anthem: a positional sound you find her by.","source":"// @role The student who hums an off-key anthem: a positional sound you find her by.\n// @calls AudioSynth\n// @tune volume:float:0-1:Humming volume.\n// @tune maxDistance:float:1-15:Distance where the humming fades out.\n\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>A student humming an off-key anthem - you find her by listening.</summary>\n    public class HumSource : MonoBehaviour\n    {\n        public float volume = 0.8f;\n        public float maxDistance = 6.5f;\n        AudioSource src;\n\n        void Awake()\n        {\n            src = gameObject.AddComponent<AudioSource>();\n            src.clip = AudioSynth.HumMelody();\n            src.loop = true;\n            src.spatialBlend = 1f;\n            src.rolloffMode = AudioRolloffMode.Linear;\n            src.minDistance = 0.8f;\n            src.maxDistance = maxDistance;\n            src.dopplerLevel = 0f;\n            src.volume = volume;\n            src.playOnAwake = false;\n            src.Play();\n        }\n\n        public bool Humming { get { return src != null && src.isPlaying; } }\n\n        public void StopHumming()\n        {\n            if (src != null) src.Stop();\n        }\n    }\n}\n"},"Interactable":{"path":"Assets/Game/Scripts/Interactable.cs","role":"Something the player can look at and use with E: prompt, active flag and use callback.","source":"// @role Something the player can look at and use with E: prompt, active flag and use callback.\n\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Something the player can use by looking at it (crosshair) and pressing E.\n    /// The level director sets prompt / active / onUse.\n    /// </summary>\n    public class Interactable : MonoBehaviour\n    {\n        public string prompt = \"Use\";\n        public bool active = true;\n        public System.Action onUse;\n    }\n}\n"},"LessonLine":{"path":"Assets/Game/Scripts/LessonScript.cs","role":"Lesson text data: what the teacher says and the questions he may ask about it.","source":"// @role Lesson text data: what the teacher says and the questions he may ask about it.\n\nusing System.Collections.Generic;\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// What the teacher says, and what he may ask. Questions are only asked about things he has\n    /// ALREADY said - so listening to him matters. Edit freely in the Inspector (on the Teacher).\n    /// </summary>\n    [System.Serializable]\n    public class LessonLine\n    {\n        [TextArea] public string text;\n        public LessonLine(string t) { text = t; }\n    }\n\n    [System.Serializable]\n    public class LessonQuestion\n    {\n        [Tooltip(\"Index of the lesson line this question is about. -1 = can be asked any time.\")]\n        public int aboutLine = -1;\n        [TextArea] public string question;\n        public string[] options = new string[3];\n        [Tooltip(\"0, 1 or 2\")]\n        public int correct;\n\n        public LessonQuestion(int line, string q, string a, string b, string c, int right)\n        {\n            aboutLine = line; question = q; options = new[] { a, b, c }; correct = right;\n        }\n    }\n\n    public static class LessonDefaults\n    {\n        // The phone code is the founding year (line 1); the Photos code is lights-out on a 24-hour clock (line 5).\n        public static List<LessonLine> Lines()\n        {\n            return new List<LessonLine>\n            {\n                new LessonLine(\"Today we continue with the Founding Charter of our school.\"),\n                new LessonLine(\"Our school was founded in 1952. Nineteen fifty-two. Far away from the noise of the city.\"),\n                new LessonLine(\"The Charter has four rules. Rule one: what is seen, is safe.\"),\n                new LessonLine(\"Every device in this building is monitored. That is how we keep you safe.\"),\n                new LessonLine(\"Rule two: no voice leaves these walls.\"),\n                new LessonLine(\"Rule three: lights out is at nine. Twenty-one hundred. Exactly.\"),\n                new LessonLine(\"The pigeons in the courtyard are not monitored. ...Yet.\"),\n                new LessonLine(\"The founder planted the oak tree in the courtyard on the very first day.\"),\n                new LessonLine(\"Seven classes. Seven bells. Every single day.\"),\n                new LessonLine(\"Whoever drew a moustache on the founder's portrait: I know you are left-handed.\"),\n                new LessonLine(\"Rule four: we do not keep things from each other.\"),\n                new LessonLine(\"A quiet room is a good room. Remember that.\"),\n                new LessonLine(\"And the back row, by the window... I sat in that seat once. Before you. Before all of you.\"),\n            };\n        }\n\n        /// <summary>Chapter 4 - Inspection Day. Same teacher, same rhythm; he finally says who he is.</summary>\n        public static List<LessonLine> InspectionLines()\n        {\n            return new List<LessonLine>\n            {\n                new LessonLine(\"Inspection Day was established in 1953. One year after our founding.\"),\n                new LessonLine(\"The Charter's first rule: what is seen, is safe.\"),\n                new LessonLine(\"An inspected desk is a happy desk.\"),\n                new LessonLine(\"Last year we found four hundred and twelve forbidden items. All of them are safe now.\"),\n                new LessonLine(\"I have taught in this room for thirty-one years. I sat in it before that.\"),\n                new LessonLine(\"There is nothing in this school I have not seen.\"),\n                new LessonLine(\"Rule four: we do not keep things from each other. It is my favourite rule.\"),\n                new LessonLine(\"Some of you think you are the first. You are never the first.\"),\n            };\n        }\n\n        public static List<LessonQuestion> InspectionQuestions()\n        {\n            return new List<LessonQuestion>\n            {\n                new LessonQuestion(-1, \"What is six times seven?\", \"42\", \"36\", \"48\", 0),\n                new LessonQuestion(0, \"When was Inspection Day established?\", \"1952\", \"1953\", \"1979\", 1),\n                new LessonQuestion(2, \"An inspected desk is a...?\", \"Happy desk\", \"Safe desk\", \"Clean desk\", 0),\n                new LessonQuestion(3, \"How many forbidden items were found last year?\", \"214\", \"421\", \"412\", 2),\n                new LessonQuestion(4, \"How long has he taught in this room?\", \"13 years\", \"31 years\", \"30 years\", 1),\n                new LessonQuestion(6, \"Which rule is his favourite?\", \"Rule one\", \"Rule two\", \"Rule four\", 2),\n            };\n        }\n\n        public static List<LessonQuestion> Questions()\n        {\n            return new List<LessonQuestion>\n            {\n                new LessonQuestion(-1, \"What is six plus seven?\", \"11\", \"13\", \"15\", 1),\n                new LessonQuestion(1, \"In what year was our school founded?\", \"1925\", \"1962\", \"1952\", 2),\n                new LessonQuestion(2, \"What is Rule one of the Charter?\", \"What is seen, is safe\", \"Silence is golden\", \"Hands on the desk\", 0),\n                new LessonQuestion(5, \"When is lights out?\", \"22:00\", \"21:00\", \"20:00\", 1),\n                new LessonQuestion(7, \"What did the founder plant in the courtyard?\", \"An oak tree\", \"A pine tree\", \"A rose garden\", 0),\n                new LessonQuestion(8, \"How many bells ring every day?\", \"Five\", \"Nine\", \"Seven\", 2),\n                new LessonQuestion(4, \"What is Rule two?\", \"No voice leaves these walls\", \"No running in the halls\", \"No phones after nine\", 0),\n                new LessonQuestion(6, \"Which of these is NOT monitored?\", \"The library\", \"The courtyard pigeons\", \"The hallway\", 1),\n            };\n        }\n    }\n}\n"},"Level01Director":{"path":"Assets/Game/Scripts/Level01Director.cs","role":"Chapter 1 The Lesson: walk in, roll call, search the desk, decode the phone and tap the triangle student.","source":"// @role Chapter 1 The Lesson: walk in, roll call, search the desk, decode the phone and tap the triangle student.\n// @calls LevelDirectorBase, TeacherAI, TeacherVision, PlayerRig, PhoneController, Interactable, LessonLine, GameInput\n// @tune answerSeconds:float:5-30:Seconds to answer a question.\n// @tune callInterval:Vector2:20-90:Seconds between questions (x to y).\n// @tune firstCallAtBootSecond:float:1-10:Seconds into the phone boot for the first question.\n\nusing System.Collections;\nusing System.Collections.Generic;\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Chapter 1 \"The Lesson\".\n    ///  1. Hallway: the teacher calls you in. Walking through the door you are pulled to your seat while the\n    ///     class turns to stare. No control during the walk.\n    ///  2. ROLL CALL: the teacher reads names (yours too - answer with 1). Between names, the player's\n    ///     thoughts quietly explain the rules (devices monitored, random questions, three warnings, the desk).\n    ///  3. Desk cubby -> books -> loose back panel -> the old phone.\n    ///  4. Codes come from numbers the teacher says: founding year 1952 (phone), lights-out 21:00 -> 2100 (Photos).\n    ///  5. A photo shows the sign of the student in front of you -> tap their shoulder -> WIN.\n    ///  Only ONE subtitle is on screen at a time: teacher (top) OR thought (bottom-left).\n    ///  Danger: while he can see the phone, the phone shakes and turns red. Full = a warning.\n    ///  Three warnings, never shown as UI - the teacher says so. Third: he takes the phone (LOSE).\n    /// </summary>\n    public class Level01Director : LevelDirectorBase\n    {\n        [Header(\"Scene references (filled by the scene builder)\")]\n        public TeacherAI teacher;\n        public TeacherVision vision;\n        public Transform seatPoint;\n        public Interactable cubbyZone, books, loosePanel, hiddenPhone, frontStudent;\n        [Tooltip(\"The chair of the student in front - they turn around together with it.\")]\n        public Transform frontChair;\n        public Transform takePhoneStandPoint;\n        [Tooltip(\"The school bell at the very start.\")]\n        public AudioClip bellClip;\n\n        [Header(\"Classroom doors (x min, z min, x max, z max) - entering one pulls you to your seat\")]\n        public Vector4 backDoorZone = new Vector4(8.6f, 0f, 9.95f, 2.2f);\n        public Vector4 frontDoorZone = new Vector4(8.6f, 9.8f, 9.95f, 12f);\n        public float sideAisleX = 9.3f;\n        public float backAisleZ = 1.0f;\n\n        [Header(\"Questions\")]\n        public float answerSeconds = 10f;\n        public Vector2 callInterval = new Vector2(35f, 60f);\n        [Tooltip(\"The first question always comes this many seconds into the first phone start-up.\")]\n        public float firstCallAtBootSecond = 3f;\n\n        [Header(\"Roll call (the player's name goes after these)\")]\n        public string[] namesBefore = { \"Emily Carter\", \"Daniel Brooks\", \"Sophie Turner\" };\n        public string[] namesAfter = { \"Lucas Reed\" };\n\n        float nextCall = -1f;\n        bool seated, calling, rollCall, bootCallDone, cubbySearched, toldAboutDanger, staring;\n        LessonQuestion question;\n        float callTimer;\n        int linesSaid = -1;\n        readonly List<int> asked = new List<int>();\n        readonly List<Transform> classmates = new List<Transform>();\n        readonly List<Quaternion> classmateRest = new List<Quaternion>();\n        Coroutine lecture;\n\n        // ------------------------------------------------------------------ setup\n        protected override void Awake()\n        {\n            base.Awake();\n            authorityLabel = \"TEACHER\";\n            authorityPitch = 0.8f;\n            if (phone != null) { phone.hasPhone = false; phone.allowRaise = false; phone.phoneClock = \"09:05\"; }\n            SetupDesk();\n            foreach (Transform t in FindObjectsByType<Transform>(FindObjectsInactive.Exclude, FindObjectsSortMode.None))\n            {\n                if (!t.name.StartsWith(\"Fig_Classmate_Seated\")) continue;\n                classmates.Add(t);\n                classmateRest.Add(t.rotation);\n            }\n        }\n\n        protected override void Start()\n        {\n            base.Start();\n            if (teacher != null) teacher.Begin();\n            StartCoroutine(Opening());\n        }\n\n        void SetupDesk()\n        {\n            if (cubbyZone != null)\n            {\n                cubbyZone.prompt = \"Search your desk\";\n                cubbyZone.active = false;   // unlocked after the roll call\n                cubbyZone.onUse = () => { rig.EnterInspect(); SetZone(false); cubbySearched = true; };\n            }\n            if (books != null) { books.prompt = \"Move the books aside\"; books.onUse = () => StartCoroutine(MoveBooks()); }\n            if (loosePanel != null) { loosePanel.prompt = \"The back panel is loose - pull it out\"; loosePanel.active = false; loosePanel.onUse = () => StartCoroutine(PullPanel()); }\n            if (hiddenPhone != null) { hiddenPhone.prompt = \"Take the phone\"; hiddenPhone.active = false; hiddenPhone.onUse = TakePhone; }\n            if (frontStudent != null) { frontStudent.prompt = \"Tap their shoulder twice\"; frontStudent.active = false; frontStudent.onUse = () => StartCoroutine(StudentTurns()); }\n        }\n\n        void SetZone(bool on)\n        {\n            if (cubbyZone == null) return;\n            foreach (Collider c in cubbyZone.GetComponents<Collider>()) c.enabled = on;\n        }\n\n        protected override bool ReminderBlocked() { return calling || rollCall; }\n\n        // ------------------------------------------------------------------ main loop\n        protected override void LevelAlways() { UpdateStare(); }\n\n        protected override void LevelUpdate()\n        {\n            if (rig.CurrentMode == PlayerRig.Mode.Walk && EnteredClassroom(rig.transform.position)) BeginPull();\n\n            phone.allowRaise = rig.CurrentMode == PlayerRig.Mode.Seated && phone.hasPhone;\n            if (phone.hasPhone && phone.RaisedOnce && !toldAboutDanger)\n            {\n                toldAboutDanger = true;\n                Thought(\"If he can see it, \" + Rule(\"the phone shakes and turns red\") + \".\\nKeep it out of his sight.\");\n            }\n\n            UpdateObjective();\n            UpdateInteraction();\n            UpdateDanger();\n            UpdateCalls();\n        }\n\n        void UpdateObjective()\n        {\n            if (rig.CurrentMode == PlayerRig.Mode.Walk) { SetObjective(\"Walk into the classroom.\\n(W + mouse)\"); return; }\n            if (!seated) { SetObjective(\"\"); return; }\n            if (rollCall) { SetObjective(\"Roll call.\\nPress 1 when YOUR name is called.\"); return; }\n            if (!phone.hasPhone) { SetObjective(\"Search your desk.\\nLook down at the cubby and press E.\"); return; }\n            if (!phone.IsUnlocked(PhoneController.AppPhotos)) { SetObjective(\"Sit up, HOLD RIGHT MOUSE.\\nPhone code = the year the school was founded. Then PHOTOS = lights out (24-hour clock).\"); return; }\n            if (!phone.ClueFound) { SetObjective(\"Look through PHOTOS (A / D).\\nOne of them shows a mark you can find in this room.\"); return; }\n            SetObjective(\"Tap the shoulder of the student\\nwith the chalk triangle (E).\");\n        }\n\n        bool EnteredClassroom(Vector3 p) { return In(p, backDoorZone) || In(p, frontDoorZone); }\n        static bool In(Vector3 p, Vector4 r) { return p.x >= r.x && p.x <= r.z && p.z >= r.y && p.z <= r.w; }\n\n        // ------------------------------------------------------------------ opening & walk in\n        IEnumerator Opening()\n        {\n            // quick start: he calls you in almost immediately; you can walk once he has spoken\n            rig.Lock();\n            caption.text = \"MONDAY.  FIRST PERIOD.\";\n            if (bellClip != null) ambient.Play(bellClip, 0.85f);\n            StartCoroutine(Fade(1f, 0f, 1.2f));\n            yield return new WaitForSeconds(bellClip != null ? 2.6f : 0.5f);\n            Authority(\"(from inside the classroom)  ...The bell has rung. Whoever is standing at the door. In. Now.\", 4.5f, true, 0.3f);\n            yield return new WaitForSeconds(1.2f);\n            caption.text = \"\";\n            if (rig.CurrentMode == PlayerRig.Mode.Locked && !seated) rig.AllowWalk();\n            Thought(\"Late. Everyone is going to stare.\\nW + mouse: walk into the classroom\", 30f, false, 0.3f);\n        }\n\n        void BeginPull()\n        {\n            Vector3 p = rig.transform.position;\n            Vector3 s = seatPoint.position;\n            Vector3[] path =\n            {\n                new Vector3(sideAisleX, p.y, Mathf.Clamp(p.z, backAisleZ, 11f)),\n                new Vector3(sideAisleX, p.y, backAisleZ),\n                new Vector3(s.x + 0.8f, p.y, backAisleZ),\n                new Vector3(s.x, p.y, backAisleZ + 0.15f),\n                s,\n            };\n            rig.pullLookYaw = seatPoint.eulerAngles.y;\n            rig.PullToSeat(path, s, seatPoint.eulerAngles.y, OnSeated);\n            staring = true;\n            if (teacher != null) teacher.CallOn(rig.transform);\n            // short gaps here - these lines play while you are being walked to your seat\n            Authority(\"You're late, \" + Name + \".\", 2.8f, true, 0.3f);\n            Authority(\"Everyone has been waiting for you.\", 3f, false, 0.3f);\n            Authority(\"Sit.\", 2f, false, 0.5f);\n        }\n\n        void OnSeated()\n        {\n            seated = true;\n            StartCoroutine(RollCall());\n        }\n\n        // ------------------------------------------------------------------ roll call (rules told through thoughts)\n        IEnumerator RollCall()\n        {\n            rollCall = true;\n            yield return WaitIdle();\n            yield return new WaitForSeconds(0.6f);\n            staring = false;\n\n            Authority(\"Roll call. Answer when you hear your name.\", 5f);\n            yield return RollName(namesBefore.Length > 0 ? namesBefore[0] : null);\n            Thought(Rule(\"Every device in this school is monitored.\") + \"\\nIf he sees a phone, he takes it.\", 8.5f);\n            yield return RollName(namesBefore.Length > 1 ? namesBefore[1] : null);\n            Thought(\"He calls on people at random.\\n\" + Rule(\"Listen to him\") + \" - he only asks about what he has said.\", 8.5f);\n            yield return RollName(namesBefore.Length > 2 ? namesBefore[2] : null);\n            Thought(\"The older kids say he gives \" + Rule(\"three warnings\") + \".\\nAfter the third, he takes whatever you're hiding.\", 9f);\n            yield return WaitIdle();\n\n            // the player's own name\n            bool answered = false;\n            for (int attempt = 0; attempt < 2 && !answered && !ended; attempt++)\n            {\n                Authority(attempt == 0 ? Name + \".\" : Name + \". I said your name.\", 99f, true);\n                ShowQuestion(\"Your name was called.\\n\\n1    \\\"Here.\\\"\");\n                float t = 0f;\n                while (t < answerSeconds && !answered)\n                {\n                    t += Time.deltaTime;\n                    questionTimer.rectTransform.anchorMax = new Vector2(1f - t / answerSeconds, 1f);\n                    questionStatus.text = phone.IsExposed ? \"Put the phone down first!\" : \"Press 1\";\n                    if (!phone.IsExposed && GameInput.DigitDown() == 1) answered = true;\n                    yield return null;\n                }\n                questionBox.SetActive(false);\n                ClearLine();\n            }\n            if (answered) { StudentSay(Name, \"Here.\", 2.5f); Authority(\"...Late, and slow. Noted.\", 4.5f); }\n            else Authority(\"...Present, I suppose. Barely.\", 4.5f);\n\n            Thought(\"And this seat... they say whoever sits here\\n\" + Rule(\"finds something in the desk\") + \".\", 8.5f);\n            foreach (string n in namesAfter) yield return RollName(n);\n            Authority(\"Good. Today: the Founding Charter. Listen carefully. I will be asking questions.\", 7f);\n            yield return WaitIdle();\n\n            rollCall = false;\n            if (cubbyZone != null) cubbyZone.active = true;\n            if (teacher != null) teacher.EndCall();\n            lecture = StartCoroutine(Lecture());\n            StartCoroutine(Reminder(\"(Something about this desk feels off... look down at the cubby.)\", () => cubbySearched, 30f));\n        }\n\n        IEnumerator RollName(string n)\n        {\n            if (string.IsNullOrEmpty(n)) yield break;\n            Authority(n + \".\", 3.5f);\n            StudentSay(n, \"Here.\", 3f);\n            yield return null;\n        }\n\n        // ------------------------------------------------------------------ the classmates stare while you walk in\n        void UpdateStare()\n        {\n            for (int i = 0; i < classmates.Count; i++)\n            {\n                Transform t = classmates[i];\n                if (t == null) continue;\n                if (frontStudent != null && t == frontStudent.transform && ended && strikes < chances) continue;  // turning to you (win)\n                if (staring)\n                {\n                    Vector3 d = rig.transform.position - t.position; d.y = 0f;\n                    if (d.sqrMagnitude < 0.01f) continue;\n                    // a small twist only - a seated body can't spin round without going through the chair and desk\n                    Quaternion limited = Quaternion.RotateTowards(classmateRest[i], Quaternion.LookRotation(d), 32f);\n                    t.rotation = Quaternion.RotateTowards(t.rotation, limited, 60f * Time.deltaTime);\n                }\n                else t.rotation = Quaternion.RotateTowards(t.rotation, classmateRest[i], 40f * Time.deltaTime);\n            }\n        }\n\n        // ------------------------------------------------------------------ interaction\n        void UpdateInteraction()\n        {\n            string p = null;\n            PlayerRig.Mode m = rig.CurrentMode;\n            if (m == PlayerRig.Mode.Seated || m == PlayerRig.Mode.Inspect)\n            {\n                if (m == PlayerRig.Mode.Inspect && GameInput.SpaceDown()) { rig.BackToSeat(); SetZone(true); SetPrompt(null); return; }\n                p = RaycastInteract();\n                if (p == null && m == PlayerRig.Mode.Inspect) p = \"[Space]  Sit back up\";\n            }\n            SetPrompt(p);\n        }\n\n        IEnumerator MoveBooks()\n        {\n            // slid to the left side of the cubby - they stay where you can see them\n            books.active = false;\n            Transform t = books.transform;\n            Vector3 from = t.localPosition, to = from + new Vector3(-0.23f, 0f, 0f);\n            for (float k = 0f; k < 1f; k += Time.deltaTime / 0.6f) { t.localPosition = Vector3.Lerp(from, to, k * k * (3f - 2f * k)); yield return null; }\n            t.localPosition = to;\n            if (loosePanel != null) loosePanel.active = true;\n        }\n\n        IEnumerator PullPanel()\n        {\n            // pulled towards you, then set aside to the right - still in view\n            loosePanel.active = false;\n            Transform t = loosePanel.transform;\n            foreach (Collider c in t.GetComponentsInChildren<Collider>()) c.enabled = false;\n            Vector3 a = t.localPosition, b = a + new Vector3(0f, 0f, -0.14f), c2 = b + new Vector3(0.16f, 0f, 0f);\n            for (float k = 0f; k < 1f; k += Time.deltaTime / 0.45f) { t.localPosition = Vector3.Lerp(a, b, k * k * (3f - 2f * k)); yield return null; }\n            for (float k = 0f; k < 1f; k += Time.deltaTime / 0.45f) { t.localPosition = Vector3.Lerp(b, c2, k * k * (3f - 2f * k)); yield return null; }\n            t.localPosition = c2;\n            if (hiddenPhone != null) hiddenPhone.active = true;\n            Thought(\"There's something hidden behind it.\", 4f, true);\n        }\n\n        void TakePhone()\n        {\n            hiddenPhone.active = false;\n            hiddenPhone.gameObject.SetActive(false);\n            phone.hasPhone = true;\n            nextCall = Random.Range(callInterval.x, callInterval.y);\n            Thought(\"(An old phone. A sticky note on the back: \\\"it opens the year it all began.\\\")\", 8f, true);\n            StartCoroutine(Reminder(\"Sit up [Space], then \" + Rule(\"HOLD RIGHT MOUSE\") + \" to take out the phone.\", () => phone.RaisedOnce || ended, 20f));\n        }\n\n        IEnumerator StudentTurns()\n        {\n            ended = true;\n            frontStudent.active = false;\n            phone.allowRaise = false;\n            rig.Lock();\n            if (lecture != null) StopCoroutine(lecture);\n            Thought(\"(You tap their shoulder. Twice.)\", 2.5f, true);\n            yield return new WaitForSeconds(2f);\n            // they turn round to face you, chair and all (the chair spins with them, so nothing clips)\n            Transform s = frontStudent.transform;\n            Quaternion r0 = s.rotation;\n            Quaternion c0 = frontChair != null ? frontChair.rotation : Quaternion.identity;\n            for (float k = 0f; k <= 1f; k += Time.deltaTime / 1.1f)\n            {\n                float e = Mathf.Clamp01(k * k * (3f - 2f * k));\n                Quaternion turn = Quaternion.Euler(0f, -180f * e, 0f);   // both turn the same way (towards the window side)\n                s.rotation = r0 * turn;\n                if (frontChair != null) frontChair.rotation = c0 * turn;\n                yield return null;\n            }\n            s.rotation = r0 * Quaternion.Euler(0f, 180f, 0f);\n            if (frontChair != null) frontChair.rotation = c0 * Quaternion.Euler(0f, 180f, 0f);\n            yield return new WaitForSeconds(0.8f);\n            StudentSay(\"STUDENT (whispering)\", \"...Took you long enough. Keep it hidden.\", 4.5f);\n            StudentSay(\"STUDENT (whispering)\", \"After the bell - the stairwell. I'll show you where we really go.\", 5.5f);\n            yield return new WaitForSeconds(1f);\n            yield return WaitIdle();\n            yield return FinishLevel(\"contact\", 1.2f);\n        }\n\n        // ------------------------------------------------------------------ danger (stealth)\n        void UpdateDanger()\n        {\n            bool seen = phone.IsExposed && teacher != null && teacher.Running && vision != null && vision.CanSee(phoneExposurePoint.position, rig.transform);\n            if (AccumulateDanger(seen ? 1f / Mathf.Max(0.05f, noticeSeconds) : 0f))\n                Strike(\"...What was that? Eyes up here, \" + Name + \".\");\n            if (phone.ClueFound && frontStudent != null && !frontStudent.active && !ended)\n            {\n                frontStudent.active = true;\n                Thought(\"A chalk triangle... \" + Rule(\"the chair in front of me has one\") + \".\", 7f);\n            }\n        }\n\n        protected override IEnumerator OnCaught()\n        {\n            calling = false;\n            questionBox.SetActive(false);\n            phone.allowRaise = false;\n            rig.Lock();\n            if (lecture != null) StopCoroutine(lecture);\n            Authority(\"That's three, \" + Name + \". Give it to me.\", 6f, true);\n            if (teacher != null && takePhoneStandPoint != null) teacher.Approach(takePhoneStandPoint.position, rig.transform);\n            staring = true;\n            float t = 0f;\n            yield return new WaitForSeconds(0.5f);\n            while (teacher != null && !teacher.HasArrived && t < 8f) { t += Time.deltaTime; yield return null; }\n            yield return WaitIdle();\n            Thought(\"(He takes the phone. Everyone saw.)\", 4f, true);\n            yield return WaitIdle();\n            yield return Caught(\"taken\");\n        }\n\n        // ------------------------------------------------------------------ lecture & questions\n        IEnumerator Lecture()\n        {\n            int i = 0;\n            bool pa1 = false, pa2 = false;\n            while (!ended)\n            {\n                if (!calling && DialogueIdle && teacher != null && teacher.lines.Count > 0)\n                {\n                    int idx = i % teacher.lines.Count;\n                    if (idx > linesSaid) linesSaid = idx;\n                    Authority(teacher.lines[idx].text);\n                    i++;\n                    yield return WaitIdle();\n                    // the school interrupts, politely (dark humour)\n                    if (i == 5 && !pa1) { pa1 = true; PA(\"This is a reminder that you are happy. Thank you.\"); yield return WaitIdle(); }\n                    if (i == 10 && !pa2) { pa2 = true; PA(\"Reminder: the pigeons in the courtyard are not your friends.\"); yield return WaitIdle(); }\n                    // a pause between lines - this is where the player's thoughts get their turn\n                    float t = 0f;\n                    while (t < 3f && !ended) { if (DialogueIdle) t += Time.deltaTime; yield return null; }\n                }\n                yield return null;\n            }\n        }\n\n        void UpdateCalls()\n        {\n            if (!seated || rollCall || !phone.hasPhone || teacher == null) return;\n            if (!calling)\n            {\n                if (!bootCallDone && phone.BootSecondsElapsed >= firstCallAtBootSecond) { bootCallDone = true; StartCall(); return; }\n                if (nextCall > 0f) { nextCall -= Time.deltaTime; if (nextCall <= 0f) StartCall(); }\n                return;\n            }\n\n            callTimer -= Time.deltaTime;\n            questionTimer.rectTransform.anchorMax = new Vector2(Mathf.Clamp01(callTimer / answerSeconds), 1f);\n            bool canAnswer = rig.CurrentMode == PlayerRig.Mode.Seated && !phone.IsExposed;\n            if (phone.IsExposed) questionStatus.text = \"PUT THE PHONE DOWN to answer!  (release Right Mouse)\";\n            else if (rig.CurrentMode != PlayerRig.Mode.Seated) questionStatus.text = \"SIT UP to answer!  [Space]\";\n            else questionStatus.text = \"Press 1, 2 or 3\";\n\n            if (canAnswer)\n            {\n                int d = GameInput.DigitDown();\n                if (d >= 1 && d <= 3) { EndCall(d - 1 == question.correct, false); return; }\n            }\n            if (callTimer <= 0f) EndCall(false, true);\n        }\n\n        void StartCall()\n        {\n            question = PickQuestion();\n            if (question == null) { nextCall = 10f; return; }\n            calling = true;\n            callTimer = answerSeconds;\n            teacher.CallOn(rig.transform);\n            Authority(Name + \".  \" + question.question, answerSeconds + 1f, true);\n            string q = question.question + \"\\n\";\n            for (int i = 0; i < question.options.Length; i++) q += \"\\n\" + (i + 1) + \"    \" + question.options[i];\n            ShowQuestion(q);\n        }\n\n        LessonQuestion PickQuestion()\n        {\n            List<int> pool = new List<int>();\n            for (int i = 0; i < teacher.questions.Count; i++)\n                if (teacher.questions[i].aboutLine <= linesSaid && !asked.Contains(i)) pool.Add(i);\n            if (pool.Count == 0)\n            {\n                asked.Clear();\n                for (int i = 0; i < teacher.questions.Count; i++) if (teacher.questions[i].aboutLine <= linesSaid) pool.Add(i);\n            }\n            if (pool.Count == 0) return null;\n            int pick = pool[Random.Range(0, pool.Count)];\n            foreach (int i in pool) if (teacher.questions[i].aboutLine >= 0 && Random.value < 0.7f) { pick = i; break; }\n            asked.Add(pick);\n            return teacher.questions[pick];\n        }\n\n        void EndCall(bool correct, bool timedOut)\n        {\n            calling = false;\n            questionBox.SetActive(false);\n            teacher.EndCall();\n            nextCall = Random.Range(callInterval.x, callInterval.y);\n            if (correct) Authority(\"...Correct. Hm. Keep listening.\", 4f, true);\n            else if (timedOut) Strike(\"I asked you a question, \" + Name + \".\");\n            else Strike(\"Wrong. Are you even listening?\");\n        }\n    }\n}\n"},"Level02Director":{"path":"Assets/Game/Scripts/Level02Director.cs","role":"Chapter 2 Lunch: camera and monitor threat, find the hummer, forward the message and reach the STAFF door.","source":"// @role Chapter 2 Lunch: camera and monitor threat, find the hummer, forward the message and reach the STAFF door.\n// @calls LevelDirectorBase, PatrolAI, TeacherVision, HumSource, PhoneController, PlayerRig, Interactable, AudioSynth, GameInput\n// @tune reachDistance:float:1-10:Distance at which the phone can signal her phone.\n\nusing System.Collections;\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Chapter 2 \"Lunch\" (the cafeteria).\n    ///  - New threat: a sweeping security camera + a roaming Lunch Monitor. Danger comes from WHERE you stand.\n    ///    Pillars block the camera; people and pillars block the Monitor. The hallway is the only unwatched place.\n    ///  - Phone: unlock again (1952), then Messages - its code is announced by the PA: lunch at 12:40 -> 1240.\n    ///  - Triangle's job: find the girl who hums when she's scared (listen for the humming), get close\n    ///    (this phone only reaches phones nearby) and forward \"the stairs are open tonight\".\n    ///  - Then slip behind the counters to the STAFF door while the camera looks at the windows. WIN.\n    ///  - Being seen with the phone, or seen behind the counters: a warning. Three: the phone is taken.\n    /// </summary>\n    public class Level02Director : LevelDirectorBase\n    {\n        [Header(\"Scene references (filled by the scene builder)\")]\n        public PatrolAI monitor;\n        public TeacherVision monitorVision;\n        public TeacherVision[] cameras;\n        public Transform hummer;\n        public HumSource hum;\n        public Interactable staffDoor;\n        public Transform staffDoorLeaf;\n        [Tooltip(\"Bench seats you can sit on (position = seat, forward = facing the table).\")]\n        public Interactable[] seats;\n        [Header(\"The stairwell behind the STAFF door\")]\n        public Interactable bottomDoor;\n        public Transform bottomDoorHinge;\n        public Transform voicesPoint;\n        public Vector3 throughDoorPoint = new Vector3(17f, 0f, 12.65f);\n\n        [Header(\"Zones\")]\n        [Tooltip(\"Behind the counters (x min, z min, x max, z max). Being seen here = a warning.\")]\n        public Vector4 kitchenZone = new Vector4(16f, 10.88f, 29.95f, 11.95f);\n        public Vector3 kitchenReturnPoint = new Vector3(28.6f, 0f, 9.7f);\n        public float kitchenReturnYaw = 180f;\n        [Tooltip(\"Inside the dining hall (for the Monitor's first comment).\")]\n        public Vector4 diningZone = new Vector4(14.2f, 0.1f, 29.9f, 10.8f);\n        [Tooltip(\"This phone only reaches phones this close.\")]\n        public float reachDistance = 4f;\n\n        bool gotJob, taskGiven, delivered, enteredDining, toldKitchen, toldRaise, winning, heardHum, toldInReach, listened;\n        float taskTime;\n        bool throughDoor, saidPaint, saidChalk, saidVoices;\n        AudioSource voices;\n        Light hummerGlow;\n        float kitchenSeen, kitchenGrace, paTimer = 40f, monitorTalk;\n        Interactable sitting;\n\n        static readonly string[] ambientPA =\n        {\n            \"Reminder: smiling is part of your uniform.\",\n            \"Today's dessert has been cancelled for your safety. Enjoy your safety.\",\n            \"A student has been happy for fourteen consecutive days. Congratulations to everyone.\",\n            \"Please do not look out of the windows. The windows are for light.\",\n            \"Lunch ends in five minutes. Please finish being nourished.\",\n        };\n        int paIndex;\n\n        protected override void Awake()\n        {\n            base.Awake();\n            authorityLabel = \"LUNCH MONITOR\";\n            authorityPitch = 0.95f;\n            phone.hasPhone = true;\n            phone.allowRaise = false;\n            phone.phoneClock = \"12:41\";\n            phone.appUnlocked[PhoneController.AppPhotos] = true;\n            phone.lockNotification = \"No new messages.\";\n            phone.onMessageArrived = () => { if (!phone.IsExposed) PhoneBuzz(); };\n            if (staffDoor != null) { staffDoor.prompt = \"Slip through the STAFF door\"; staffDoor.onUse = UseDoor; }\n            if (bottomDoor != null) { bottomDoor.prompt = \"Push the door open\"; bottomDoor.onUse = PushBottomDoor; }\n            if (hummer != null)\n            {\n                Interactable it = hummer.GetComponent<Interactable>();\n                if (it == null) it = hummer.gameObject.AddComponent<Interactable>();\n                it.prompt = \"Listen to her\";\n                it.onUse = ListenToHer;\n                // her own phone, glowing under the table - this phone can only reach phones close by\n                GameObject g = new GameObject(\"HerPhoneGlow\");\n                g.transform.SetParent(hummer, false);\n                g.transform.localPosition = new Vector3(0f, 0.75f, 0.35f);\n                hummerGlow = g.AddComponent<Light>();\n                hummerGlow.type = LightType.Point;\n                hummerGlow.color = new Color(0.65f, 0.85f, 1f);\n                hummerGlow.range = 1.2f;\n                hummerGlow.intensity = 0f;\n            }\n            if (seats != null)\n                foreach (Interactable s in seats)\n                {\n                    if (s == null) continue;\n                    Interactable seat = s;\n                    seat.prompt = \"Sit down\";\n                    seat.onUse = () => SitOn(seat);\n                }\n        }\n\n        protected override void Start()\n        {\n            base.Start();\n            if (monitor != null) monitor.Begin();\n            rig.Lock();\n            StartCoroutine(Opening());\n        }\n\n        IEnumerator Opening()\n        {\n            yield return ChapterCard(\"CHAPTER 2\", \"LUNCH\", \"MONDAY  -  12:40\");\n            phone.Receive(\"Triangle\", \"check Messages. the code is when we eat.\");\n            PA(\"Good afternoon, Clearview. Lunch begins at twelve-forty. Twelve. Forty.\", 6.5f);\n            PA(\"Please chew each bite thirty-two times. Thank you for eating correctly.\", 6f);\n            yield return new WaitForSeconds(1.5f);\n            rig.AllowWalk();\n            SetObjective(\"Read Triangle's message.\\nStay in the HALLWAY (safe) and HOLD RIGHT MOUSE.\");\n            Thought(\"Triangle said: after the bell, the stairwell.\\nBut the only stairs are \" + Rule(\"behind the kitchen\") + \".\", 8f);\n            Thought(Rule(\"One camera. One Lunch Monitor.\") + \"\\nThe hallway is the only place nobody watches.\", 8f);\n            yield return WaitIdle();\n            StartCoroutine(Reminder(\"My phone buzzed. \" + Rule(\"HOLD RIGHT MOUSE\") + \" - here in the hallway, where it's safe.\", () => phone.RaisedOnce || ended, 22f));\n        }\n\n        // ------------------------------------------------------------------ main loop\n        protected override void LevelUpdate()\n        {\n            if (throughDoor)\n            {\n                // behind the STAFF door nobody is watching: no camera, no monitor, no phone needed\n                rig.freezeMovement = false;\n                phone.allowRaise = false;\n                UpdateStairs();\n                SetPrompt(rig.CurrentMode == PlayerRig.Mode.Walk ? RaycastInteract() : null);\n                return;\n            }\n            PlayerRig.Mode m = rig.CurrentMode;\n            phone.allowRaise = phone.hasPhone && (m == PlayerRig.Mode.Walk || m == PlayerRig.Mode.Seated);\n            rig.freezeMovement = phone.IsExposed;\n            if (phone.IsExposed && m == PlayerRig.Mode.Walk && !toldRaise)\n            {\n                toldRaise = true;\n                Thought(\"While I look at the phone, \" + Rule(\"I stand still\") + \". Anyone looking can see it.\", 7f);\n            }\n\n            UpdateObjective();\n            UpdateHumHints();\n            UpdateInteraction();\n            UpdateStory();\n            UpdateDanger();\n            UpdateKitchen();\n            UpdateAmbientLines();\n        }\n\n        void UpdateInteraction()\n        {\n            string p = null;\n            if (rig.CurrentMode == PlayerRig.Mode.Seated)\n            {\n                if (GameInput.SpaceDown() && !phone.IsExposed) { StandUp(); SetPrompt(null); return; }\n                p = phone.IsExposed ? null : \"[Space]  Stand up\";\n            }\n            else if (rig.CurrentMode == PlayerRig.Mode.Walk) p = RaycastInteract();\n            if (phone.IsExposed && taskGiven && !delivered && phone.OpenApp == PhoneController.AppMessages && phone.UnreadCount == 0)\n                p = InReach() ? \"SIGNAL: STRONG  -  A / D pick \\\"Hums When Scared\\\", Left Mouse, then HOLD Left Mouse\"\n                              : \"SIGNAL: NONE  -  lower the phone and walk closer to the humming girl\";\n            SetPrompt(p);\n        }\n\n        void SitOn(Interactable seat)\n        {\n            if (seat == null) return;\n            sitting = seat;\n            rig.SitAt(seat.transform.position, seat.transform.eulerAngles.y);\n            foreach (Interactable s in seats) if (s != null) s.active = false;\n        }\n\n        void StandUp()\n        {\n            if (sitting == null) return;\n            Vector3 back = sitting.transform.position - sitting.transform.forward * 0.62f;\n            rig.StandUpAt(back);\n            sitting = null;\n            foreach (Interactable s in seats) if (s != null) s.active = true;\n        }\n\n        // ------------------------------------------------------------------ story\n        void UpdateStory()\n        {\n            if (!gotJob && phone.IsUnlocked(PhoneController.AppMessages))\n            {\n                gotJob = true;\n                phone.Receive(\"Triangle\", \"you made it. don't look for me. they watch who I talk to.\");\n                phone.Receive(\"Triangle\", \"a job first. someone at the window tables hums when she's scared. listen for her.\");\n                phone.Receive(\"Triangle\", \"tell her: the stairs are open tonight. this phone only reaches phones close by.\");\n            }\n            if (gotJob && !taskGiven && phone.UnreadCount == 0)\n            {\n                taskGiven = true;\n                phone.StartTask(new PhoneTask\n                {\n                    forward = true,\n                    header = \"Forward to...\",\n                    options = new[] { \"Mom (not mine)\", \"Don't Reply\", \"Lent Me An Eraser\", \"Hums When Scared\", \"Bus 14\" },\n                    correct = 3,\n                    sendText = \"the stairs are open tonight.\",\n                    check = i => InReach() ? null : \"No signal. Get closer to her.\",\n                    onDone = i => StartCoroutine(Delivered()),\n                    typeSeconds = 3f,\n                });\n                Thought(Rule(\"Find the one who hums\") + \" - pink ribbon, window table, far right corner.\\nPut the phone DOWN to walk. Pillars block the camera.\", 9f);\n            }\n            if (!enteredDining && In(rig.transform.position, diningZone))\n            {\n                enteredDining = true;\n                if (monitor != null && Vector3.Distance(monitor.transform.position, rig.transform.position) < 9f)\n                    Authority(\"Find a seat. Eat. Smile.\", 4f);\n            }\n        }\n\n        bool InReach()\n        {\n            if (hummer == null) return true;\n            Vector3 a = rig.transform.position, b = hummer.position;\n            a.y = 0f; b.y = 0f;\n            return Vector3.Distance(a, b) <= reachDistance;\n        }\n\n        /// <summary>The goal box top-left always says what to do next, and where.</summary>\n        void UpdateObjective()\n        {\n            if (winning) return;\n            if (delivered) { SetObjective(\"Go to the STAFF door (north wall, behind the counters).\\nEnter the lane at the FAR RIGHT end of the counters. Move when the corner camera faces the windows.\"); return; }\n            if (taskGiven)\n            {\n                if (InReach()) SetObjective(\"You're close enough.\\nHOLD RIGHT MOUSE -> Messages -> send to \\\"Hums When Scared\\\".\");\n                else SetObjective(\"Find the girl who HUMS (pink ribbon).\\nShe sits alone at the window table in the FAR RIGHT corner. Follow the sound.\");\n                return;\n            }\n            if (gotJob) { SetObjective(\"Keep the phone up and read Triangle's messages.\"); return; }\n            if (phone.RaisedOnce) SetObjective(\"Unlock MESSAGES.\\nCode = when lunch begins (the PA said it: 12:40 -> 4 digits).\");\n        }\n\n        void UpdateHumHints()\n        {\n            if (hummer == null) return;\n            float d = Vector3.Distance(new Vector3(rig.transform.position.x, 0f, rig.transform.position.z), new Vector3(hummer.position.x, 0f, hummer.position.z));\n            if (hummerGlow != null) hummerGlow.intensity = taskGiven && !delivered ? 0.6f + 0.4f * Mathf.Sin(Time.time * 3f) : 0f;\n            // she rocks slightly while she hums\n            if (hum != null && hum.Humming) hummer.localRotation = Quaternion.Euler(0f, hummer.localEulerAngles.y, Mathf.Sin(Time.time * 2.2f) * 2.5f);\n            if (!taskGiven || delivered) return;\n            taskTime += Time.deltaTime;\n            if (!heardHum && d < 6f && DialogueIdle)\n            {\n                heardHum = true;\n                Thought(\"That humming... the school anthem, off-key.\\n\" + Rule(\"It's coming from the window table.\") + \" Pink ribbon.\", 6f);\n            }\n            if (!toldInReach && InReach())\n            {\n                toldInReach = true;\n                ambient.Play(AudioSynth.Confirm(), 0.3f, 1.5f);\n                Thought(Rule(\"Close enough - signal!\") + \"\\nHOLD RIGHT MOUSE and send it to \\\"Hums When Scared\\\".\", 7f, true);\n            }\n            if (taskTime > 50f && !InReach() && DialogueIdle)\n            {\n                taskTime = 0f;\n                Thought(\"Listen. \" + Rule(\"The humming\") + \" - far right corner, by the south windows.\", 6f);\n            }\n        }\n\n        void ListenToHer()\n        {\n            if (delivered) { Thought(\"She mouths: thank you.\", 3.5f, true); return; }\n            if (!taskGiven) { Thought(\"She's humming the school anthem. Off-key, eyes on her tray.\\nShe looks scared.\", 5f, true); return; }\n            listened = true;\n            Thought(\"It's her. I can't talk to her - \" + Rule(\"they watch who talks\") + \".\\nHOLD RIGHT MOUSE and send the message from here.\", 7f, true);\n        }\n\n        IEnumerator Delivered()\n        {\n            delivered = true;\n            ambient.Play(AudioSynth.Confirm(), 0.4f);\n            yield return new WaitForSeconds(1.5f);\n            if (hum != null) hum.StopHumming();\n            phone.Receive(\"Hums When Scared\", \"...ok. ok. thank you.\");\n            phone.Receive(\"Hums When Scared\", \"tell Triangle I'll be there.\");\n            yield return new WaitForSeconds(5f);\n            phone.Receive(\"Triangle\", \"good. now the STAFF door behind the counters.\");\n            phone.Receive(\"Triangle\", \"the corner camera looks at the windows every few seconds. that's your moment.\");\n            Thought(Rule(\"Behind the counters, to the STAFF door.\") + \"\\nGo when the camera faces the windows.\", 9f);\n        }\n\n        void UseDoor()\n        {\n            if (!delivered) { Thought(\"Not yet. Triangle said: the job first.\", 4f, true); return; }\n            if (!winning) StartCoroutine(ThroughStaffDoor());\n        }\n\n        /// <summary>The STAFF door opens; you step through, it shuts behind you, and the stairs are yours to walk down.</summary>\n        IEnumerator ThroughStaffDoor()\n        {\n            winning = true;\n            rig.Lock();\n            SetPrompt(null);\n            phone.allowRaise = false;\n            ambient.Play(AudioSynth.Creak(), 0.6f);\n            Quaternion r0 = staffDoorLeaf != null ? staffDoorLeaf.localRotation : Quaternion.identity;\n            Quaternion r1 = r0 * Quaternion.Euler(0f, -100f, 0f);\n            if (staffDoorLeaf != null)\n                for (float k = 0f; k < 1f; k += Time.deltaTime / 0.8f) { staffDoorLeaf.localRotation = Quaternion.Slerp(r0, r1, k); yield return null; }\n            yield return Fade(0f, 1f, 0.35f);\n            rig.Teleport(throughDoorPoint, 0f);\n            throughDoor = true;\n            danger = 0f;\n            if (staffDoorLeaf != null) staffDoorLeaf.localRotation = r0;   // it shuts behind you\n            ambient.Play(AudioSynth.Click(), 0.7f, 0.6f);\n            ambient.droneVolume *= 0.5f;\n            if (voicesPoint != null)\n            {\n                voices = voicesPoint.gameObject.AddComponent<AudioSource>();\n                voices.clip = AudioSynth.Murmur();\n                voices.loop = true;\n                voices.spatialBlend = 1f;\n                voices.rolloffMode = AudioRolloffMode.Linear;\n                voices.minDistance = 1.5f;\n                voices.maxDistance = 7f;\n                voices.volume = 0.55f;\n                voices.dopplerLevel = 0f;\n                voices.Play();\n            }\n            yield return Fade(1f, 0f, 0.6f);\n            rig.AllowWalk();\n            SetObjective(\"Go down the stairs.\\nAt the bottom: the door (E).\");\n            Thought(\"The door clicks shut behind me. \" + Rule(\"No camera here.\") + \"\\nStairs. Going down.\", 5f, true);\n        }\n\n        void UpdateStairs()\n        {\n            float z = rig.transform.position.z;\n            if (!saidPaint && z > 13.5f)\n            {\n                saidPaint = true;\n                Thought(\"Someone painted on the wall, a long time ago:\\n\" + Rule(\"WE KEEP THINGS FROM EACH OTHER.\"), 5.5f);\n            }\n            if (!saidChalk && z > 14.6f)\n            {\n                saidChalk = true;\n                Thought(\"And in chalk: \" + Rule(\"SEAT 31\") + \". '79, '86, '94...\\nYear after year. ...And me?\", 5.5f);\n            }\n            if (!saidVoices && z > 16.1f)\n            {\n                saidVoices = true;\n                Thought(\"Voices. Behind that door.\\n\" + Rule(\"Nobody is whispering.\"), 5f, true);\n            }\n        }\n\n        void PushBottomDoor()\n        {\n            if (ended) return;\n            StartCoroutine(PushDoorRoutine());\n        }\n\n        IEnumerator PushDoorRoutine()\n        {\n            ended = true;\n            rig.Lock();\n            SetPrompt(null);\n            SetObjective(\"\");\n            ambient.Play(AudioSynth.Creak(), 0.7f, 0.9f);\n            if (bottomDoorHinge != null)\n            {\n                Quaternion a = bottomDoorHinge.rotation, b = a * Quaternion.Euler(0f, -55f, 0f);\n                for (float k = 0f; k < 1f; k += Time.deltaTime / 1.1f)\n                {\n                    bottomDoorHinge.rotation = Quaternion.Slerp(a, b, k * k * (3f - 2f * k));\n                    if (voices != null) voices.volume = Mathf.Lerp(0.55f, 1f, k);\n                    yield return null;\n                }\n            }\n            Thought(\"Warm light. A lot of people, talking out loud.\\nSomeone says my seat number - like a name.\", 5f, true);\n            yield return new WaitForSeconds(3.5f);\n            yield return FinishLevel(\"stairs\", 2.2f);\n        }\n\n        // ------------------------------------------------------------------ watchers\n        bool AnyCameraSees(Vector3 p)\n        {\n            if (cameras == null) return false;\n            foreach (TeacherVision c in cameras) if (c != null && c.CanSee(p, rig.transform)) return true;\n            return false;\n        }\n\n        void UpdateDanger()\n        {\n            bool byMonitor = false, byCamera = false;\n            if (phone.IsExposed)\n            {\n                Vector3 p = phoneExposurePoint.position;\n                byMonitor = monitorVision != null && monitor != null && monitor.Running && monitorVision.CanSee(p, rig.transform);\n                byCamera = !byMonitor && AnyCameraSees(p);\n            }\n            if (AccumulateDanger(byMonitor || byCamera ? 1f / Mathf.Max(0.05f, noticeSeconds) : 0f))\n            {\n                if (byMonitor) Strike(\"...Was that a phone?\");\n                else Strike(\"A device has been observed in the dining hall.\", true);\n            }\n        }\n\n        void UpdateKitchen()\n        {\n            if (kitchenGrace > 0f) kitchenGrace -= Time.deltaTime;\n            bool inside = In(rig.transform.position, kitchenZone);\n            if (inside && !toldKitchen)\n            {\n                toldKitchen = true;\n                Thought(\"Behind the counters. \" + Rule(\"Keep moving\") + \" - before it turns back.\", 5f, true);\n            }\n            bool seen = false;\n            if (inside && kitchenGrace <= 0f)\n            {\n                Vector3 head = rig.eye.position;\n                seen = AnyCameraSees(head) || (monitorVision != null && monitor != null && monitor.Running && monitorVision.CanSee(head, rig.transform));\n            }\n            kitchenSeen = seen ? kitchenSeen + Time.deltaTime : Mathf.Max(0f, kitchenSeen - Time.deltaTime);\n            if (kitchenSeen > 0.7f)\n            {\n                kitchenSeen = 0f;\n                kitchenGrace = 2.5f;\n                Strike(\"Students are reminded that the kitchen is not a destination.\", true);\n                if (!ended) rig.Teleport(kitchenReturnPoint, kitchenReturnYaw);\n            }\n        }\n\n        void UpdateAmbientLines()\n        {\n            paTimer -= Time.deltaTime;\n            if (paTimer <= 0f && DialogueIdle)\n            {\n                paTimer = Random.Range(55f, 75f);\n                PA(ambientPA[paIndex % ambientPA.Length], 6.5f);\n                paIndex++;\n            }\n            if (monitorTalk > 0f) monitorTalk -= Time.deltaTime;\n            if (monitor != null && monitorTalk <= 0f && DialogueIdle && !phone.IsExposed)\n            {\n                if (Vector3.Distance(monitor.transform.position, rig.transform.position) < 2.2f && In(rig.transform.position, diningZone))\n                {\n                    monitorTalk = 30f;\n                    string[] lines = { \"Chew. Thirty-two times.\", \"Why aren't you eating?\", \"Eyes forward. Thank you.\" };\n                    Authority(lines[Random.Range(0, lines.Length)], 4f);\n                }\n            }\n        }\n\n        static bool In(Vector3 p, Vector4 r) { return p.x >= r.x && p.x <= r.z && p.z >= r.y && p.z <= r.w; }\n\n        protected override IEnumerator OnCaught()\n        {\n            phone.allowRaise = false;\n            phone.CancelTask();\n            rig.Lock();\n            Authority(\"Device. Now.\", 4f, true);\n            if (monitor != null)\n            {\n                Vector3 to = rig.transform.position - monitor.transform.position; to.y = 0f;\n                Vector3 stand = rig.transform.position - to.normalized * 0.9f;\n                monitor.Approach(stand, rig.transform);\n                float t = 0f;\n                yield return new WaitForSeconds(0.4f);\n                while (!monitor.HasArrived && t < 7f) { t += Time.deltaTime; yield return null; }\n            }\n            yield return WaitIdle();\n            PA(\"A device has been retired. Thank you for your cooperation.\", 5f);\n            yield return WaitIdle();\n            yield return Caught(\"confiscated\");\n        }\n    }\n}\n"},"Level03Director":{"path":"Assets/Game/Scripts/Level03Director.cs","role":"Chapter 3 Lights Out: listen for the warden, lie down for bed checks, reply and flash the window three times.","source":"// @role Chapter 3 Lights Out: listen for the warden, lie down for bed checks, reply and flash the window three times.\n// @calls LevelDirectorBase, PatrolAI, TeacherVision, Footsteps, PlayerRig, PhoneController, GameInput, AudioSynth\n// @tune lightNoticeSeconds:float:0.5-4:Seconds of phone light before the warden notices.\n// @tune awakeNoticeSeconds:float:1-6:Seconds sitting up during a bed check before he notices.\n\nusing System.Collections;\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Chapter 3 \"Lights Out\" (dormitory, Room 304, night).\n    ///  - Watch becomes LISTEN: it is almost dark. You hear the Warden's footsteps and keys in the hall.\n    ///  - HOLD [SPACE] = lie down and pretend to sleep. If he comes in and you are sitting up, he notices (slowly).\n    ///  - The phone screen is the brightest thing in the room: if his flashlight catches it, he notices fast.\n    ///  - Never Blinks (across the room) can't sleep. Reply to her. Contacts' code is the room number (0304),\n    ///    which he says every night. The oldest contact: \"Seat 31 - '79\".\n    ///  - Triangle: flash your screen at the window three times so the dorm across the yard knows. They answer. WIN.\n    /// </summary>\n    public class Level03Director : LevelDirectorBase\n    {\n        [Header(\"Scene references (filled by the scene builder)\")]\n        public PatrolAI warden;\n        [Tooltip(\"A student sneaking back from the stairwell at the start (the girl who hums).\")]\n        public PatrolAI sneaker;\n        public TeacherVision wardenVision;\n        public Footsteps wardenSteps;\n        public Transform bedSeat;\n        public Transform windowTarget;\n        public Renderer[] acrossWindows;\n        public Light acrossSignal;\n        public Light neverBlinksGlow;\n\n        [Header(\"Warden route (corridor centre line x = 9)\")]\n        public Vector3 corridorSouth = new Vector3(9f, 0f, -1.2f);\n        public Vector3 corridorNorth = new Vector3(9f, 0f, 11.2f);\n        public Vector3 doorOutside = new Vector3(9f, 0f, 3f);\n        public Vector3 doorInside = new Vector3(6.9f, 0f, 3f);\n        public Vector3 aisleSouth = new Vector3(4f, 0f, 3f);\n        public Vector3 aisleMiddle = new Vector3(4f, 0f, 6.2f);\n        public Vector3 aisleNorth = new Vector3(4f, 0f, 8.8f);\n        public Vector3 bedsideStand = new Vector3(5.4f, 0f, 5.6f);\n        [Tooltip(\"Inside the dorm room (x min, z min, x max, z max).\")]\n        public Vector4 roomZone = new Vector4(0.1f, 0.1f, 7.95f, 9.95f);\n\n        [Header(\"Rules\")]\n        [Tooltip(\"Seconds until he notices the phone's light in his flashlight.\")]\n        public float lightNoticeSeconds = 1.6f;\n        [Tooltip(\"Seconds until he notices you are sitting up during a bed check.\")]\n        public float awakeNoticeSeconds = 3.2f;\n\n        bool firstCheckDone, replied, contactsAsked, firstContactTold, signalAsked, answered, wardenWasInside, toldComing;\n        int flashes;\n        string lastSeenReason = \"\";\n        float wardenWait;\n        Coroutine wardenLoop;\n\n        protected override void Awake()\n        {\n            base.Awake();\n            authorityLabel = \"WARDEN\";\n            authorityPitch = 0.68f;\n            phone.hasPhone = true;\n            phone.allowRaise = false;\n            phone.phoneClock = \"23:41\";\n            phone.appUnlocked[PhoneController.AppPhotos] = true;\n            phone.appUnlocked[PhoneController.AppMessages] = true;\n            phone.lockNotification = \"No new messages.\";\n            phone.AddHistory(\"Triangle\", \"the stairs are open tonight. you did good at lunch.\", false);\n            phone.AddHistory(\"Hums When Scared\", \"thank you. I mean it.\", false);\n            phone.onMessageArrived = () => { if (!phone.IsExposed) PhoneBuzz(); };\n            ambient.droneVolume = 0.11f;\n            ambient.ventVolume = 0.05f;\n            ambient.SetExtraLoop(AudioSynth.Breathing(), 0.07f);\n            if (neverBlinksGlow != null) neverBlinksGlow.enabled = false;\n            GameObject rl = new GameObject(\"RoomLight (warden switches it on)\");\n            rl.transform.position = new Vector3(4f, 2.8f, 5f);\n            roomLight = rl.AddComponent<Light>();\n            roomLight.type = LightType.Point;\n            roomLight.range = 10f;\n            roomLight.intensity = 0f;\n            roomLight.color = new Color(0.92f, 0.98f, 1f);\n            if (acrossSignal != null) acrossSignal.enabled = false;\n        }\n\n        protected override void Start()\n        {\n            base.Start();\n            if (bedSeat != null) rig.SitAt(bedSeat.position, bedSeat.eulerAngles.y);\n            if (warden != null) warden.Begin();\n            StartCoroutine(Script());\n        }\n\n        protected override string StrikeSuffix(int n, bool pa)\n        {\n            return n == 1 ? \"  That's once. Three times, and it's mine.\" : \"  Twice. Next time, it's mine.\";\n        }\n\n        // ------------------------------------------------------------------ story\n        IEnumerator Script()\n        {\n            rig.Lock();\n            yield return ChapterCard(\"CHAPTER 3\", \"LIGHTS OUT\", \"MONDAY  -  23:40\");\n            rig.BackToSeat();\n            yield return SneakBack();\n            Authority(\"Room three-oh-four. Three. Zero. Four.\", 5f);\n            Authority(\"Lights out was at twenty-one hundred. Bed check every fifteen minutes.\", 6.5f);\n            Authority(\"Sleep.\", 2.5f);\n            yield return WaitIdle();\n            if (warden != null) warden.RunRoute(new[] { corridorNorth }, new[] { 6f }, new[] { float.NaN }, null);\n            Thought(\"Dark. I can hear his keys down the hall.\", 5f);\n            Thought(Rule(\"Listen for his footsteps.\") + \" When he comes in,\\n\" + Rule(\"HOLD [SPACE]\") + \" to lie down and pretend to sleep.\", 9f);\n            Thought(\"In the dark, the phone is the brightest thing in the room.\\n\" + Rule(\"Only when he's gone.\"), 8f);\n            yield return WaitIdle();\n            yield return new WaitForSeconds(4f);\n\n            // the first bed check is scripted, so everyone learns to lie down\n            if (!toldComing) { toldComing = true; Thought(\"Footsteps. He's coming back. \" + Rule(\"[SPACE]\"), 4f, true); }\n            yield return RoomCheck();\n            firstCheckDone = true;\n            wardenLoop = StartCoroutine(WardenLoop());\n\n            yield return new WaitForSeconds(3f);\n            NeverBlinksTypes();\n            phone.Receive(\"Never Blinks\", \"are you awake\");\n            yield return new WaitForSeconds(2.5f);\n            phone.Receive(\"Never Blinks\", \"it's me. across from you. i can't sleep. i count his footsteps.\");\n            Thought(\"A message. Across the room - Never Blinks.\\n\" + Rule(\"Only when he's gone.\"), 6f);\n            while (phone.UnreadCount > 0 && !ended) yield return null;\n            phone.StartTask(new PhoneTask\n            {\n                header = \"Reply\",\n                toLabel = \"To: Never Blinks\",\n                options = new[] { \"I'm here.\", \"Go to sleep.\" },\n                onDone = i => { replied = true; StartCoroutine(AfterReply(i)); },\n                typeSeconds = 2.5f,\n            });\n            while (!replied && !ended) yield return null;\n            while (!phone.IsUnlocked(PhoneController.AppContacts) && !ended) yield return null;\n            while (!phone.FirstContactSeen && !ended) yield return null;\n            if (ended) yield break;\n            firstContactTold = true;\n            Thought(\"Seat 31. Nineteen seventy-nine.\\nSomeone had this phone almost \" + Rule(\"fifty years ago\") + \".\", 7f);\n            yield return new WaitForSeconds(3f);\n            NeverBlinksTypes();\n            phone.Receive(\"Never Blinks\", \"see it? the oldest one. nobody knows who.\");\n            yield return new WaitForSeconds(7f);\n            phone.Receive(\"Triangle\", \"one more thing tonight.\");\n            phone.Receive(\"Triangle\", \"the dorm across the yard watches our window at midnight. flash your screen at it three times.\");\n            while (phone.UnreadCount > 0 && !ended) yield return null;\n            signalAsked = true;\n            Thought(Rule(\"Phone up, face the window, [LEFT MOUSE] to flash.\") + \"\\nThree times. Only when he's far away.\", 9f);\n        }\n\n        /// <summary>Opening: someone tiptoes back from the stairwell, stops at your door, and whispers.</summary>\n        IEnumerator SneakBack()\n        {\n            if (sneaker == null) yield break;\n            sneaker.Begin();\n            bool done = false;\n            sneaker.RunRoute(new[] { doorOutside }, new[] { 0f }, new[] { -90f }, () => done = true);\n            Thought(\"Footsteps. Light ones - not his.\", 3.5f);\n            float t = 0f;\n            while (!done && t < 14f) { t += Time.deltaTime; yield return null; }\n            yield return new WaitForSeconds(0.6f);\n            StudentSay(\"(whispering)\", \"...psst. Seat thirty-one. It's real - down there. The stairs.\", 4.5f);\n            StudentSay(\"(whispering)\", \"Everyone was talking. Out loud. Come next time.\", 4f);\n            yield return WaitIdle();\n            Thought(\"The girl who hums. Back from the stairs.\\nShe's smiling. \" + Rule(\"People really go down there.\"), 5.5f);\n            done = false;\n            sneaker.RunRoute(new[] { corridorNorth }, new[] { 0f }, new[] { float.NaN }, () => done = true);\n            t = 0f;\n            while (!done && t < 12f) { t += Time.deltaTime; yield return null; }\n            sneaker.gameObject.SetActive(false);\n            yield return WaitIdle();\n            if (wardenSteps != null) wardenSteps.PlayAt(AudioSynth.Keys(), 0.8f);\n        }\n\n        IEnumerator AfterReply(int choice)\n        {\n            yield return new WaitForSeconds(2f);\n            NeverBlinksTypes();\n            phone.Receive(\"Never Blinks\", choice == 0 ? \"...thanks. nobody says that here.\" : \"...you sound like him.\");\n            yield return new WaitForSeconds(2.5f);\n            phone.Receive(\"Never Blinks\", \"triangle says: the oldest name in Contacts. its code is this room. he says it every night.\");\n            contactsAsked = true;\n            while (phone.UnreadCount > 0 && !ended) yield return null;\n            Thought(\"This room... \" + Rule(\"Three. Zero. Four.\") + \"\\nContacts.\", 6f);\n        }\n\n        void NeverBlinksTypes()\n        {\n            if (neverBlinksGlow != null) StartCoroutine(Glow(neverBlinksGlow, 2.2f));\n        }\n\n        IEnumerator Glow(Light l, float seconds)\n        {\n            l.enabled = true;\n            yield return new WaitForSeconds(seconds);\n            l.enabled = false;\n        }\n\n        IEnumerator Answer()\n        {\n            answered = true;\n            yield return new WaitForSeconds(2.5f);\n            for (int i = 0; i < 3; i++)\n            {\n                SetAcross(true);\n                yield return new WaitForSeconds(0.35f);\n                SetAcross(false);\n                yield return new WaitForSeconds(0.45f);\n            }\n            Thought(\"Three lights across the yard.\\n\" + Rule(\"Someone answered.\"), 5f, true);\n            yield return new WaitForSeconds(2f);\n            NeverBlinksTypes();\n            phone.Receive(\"Never Blinks\", \"they saw. goodnight :)\");\n            yield return new WaitForSeconds(4.5f);\n            ended = true;\n            phone.allowRaise = false;\n            yield return Fade(0f, 1f, 2.5f);\n            ambient.Play(AudioSynth.Chime(), 0.4f);\n            caption.text = \"06:00\\n\\nGOOD MORNING, CLEARVIEW. YOU SLEPT WELL.\\nTHANK YOU FOR SLEEPING.\";\n            yield return new WaitForSeconds(4.5f);\n            GameFlow.EndLevel(LessonResult.Win, \"signal\");\n        }\n\n        void SetAcross(bool on)\n        {\n            if (acrossSignal != null) acrossSignal.enabled = on;\n            if (acrossWindows != null)\n            {\n                MaterialPropertyBlock mpb = new MaterialPropertyBlock();\n                foreach (Renderer r in acrossWindows)\n                {\n                    if (r == null) continue;\n                    r.GetPropertyBlock(mpb);\n                    mpb.SetColor(\"_EmissionColor\", on ? new Color(3f, 2.6f, 1.6f) : new Color(0.25f, 0.2f, 0.1f));\n                    r.SetPropertyBlock(mpb);\n                }\n            }\n        }\n\n        // ------------------------------------------------------------------ warden\n        IEnumerator RoomCheck()\n        {\n            if (warden == null) yield break;\n            bool done = false;\n            warden.RunRoute(\n                new[] { doorOutside, doorInside, aisleSouth, aisleMiddle, aisleNorth, aisleMiddle, doorInside, doorOutside, corridorSouth },\n                new[] { 1.2f, 0.3f, 0.8f, 2.6f, 1.6f, 0.4f, 0.3f, 0.5f, 0f },\n                new[] { -90f, float.NaN, 0f, 90f, 0f, float.NaN, float.NaN, float.NaN, float.NaN },\n                () => done = true);\n            while (!done && !ended) yield return null;\n        }\n\n        IEnumerator Peek()\n        {\n            if (warden == null) yield break;\n            bool done = false;\n            Vector3 end = Random.value < 0.5f ? corridorNorth : corridorSouth;\n            warden.RunRoute(new[] { doorOutside, end }, new[] { 4f, 0f }, new[] { -90f, float.NaN }, () => done = true);\n            while (!done && !ended) yield return null;\n        }\n\n        IEnumerator PassBy()\n        {\n            if (warden == null) yield break;\n            bool done = false;\n            Vector3 end = warden.transform.position.z > 5f ? corridorSouth : corridorNorth;\n            warden.RunRoute(new[] { end }, new[] { 0f }, new[] { float.NaN }, () => done = true);\n            while (!done && !ended) yield return null;\n        }\n\n        // ---- random bed-check events: every visit is a little different\n        static readonly Vector3[] sleeperSpots =\n        {\n            new Vector3(2.6f, 0f, 1.3f), new Vector3(2.6f, 0f, 7.6f), new Vector3(5.4f, 0f, 8.3f), new Vector3(5.4f, 0f, 0.9f), new Vector3(2.6f, 0f, 4.4f),\n        };\n        static readonly string[] enterLines =\n        {\n            \"Bed check.\", \"Three-oh-four. Count.\", \"...\", \"Nobody move.\", \"Eyes closed. All of them.\", \"I can hear you breathing. Good. Keep doing that.\",\n        };\n        static readonly string[] sleeperLines =\n        {\n            \"Still breathing. Good.\", \"Bed number two. Asleep. Correct.\", \"Who taught you to snore like that.\", \"...Sleep is mandatory.\",\n        };\n        static readonly string[] mumbles = { \"...don't take it...\", \"...mum?...\", \"...thirty-two times...\", \"...I'm smiling, I'm smiling...\" };\n        Light roomLight;\n        int lastEvent = -1;\n\n        IEnumerator Route(Vector3[] pts, float[] waits, float[] yaws)\n        {\n            if (warden == null) yield break;\n            bool done = false;\n            warden.RunRoute(pts, waits, yaws, () => done = true);\n            while (!done && !ended) yield return null;\n        }\n\n        IEnumerator GoTo(Vector3 p, float wait, float yaw)\n        {\n            yield return Route(new[] { p }, new[] { wait }, new[] { yaw });\n        }\n\n        void WardenSays(string line, float seconds = 3.5f)\n        {\n            if (!ended && DialogueIdle) Authority(line, seconds);\n        }\n\n        /// <summary>He stops at a sleeping student and shines the light on them. Sometimes they talk in their sleep first.</summary>\n        IEnumerator CheckSleeper()\n        {\n            Vector3 spot = sleeperSpots[Random.Range(0, sleeperSpots.Length)];\n            if (Random.value < 0.5f) StudentSay(\"SLEEPING STUDENT\", mumbles[Random.Range(0, mumbles.Length)], 3.5f);\n            yield return Route(new[] { doorOutside, doorInside, new Vector3(4f, 0f, spot.z) }, new[] { 0.8f, 0.2f, 0.2f }, new[] { -90f, float.NaN, float.NaN });\n            yield return GoTo(spot, 3.2f, spot.x < 4f ? -90f : 90f);\n            WardenSays(sleeperLines[Random.Range(0, sleeperLines.Length)]);\n            yield return Route(new[] { doorInside, doorOutside, Random.value < 0.5f ? corridorSouth : corridorNorth }, new[] { 0.3f, 0.4f, 0f }, new[] { float.NaN, float.NaN, float.NaN });\n        }\n\n        /// <summary>He walks right up to your bed and just stands there.</summary>\n        IEnumerator StandOverYou()\n        {\n            yield return Route(new[] { doorOutside, doorInside }, new[] { 1.0f, 0.4f }, new[] { -90f, float.NaN });\n            yield return GoTo(bedsideStand, Random.Range(4f, 6.5f), 90f);\n            WardenSays(Random.value < 0.5f ? \"...I know when someone is pretending.\" : \"...\", 3.5f);\n            yield return Route(new[] { doorInside, doorOutside, corridorSouth }, new[] { 0.3f, 0.3f, 0f }, new[] { float.NaN, float.NaN, float.NaN });\n        }\n\n        /// <summary>He fills the doorway and doesn't move. Keys. Silence. Then leaves.</summary>\n        IEnumerator DoorwaySilence()\n        {\n            yield return GoTo(doorOutside, 0.5f, -90f);\n            yield return GoTo(doorInside, Random.Range(6f, 9f), -90f);\n            if (wardenSteps != null) wardenSteps.PlayAt(AudioSynth.Keys(), 0.6f);\n            WardenSays(Random.value < 0.5f ? \"Sweet dreams, three-oh-four.\" : \"Good. Nobody is awake.\", 3.5f);\n            yield return Route(new[] { doorOutside, Random.value < 0.5f ? corridorNorth : corridorSouth }, new[] { 0.3f, 0f }, new[] { float.NaN, float.NaN });\n        }\n\n        /// <summary>Footsteps come right to the door... stop... and go away again.</summary>\n        IEnumerator FakeOut()\n        {\n            yield return GoTo(doorOutside, Random.Range(1.2f, 2.5f), 0f);\n            yield return GoTo(Random.value < 0.5f ? corridorNorth : corridorSouth, 0f, float.NaN);\n        }\n\n        /// <summary>He counts heads out loud, bed by bed. Yours is somewhere in the count.</summary>\n        IEnumerator CountHeads()\n        {\n            yield return Route(new[] { doorOutside, doorInside, aisleSouth }, new[] { 0.6f, 0.2f, 0.4f }, new[] { -90f, float.NaN, 0f });\n            string[] n = { \"One.\", \"Two.\", \"Three.\", \"Four.\", \"Five.\", \"...Six.\" };\n            Vector3[] stops = { new Vector3(4f, 0f, 1.3f), new Vector3(4f, 0f, 0.9f), new Vector3(4f, 0f, 4.4f), new Vector3(4.6f, 0f, 4.4f), new Vector3(4f, 0f, 7.6f), new Vector3(4f, 0f, 8.3f) };\n            float[] yaws = { -90f, 90f, -90f, 90f, -90f, 90f };\n            for (int i = 0; i < stops.Length && !ended; i++)\n            {\n                yield return GoTo(stops[i], i == 3 ? 2.2f : 0.9f, yaws[i]);\n                Authority(n[i], 1.6f, true, 0.1f);\n            }\n            yield return Route(new[] { aisleMiddle, doorInside, doorOutside, corridorSouth }, new[] { 0.2f, 0.2f, 0.3f, 0f }, new[] { float.NaN, float.NaN, float.NaN, float.NaN });\n        }\n\n        /// <summary>He flicks the room light on. Everyone is lit. Then off again.</summary>\n        IEnumerator LightsOn()\n        {\n            yield return GoTo(doorOutside, 0.4f, -90f);\n            yield return GoTo(doorInside, 0.1f, -90f);\n            ambient.Play(AudioSynth.Click(), 0.8f, 0.7f);\n            if (roomLight != null) roomLight.intensity = 2.2f;\n            Authority(\"Lights.\", 2f, true);\n            float t = 0f;\n            while (t < Random.Range(2.5f, 4f) && !ended) { t += Time.deltaTime; yield return null; }\n            ambient.Play(AudioSynth.Click(), 0.8f, 0.7f);\n            if (roomLight != null) roomLight.intensity = 0f;\n            yield return Route(new[] { doorOutside, corridorNorth }, new[] { 0.6f, 0f }, new[] { float.NaN, float.NaN });\n        }\n\n        IEnumerator RandomCheck()\n        {\n            // never the same event twice in a row\n            int e;\n            do { e = Random.Range(0, 6); } while (e == lastEvent);\n            lastEvent = e;\n            if (DialogueIdle && e != 3) Authority(enterLines[Random.Range(0, enterLines.Length)], 3f);\n            switch (e)\n            {\n                case 0: yield return RoomCheck(); break;\n                case 1: yield return CheckSleeper(); break;\n                case 2: yield return StandOverYou(); break;\n                case 3: yield return FakeOut(); break;\n                case 4: yield return CountHeads(); break;\n                default: yield return Random.value < 0.5f ? LightsOn() : DoorwaySilence(); break;\n            }\n        }\n\n        IEnumerator WardenLoop()\n        {\n            while (!ended)\n            {\n                // long quiet gaps: time to use the phone (he is still somewhere in the hall)\n                wardenWait = Random.Range(24f, 38f);\n                while (wardenWait > 0f && !ended) { wardenWait -= Time.deltaTime; yield return null; }\n                if (ended) yield break;\n                float r = Random.value;\n                if (r < 0.35f) yield return PassBy();\n                else if (r < 0.6f) yield return Peek();\n                else\n                {\n                    yield return RandomCheck();\n                    // after he has been in the room, he stays away a bit longer\n                    float rest = Random.Range(10f, 16f);\n                    while (rest > 0f && !ended) { rest -= Time.deltaTime; yield return null; }\n                }\n            }\n        }\n\n        // ------------------------------------------------------------------ main loop\n        protected override void LevelUpdate()\n        {\n            // lie down / sit up\n            bool canLie = !phone.IsExposed;\n            if (rig.CurrentMode == PlayerRig.Mode.Seated && GameInput.SpaceHeld() && canLie) rig.LieDown();\n            else if (rig.CurrentMode == PlayerRig.Mode.Lying && !GameInput.SpaceHeld()) rig.SitUp();\n            SetLids(rig.CurrentMode == PlayerRig.Mode.Lying ? 0.72f : 0f);\n            phone.allowRaise = rig.CurrentMode == PlayerRig.Mode.Seated;\n\n            // the door creaks when he comes in\n            bool inside = warden != null && In(warden.transform.position, roomZone);\n            if (inside && !wardenWasInside && wardenSteps != null) wardenSteps.PlayAt(AudioSynth.Creak(), 0.7f);\n            wardenWasInside = inside;\n\n            UpdateObjective();\n            UpdateSignal();\n            UpdateDanger(inside);\n            UpdatePrompt();\n        }\n\n        void UpdateObjective()\n        {\n            if (!firstCheckDone) { SetObjective(\"Listen for his footsteps.\\nWhen he comes in: HOLD SPACE to lie down.\"); return; }\n            if (!replied) { SetObjective(\"Reply to Never Blinks (Messages).\\nOnly when he's gone. HOLD SPACE when he comes.\"); return; }\n            if (!phone.IsUnlocked(PhoneController.AppContacts)) { SetObjective(\"Unlock CONTACTS.\\nCode = this room's number (he says it every night).\"); return; }\n            if (!phone.FirstContactSeen) { SetObjective(\"Open Contacts and look at\\nthe OLDEST contact.\"); return; }\n            if (!signalAsked) { SetObjective(\"Wait for messages.\\nLie down (HOLD SPACE) whenever he comes.\"); return; }\n            if (flashes < 3) { SetObjective(\"Face the WINDOW, phone up, LEFT MOUSE to flash (\" + flashes + \"/3).\\nOnly when he is far away.\"); return; }\n            SetObjective(\"\");\n        }\n\n        bool FacingWindow()\n        {\n            if (windowTarget == null || rig.eye == null) return false;\n            Vector3 to = windowTarget.position - rig.eye.position; to.y = 0f;\n            Vector3 f = rig.eye.forward; f.y = 0f;\n            return Vector3.Angle(f, to) < 28f;\n        }\n\n        void UpdateSignal()\n        {\n            if (!signalAsked || answered || flashes >= 3) return;\n            if (phone.IsUp && phone.ScreenOn && FacingWindow() && GameInput.LeftDown())\n            {\n                flashes++;\n                phone.glowBoost = 1f;\n                ambient.Play(AudioSynth.Click(), 0.5f);\n                if (warden != null && wardenVision != null && wardenVision.CanSee(phoneExposurePoint.position, rig.transform, 16f))\n                {\n                    danger = Mathf.Min(0.99f, danger + 0.45f);\n                    lastSeenReason = \"light\";\n                }\n                if (flashes >= 3) StartCoroutine(Answer());\n            }\n        }\n\n        void UpdatePrompt()\n        {\n            string p = null;\n            if (signalAsked && !answered && flashes < 3 && phone.IsUp && phone.ScreenOn)\n                p = FacingWindow() ? \"[Left Mouse]  Flash the screen at the window  (\" + flashes + \"/3)\" : \"Face the window\";\n            else if (!phone.IsExposed && rig.CurrentMode == PlayerRig.Mode.Seated && !firstCheckDone) p = \"HOLD [Space]  Lie down\";\n            SetPrompt(p);\n        }\n\n        void UpdateDanger(bool wardenInside)\n        {\n            float rate = 0f;\n            if (warden != null && warden.Running && wardenVision != null)\n            {\n                if (phone.IsExposed && wardenVision.CanSee(phoneExposurePoint.position, rig.transform, 14f))\n                {\n                    rate = 1f / Mathf.Max(0.05f, lightNoticeSeconds);\n                    lastSeenReason = \"light\";\n                }\n                else if (wardenInside && rig.CurrentMode != PlayerRig.Mode.Lying && wardenVision.CanSee(rig.eye.position, rig.transform, 8f))\n                {\n                    rate = 1f / Mathf.Max(0.05f, awakeNoticeSeconds);\n                    lastSeenReason = \"awake\";\n                }\n            }\n            if (AccumulateDanger(rate))\n            {\n                if (lastSeenReason == \"light\") Strike(\"...A light. Lights out means lights out.\");\n                else Strike(\"Why are you sitting up? Lie down.\");\n            }\n        }\n\n        static bool In(Vector3 p, Vector4 r) { return p.x >= r.x && p.x <= r.z && p.z >= r.y && p.z <= r.w; }\n\n        protected override IEnumerator OnCaught()\n        {\n            if (wardenLoop != null) StopCoroutine(wardenLoop);\n            phone.allowRaise = false;\n            phone.CancelTask();\n            rig.Lock();\n            SetLids(0f);\n            Authority(\"Hand it over.\", 4f, true);\n            if (warden != null)\n            {\n                warden.Approach(bedsideStand, rig.transform);\n                float t = 0f;\n                yield return new WaitForSeconds(0.4f);\n                while (!warden.HasArrived && t < 9f) { t += Time.deltaTime; yield return null; }\n            }\n            yield return WaitIdle();\n            Authority(\"Sweet dreams.\", 3f);\n            yield return WaitIdle();\n            yield return Caught(\"confiscated\");\n        }\n    }\n}\n"},"Level04Director":{"path":"Assets/Game/Scripts/Level04Director.cs","role":"Chapter 4 Inspection Day: recover the phone, answer questions, find the 1979 photo and choose an ending.","source":"// @role Chapter 4 Inspection Day: recover the phone, answer questions, find the 1979 photo and choose an ending.\n// @calls LevelDirectorBase, TeacherAI, TeacherVision, PlayerRig, PhoneController, Interactable, LessonLine, GameInput, AudioSynth\n// @tune answerSeconds:float:5-30:Seconds to answer a question.\n// @tune callInterval:Vector2:10-60:Seconds between questions (x to y).\n// @tune inspectionFallbackSeconds:float:30-240:Seconds after taking the phone before inspection starts if the photo is missed.\n// @tune choiceSeconds:float:5-30:Seconds to choose an ending.\n\nusing System.Collections;\nusing System.Collections.Generic;\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Chapter 4 \"Inspection Day\" - the finale. Back in the same classroom, same seat.\n    ///  1. The phone is still behind the loose panel in your desk. Get it back while he lectures.\n    ///  2. He asks questions, like on the first day (only about what he has said).\n    ///  3. Triangle: \"look at the last photo.\" 1979, same seat - VOSS. The teacher sat here.\n    ///  4. The inspection begins: desk by desk, front to back. Yours is last.\n    ///  5. One desk away, you decide:\n    ///       1 = hide it again   -> ENDING \"THE SEAT\"   (the secret survives, and so does the school)\n    ///       2 = send it to all  -> ENDING \"LIGHTS\"     (every hidden phone in the room lights up)\n    ///  Third warning: \"...Just like I was.\" (LOSE, retry from this chapter)\n    /// </summary>\n    public class Level04Director : LevelDirectorBase\n    {\n        [Header(\"Scene references (filled by the scene builder)\")]\n        public TeacherAI teacher;\n        public TeacherVision vision;\n        public Transform seatPoint;\n        public Interactable cubbyZone, loosePanel, hiddenPhone;\n        public Transform takePhoneStandPoint;\n        public AudioClip bellClip;\n        [Header(\"Ending LIGHTS: the room behind the stairs\")]\n        public Transform basementSeat;\n        public Transform basementDoorHinge;\n        public GameObject vossInDoorway;\n\n        [Header(\"Questions\")]\n        public float answerSeconds = 10f;\n        public Vector2 callInterval = new Vector2(24f, 36f);\n        [Tooltip(\"If the old photo is never found, the inspection starts anyway this long after taking the phone.\")]\n        public float inspectionFallbackSeconds = 100f;\n        public float choiceSeconds = 14f;\n\n        bool calling, cubbySearched, gotPhone, inspecting, toldDanger, choosing;\n        float nextCall = -1f, callTimer, phoneTime;\n        int linesSaid = -1;\n        LessonQuestion question;\n        readonly List<int> asked = new List<int>();\n        readonly List<Transform> classmates = new List<Transform>();\n        Coroutine lecture;\n\n        protected override void Awake()\n        {\n            base.Awake();\n            authorityLabel = \"INSTRUCTOR VOSS\";\n            authorityPitch = 0.76f;\n            if (teacher != null)\n            {\n                teacher.lines = LessonDefaults.InspectionLines();\n                teacher.questions = LessonDefaults.InspectionQuestions();\n            }\n            phone.hasPhone = false;\n            phone.allowRaise = false;\n            phone.phoneClock = \"09:00\";\n            phone.showOldPhoto = true;\n            phone.appUnlocked[PhoneController.AppPhotos] = true;\n            phone.appUnlocked[PhoneController.AppMessages] = true;\n            phone.appUnlocked[PhoneController.AppContacts] = true;\n            phone.lockNotification = \"2 new messages\\nTriangle: inspection today.\";\n            phone.AddHistory(\"Triangle\", \"the stairs are open tonight. you did good at lunch.\", false);\n            phone.AddHistory(\"Never Blinks\", \"they saw. goodnight :)\", false);\n            phone.onMessageArrived = () => { if (!phone.IsExposed) PhoneBuzz(); };\n            foreach (Transform t in FindObjectsByType<Transform>(FindObjectsInactive.Exclude, FindObjectsSortMode.None))\n                if (t.name.StartsWith(\"Fig_Classmate_Seated\")) classmates.Add(t);\n            SetupDesk();\n        }\n\n        protected override void Start()\n        {\n            base.Start();\n            if (seatPoint != null) rig.SitAt(seatPoint.position, seatPoint.eulerAngles.y);\n            if (teacher != null) teacher.Begin();\n            StartCoroutine(Opening());\n        }\n\n        protected override string StrikeSuffix(int n, bool pa)\n        {\n            if (pa) return base.StrikeSuffix(n, true);\n            return n == 1 ? \"  One. You know how many you get.\" : \"  Two. I was sitting where you are when I got my second.\";\n        }\n\n        protected override bool ReminderBlocked() { return calling || choosing; }\n\n        void SetupDesk()\n        {\n            if (cubbyZone != null)\n            {\n                cubbyZone.prompt = \"Search your desk\";\n                cubbyZone.active = false;\n                cubbyZone.onUse = () => { rig.EnterInspect(); SetZone(false); cubbySearched = true; };\n            }\n            if (loosePanel != null) { loosePanel.prompt = \"Pull the loose panel\"; loosePanel.onUse = () => StartCoroutine(PullPanel()); }\n            if (hiddenPhone != null) { hiddenPhone.prompt = \"Take the phone back\"; hiddenPhone.active = false; hiddenPhone.onUse = TakePhone; }\n        }\n\n        void SetZone(bool on)\n        {\n            if (cubbyZone == null) return;\n            foreach (Collider c in cubbyZone.GetComponents<Collider>()) c.enabled = on;\n        }\n\n        // ------------------------------------------------------------------ story\n        IEnumerator Opening()\n        {\n            rig.Lock();\n            yield return ChapterCard(\"CHAPTER 4\", \"INSPECTION DAY\", \"FRIDAY  -  09:00\");\n            rig.BackToSeat();\n            if (cubbyZone != null) cubbyZone.active = true;\n            if (bellClip != null) { ambient.Play(bellClip, 0.8f); yield return new WaitForSeconds(2.5f); }\n            PA(\"Good morning! Today is Inspection Day. Instructor Voss will inspect every desk.\", 6f, false, 0.6f);\n            Authority(\"Sit straight. A short lesson first. I will be asking questions.\", 5f, false, 0.6f);\n            Thought(\"I left it behind the panel last night.\\n\" + Rule(\"Get it back\") + \" before he gets to my desk.\", 6f, false, 0.6f);\n            lecture = StartCoroutine(Lecture());\n            StartCoroutine(Reminder(\"(Look down at the cubby. The phone is still behind the panel.)\", () => cubbySearched, 28f));\n        }\n\n        IEnumerator PullPanel()\n        {\n            loosePanel.active = false;\n            Transform t = loosePanel.transform;\n            foreach (Collider c in t.GetComponentsInChildren<Collider>()) c.enabled = false;\n            Vector3 a = t.localPosition, b = a + new Vector3(0f, 0f, -0.14f), c2 = b + new Vector3(0.16f, 0f, 0f);\n            for (float k = 0f; k < 1f; k += Time.deltaTime / 0.45f) { t.localPosition = Vector3.Lerp(a, b, k * k * (3f - 2f * k)); yield return null; }\n            for (float k = 0f; k < 1f; k += Time.deltaTime / 0.45f) { t.localPosition = Vector3.Lerp(b, c2, k * k * (3f - 2f * k)); yield return null; }\n            t.localPosition = c2;\n            if (hiddenPhone != null) hiddenPhone.active = true;\n        }\n\n        void TakePhone()\n        {\n            hiddenPhone.active = false;\n            hiddenPhone.gameObject.SetActive(false);\n            phone.hasPhone = true;\n            gotPhone = true;\n            nextCall = Random.Range(callInterval.x, callInterval.y) * 0.5f;\n            Thought(\"Still here. Sit up \" + Rule(\"[Space]\") + \", \" + Rule(\"HOLD RIGHT MOUSE\") + \" when he isn't looking.\", 7f, true);\n            StartCoroutine(Messages());\n        }\n\n        IEnumerator Messages()\n        {\n            yield return new WaitForSeconds(2f);\n            phone.Receive(\"Triangle\", \"inspection today. he checks every desk. every single one.\");\n            yield return new WaitForSeconds(1.5f);\n            phone.Receive(\"Triangle\", \"before he gets to you: look at the last photo. the one we never told you about.\");\n            StartCoroutine(Reminder(\"Triangle said: \" + Rule(\"Photos - the last photo\") + \".\", () => phone.OldPhotoFound || inspecting || ended, 34f));\n            while (!phone.OldPhotoFound && !inspecting && !ended) yield return null;\n            if (ended || inspecting) yield break;\n            Thought(\"1979. Back row, by the window. \" + Rule(\"My seat.\") + \"\\nIn pencil: VOSS. He sat here.\", 6f, true, 0.5f);\n            phone.Receive(\"Triangle\", \"he had this phone once. he gave it up. that's how he got to stay.\");\n            yield return new WaitForSeconds(2f);\n            phone.Receive(\"Triangle\", \"he's starting. decide what you want it to be for.\");\n            yield return new WaitForSeconds(2f);\n            StartInspection();\n        }\n\n        void StartInspection()\n        {\n            if (inspecting || ended) return;\n            inspecting = true;\n            if (calling) { calling = false; questionBox.SetActive(false); }\n            if (lecture != null) StopCoroutine(lecture);\n            StartCoroutine(Inspection());\n        }\n\n        // ------------------------------------------------------------------ the inspection\n        IEnumerator Inspection()\n        {\n            yield return WaitIdle();\n            PA(\"Inspection will now begin. Please remain seated and grateful.\", 4.5f, false, 0.4f);\n            UnityEngine.AI.NavMeshAgent ag = teacher.GetComponent<UnityEngine.AI.NavMeshAgent>();\n            if (ag != null) ag.speed = 1.9f;\n\n            // only a few desks on the way to yours: one at the front, one in the middle, then the two next to you\n            List<Transform> all = new List<Transform>(classmates);\n            all.RemoveAll(x => x == null);\n            all.Sort((a, b) => b.position.z.CompareTo(a.position.z));\n            List<Transform> near = new List<Transform>(all);\n            near.Sort((a, b) => Vector3.Distance(b.position, rig.transform.position).CompareTo(Vector3.Distance(a.position, rig.transform.position)));\n            List<Transform> order = new List<Transform>();\n            if (all.Count > 0) order.Add(all[0]);\n            if (all.Count > 2 && !order.Contains(all[all.Count / 2])) order.Add(all[all.Count / 2]);\n            for (int k = Mathf.Max(0, near.Count - 2); k < near.Count; k++) if (!order.Contains(near[k])) order.Add(near[k]);\n            string[] verdicts =\n            {\n                \"Pencils. Two. Approved.\",\n                \"A drawing of a horse. Confiscated. ...It is a good horse.\",\n                \"Nothing. Good. Nothing is good.\",\n                \"A note that says 'help'. Is this a joke? Confiscated. Ha. Ha.\",\n                \"Approved.\",\n                \"Gum. Under the desk. Since 1986. Approved, historically.\",\n                \"An eraser. Whose eraser is this? ...Approved.\",\n                \"Approved. Thank you for your cooperation.\",\n            };\n            int v = 0;\n            for (int i = 0; i < order.Count && !ended; i++)\n            {\n                Transform s = order[i];\n                if (s == null) continue;\n                // he stands in the nearest aisle, never on or between the desks\n                float ax = 0.65f;\n                foreach (float a in new[] { 0.65f, 3.5f, 6.5f, 9.3f }) if (Mathf.Abs(a - s.position.x) < Mathf.Abs(ax - s.position.x)) ax = a;\n                Vector3 stand = new Vector3(ax, 0f, s.position.z);\n                teacher.Approach(stand, s);\n                float t = 0f;\n                yield return new WaitForSeconds(0.3f);\n                while (!teacher.HasArrived && t < 8f && !ended) { t += Time.deltaTime; yield return null; }\n                if (ended) yield break;\n                Authority(verdicts[v % verdicts.Length], 3f, true, 0.2f);\n                v++;\n                ambient.Play(AudioSynth.Creak(), 0.25f, 1.4f);\n                t = 0f;\n                while (t < 1.4f && !ended) { t += Time.deltaTime; yield return null; }\n            }\n            if (ended) yield break;\n            yield return Choice();\n        }\n\n        IEnumerator Choice()\n        {\n            yield return WaitIdle();\n            choosing = true;\n            phone.CancelTask();\n            Authority(Name + \". Seat thirty-one. Your turn.\", 5f, true);\n            Thought(\"He's coming. \" + Rule(\"Decide.\"), 4f);\n            ShowQuestion(\"He's one desk away.\\n\\n1    Hide it again. Keep the seat's secret.\\n2    Send it. To everyone.\");\n            int pick = 0;\n            float tt = 0f;\n            while (tt < choiceSeconds && pick == 0 && !ended)\n            {\n                tt += Time.deltaTime;\n                questionTimer.rectTransform.anchorMax = new Vector2(1f - tt / choiceSeconds, 1f);\n                questionStatus.text = \"Press 1 or 2\";\n                int d = GameInput.DigitDown();\n                if (d == 1 || d == 2) pick = d;\n                yield return null;\n            }\n            questionBox.SetActive(false);\n            choosing = false;\n            SetObjective(\"\");\n            if (ended) yield break;\n            ended = true;   // no more warnings from here on: this is your decision\n            if (pick == 2) yield return EndingLights();\n            else yield return EndingSeat();\n        }\n\n        IEnumerator WalkToYou()\n        {\n            if (teacher == null || takePhoneStandPoint == null) yield break;\n            teacher.Approach(takePhoneStandPoint.position, rig.transform);\n            float t = 0f;\n            yield return new WaitForSeconds(0.3f);\n            while (!teacher.HasArrived && t < 8f) { t += Time.deltaTime; yield return null; }\n        }\n\n        IEnumerator EndingSeat()\n        {\n            phone.allowRaise = false;\n            phone.hasPhone = false;\n            rig.Lock();\n            Thought(\"(You slide it back behind the panel. Like whoever sat here before you.)\", 5f, true);\n            yield return WalkToYou();\n            yield return WaitIdle();\n            ambient.Duck(6f);\n            Authority(\"Lid up.\", 3f);\n            yield return WaitIdle();\n            Authority(\"Books. Approved.\", 3.5f);\n            Authority(\"...\", 3f);\n            Authority(\"This panel is loose.\", 4f);\n            yield return WaitIdle();\n            Thought(\"Don't breathe.\", 3f);\n            yield return WaitIdle();\n            Authority(\"...It has always been loose.\", 4.5f);\n            Authority(\"An inspected desk is a happy desk, \" + Name + \".\", 5f);\n            yield return WaitIdle();\n            if (teacher != null) teacher.WalkToAndFace(teacher.lectureSpot, teacher.lectureFacingYaw);\n            PA(\"Inspection complete. Zero items found. Congratulations, Clearview!\", 6f);\n            yield return WaitIdle();\n            Thought(\"It's still there. For whoever sits here next.\", 5f);\n            yield return WaitIdle();\n            GameFlow.endingChoice = 1;\n            yield return FinishLevel(\"ending_seat\", 2.5f);\n        }\n\n        IEnumerator EndingLights()\n        {\n            rig.Lock();\n            phone.forceRaise = true;\n            phone.ForceOpen(PhoneController.AppMessages);\n            bool sent = false;\n            phone.StartTask(new PhoneTask\n            {\n                forward = true,\n                header = \"Forward\",\n                options = new[] { \"EVERYONE (all contacts)\" },\n                sendText = \"the stairs are open. everyone. now.\",\n                typeSeconds = 4f,\n                onDone = i => sent = true,\n            });\n            Thought(Rule(\"[LEFT MOUSE]\") + \" select, then \" + Rule(\"HOLD LEFT MOUSE\") + \" to send.\", 99f, true);\n            StartCoroutine(WalkToYou());\n            yield return new WaitForSeconds(1.5f);\n            Authority(\"...What are you doing.\", 4f, true);\n            float t = 0f;\n            bool said = false;\n            while (!sent)\n            {\n                t += Time.deltaTime;\n                if (t > 6f && !said) { said = true; Authority(\"Put it down, \" + Name + \". Put it DOWN.\", 5f, true); }\n                yield return null;\n            }\n            ClearLine();\n            yield return new WaitForSeconds(1.2f);\n            yield return LightsUp();\n            ambient.Duck(5f);\n            yield return new WaitForSeconds(2f);\n            StudentSay(\"CLASSMATE\", \"...Seat thirty-one.\", 3.5f);\n            StudentSay(\"CLASSMATE\", \"It's open. The stairs.\", 3.5f);\n            yield return WaitIdle();\n            Authority(\"...\", 3f);\n            yield return WaitIdle();\n            phone.forceRaise = false;\n            if (teacher != null) teacher.WalkToAndFace(teacher.boardSpot, teacher.boardFacingYaw);\n            Authority(\"Page forty. Read quietly.\", 4.5f);\n            yield return WaitIdle();\n            Thought(\"He turned to the board.\\nHe isn't looking. \" + Rule(\"He's letting us go.\"), 6f);\n            yield return WaitIdle();\n            ambient.Play(AudioSynth.Glitch(), 0.5f);\n            PA(\"<color=#7a1d16>...N0thing happened t0day. Thank y0u.</color>\", 5f);\n            yield return WaitIdle();\n            GameFlow.endingChoice = 2;\n            if (basementSeat != null) yield return Basement();\n            yield return FinishLevel(\"ending_lights\", 2.5f);\n        }\n\n        /// <summary>Epilogue of LIGHTS: that afternoon, at the bottom of the stairs. Then Voss in the doorway.</summary>\n        IEnumerator Basement()\n        {\n            yield return Fade(0f, 1f, 1.6f);\n            caption.text = \"THAT AFTERNOON.\\n\\nTHE ROOM AT THE BOTTOM OF THE STAIRS.\";\n            phone.forceRaise = false;\n            phone.hasPhone = false;\n            rig.SitAt(basementSeat.position, basementSeat.eulerAngles.y);\n            rig.BackToSeat();\n            ambient.droneVolume = 0.03f;\n            ambient.ventVolume = 0.02f;\n            AudioSource voices = gameObject.AddComponent<AudioSource>();\n            voices.clip = AudioSynth.Murmur();\n            voices.loop = true;\n            voices.spatialBlend = 0f;\n            voices.volume = 0.35f;\n            voices.Play();\n            yield return new WaitForSeconds(3f);\n            caption.text = \"\";\n            yield return Fade(1f, 0f, 1.8f);\n\n            StudentSay(\"TRIANGLE\", \"Seat thirty-one! Sit. ...Told you. After the bell.\", 4.5f);\n            StudentSay(\"HUMS WHEN SCARED\", \"You came. I'm not humming - did you notice?\", 4.5f);\n            StudentSay(\"NEVER BLINKS\", \"Still can't sleep. But it's better down here.\", 4.5f);\n            StudentSay(\"LENT ME AN ERASER\", \"Say anything. Out loud. Nobody's writing it down.\", 4.5f);\n            yield return WaitIdle();\n            Thought(\"Nobody is whispering. \" + Rule(\"Nobody looks at the ceiling.\"), 4.5f);\n            yield return WaitIdle();\n\n            // someone at the door\n            if (vossInDoorway != null) vossInDoorway.SetActive(true);\n            ambient.Play(AudioSynth.Creak(), 0.5f, 0.8f);\n            for (float k = 0f; k < 1f; k += Time.deltaTime / 1.2f) { voices.volume = Mathf.Lerp(0.35f, 0.03f, k); yield return null; }\n            Thought(\"The doorway. \" + Rule(\"Instructor Voss.\") + \"\\nEveryone stops talking.\", 4.5f, true);\n            yield return new WaitForSeconds(4.5f);\n            Authority(\"...\", 3f);\n            yield return new WaitForSeconds(3.2f);\n            // he steps back onto the landing and closes the door - from the outside\n            Vector3 v0 = vossInDoorway != null ? vossInDoorway.transform.position : Vector3.zero;\n            for (float k = 0f; k < 1f; k += Time.deltaTime / 0.8f)\n            {\n                if (vossInDoorway != null) vossInDoorway.transform.position = v0 + vossInDoorway.transform.forward * -0.8f * k;\n                yield return null;\n            }\n            if (basementDoorHinge != null)\n            {\n                Quaternion a = basementDoorHinge.rotation, b = Quaternion.Euler(0f, 0f, 0f);\n                for (float k = 0f; k < 1f; k += Time.deltaTime / 1.4f)\n                {\n                    basementDoorHinge.rotation = Quaternion.Slerp(a, b, k * k * (3f - 2f * k));\n                    if (k > 0.5f && vossInDoorway != null) vossInDoorway.SetActive(false);\n                    yield return null;\n                }\n                basementDoorHinge.rotation = b;\n            }\n            if (vossInDoorway != null) vossInDoorway.SetActive(false);\n            ambient.Play(AudioSynth.Click(), 0.6f, 0.6f);\n            Thought(\"He closed the door.\\n\" + Rule(\"From the outside.\"), 5f, true);\n            yield return new WaitForSeconds(2.5f);\n            for (float k = 0f; k < 1f; k += Time.deltaTime / 2f) { voices.volume = Mathf.Lerp(0.03f, 0.4f, k); yield return null; }\n            StudentSay(\"TRIANGLE\", \"...So. Where were we?\", 3.5f);\n            yield return WaitIdle();\n        }\n\n        IEnumerator LightsUp()\n        {\n            // every desk in the room had one\n            List<Transform> order = new List<Transform>(classmates);\n            order.Sort((a, b) => Vector3.Distance(a.position, rig.transform.position).CompareTo(Vector3.Distance(b.position, rig.transform.position)));\n            foreach (Transform s in order)\n            {\n                if (s == null) continue;\n                GameObject g = new GameObject(\"PhoneGlow\");\n                g.transform.position = s.position + new Vector3(0f, 0.85f, 0.25f);\n                Light l = g.AddComponent<Light>();\n                l.type = LightType.Point;\n                l.color = new Color(0.62f, 0.85f, 1f);\n                l.range = 1.6f;\n                l.intensity = 2.2f;\n                GameObject quad = GameObject.CreatePrimitive(PrimitiveType.Quad);\n                Destroy(quad.GetComponent<Collider>());\n                quad.transform.SetParent(g.transform, false);\n                quad.transform.localScale = new Vector3(0.07f, 0.13f, 1f);\n                quad.transform.localRotation = Quaternion.Euler(60f, 180f, 0f);\n                Renderer r = quad.GetComponent<Renderer>();\n                Shader sh = Shader.Find(\"Universal Render Pipeline/Unlit\");\n                if (sh != null) r.material = new Material(sh) { color = new Color(0.75f, 0.92f, 1f) };\n                ambient.Play(AudioSynth.Vibrate(), 0.25f, Random.Range(0.9f, 1.15f));\n                yield return new WaitForSeconds(Random.Range(0.12f, 0.35f));\n            }\n        }\n\n        // ------------------------------------------------------------------ main loop\n        protected override void LevelUpdate()\n        {\n            phone.allowRaise = rig.CurrentMode == PlayerRig.Mode.Seated && phone.hasPhone && !choosing;\n            if (gotPhone)\n            {\n                phoneTime += Time.deltaTime;\n                if (!inspecting && phoneTime > inspectionFallbackSeconds) StartInspection();\n            }\n            if (phone.hasPhone && phone.RaisedOnce && !toldDanger)\n            {\n                toldDanger = true;\n                Thought(\"Same rules. If he can see it, \" + Rule(\"it shakes and turns red\") + \".\");\n            }\n            UpdateObjective();\n            UpdateInteraction();\n            UpdateDanger();\n            UpdateCalls();\n        }\n\n        void UpdateObjective()\n        {\n            if (choosing) { SetObjective(\"DECIDE.\\n1 = hide it again    2 = send it to everyone\"); return; }\n            if (inspecting) { SetObjective(\"The inspection has begun.\\nKeep the phone hidden. Yours is the last desk.\"); return; }\n            if (!gotPhone) { SetObjective(\"Get the phone back.\\nLook down at the cubby (E), pull the loose panel.\"); return; }\n            if (!phone.OldPhotoFound) { SetObjective(\"Answer his questions (1 / 2 / 3, phone down).\\nCheck PHOTOS - the LAST photo.\"); return; }\n            SetObjective(\"Wait. He's starting the inspection.\");\n        }\n\n        void UpdateInteraction()\n        {\n            string p = null;\n            PlayerRig.Mode m = rig.CurrentMode;\n            if (m == PlayerRig.Mode.Seated || m == PlayerRig.Mode.Inspect)\n            {\n                if (m == PlayerRig.Mode.Inspect && GameInput.SpaceDown()) { rig.BackToSeat(); SetZone(true); SetPrompt(null); return; }\n                p = RaycastInteract();\n                if (p == null && m == PlayerRig.Mode.Inspect) p = \"[Space]  Sit back up\";\n            }\n            SetPrompt(p);\n        }\n\n        void UpdateDanger()\n        {\n            bool seen = phone.IsExposed && teacher != null && teacher.Running && vision != null && vision.CanSee(phoneExposurePoint.position, rig.transform);\n            // during the inspection he is close and paying attention: he notices faster\n            float secs = inspecting ? noticeSeconds * 0.7f : noticeSeconds;\n            bool searching = rig.CurrentMode == PlayerRig.Mode.Inspect && inspecting && teacher != null && vision != null && vision.CanSee(rig.eye.position, rig.transform, 4f);\n            float rate = seen ? 1f / Mathf.Max(0.05f, secs) : (searching ? 1f / 4f : 0f);\n            if (AccumulateDanger(rate))\n            {\n                if (seen) Strike(\"...Is that a device, \" + Name + \"?\");\n                else Strike(\"Hands out of the desk. I inspect it, not you.\");\n            }\n        }\n\n        protected override IEnumerator OnCaught()\n        {\n            calling = false;\n            questionBox.SetActive(false);\n            phone.allowRaise = false;\n            phone.CancelTask();\n            rig.Lock();\n            if (lecture != null) StopCoroutine(lecture);\n            Authority(\"That's three, \" + Name + \".\", 4f, true);\n            yield return WalkToYou();\n            yield return WaitIdle();\n            Authority(\"Give it to me. ...You'll thank me. Just like I was.\", 6f);\n            yield return WaitIdle();\n            PA(\"Inspection complete. One item found. Congratulations, Clearview!\", 5.5f);\n            yield return WaitIdle();\n            yield return Caught(\"inspected\");\n        }\n\n        // ------------------------------------------------------------------ lecture & questions\n        IEnumerator Lecture()\n        {\n            int i = 0;\n            bool pa = false;\n            while (!ended && !inspecting)\n            {\n                if (!calling && DialogueIdle && teacher != null && teacher.lines.Count > 0)\n                {\n                    int idx = i % teacher.lines.Count;\n                    if (idx > linesSaid) linesSaid = idx;\n                    Authority(teacher.lines[idx].text);\n                    i++;\n                    yield return WaitIdle();\n                    if (i == 4 && !pa) { pa = true; PA(\"Reminder: smiling during inspection is encouraged, but not required. It is encouraged.\"); yield return WaitIdle(); }\n                    float t = 0f;\n                    while (t < 3f && !ended) { if (DialogueIdle) t += Time.deltaTime; yield return null; }\n                }\n                yield return null;\n            }\n        }\n\n        void UpdateCalls()\n        {\n            if (!gotPhone || inspecting || teacher == null) return;\n            if (!calling)\n            {\n                if (nextCall > 0f) { nextCall -= Time.deltaTime; if (nextCall <= 0f) StartCall(); }\n                return;\n            }\n            callTimer -= Time.deltaTime;\n            questionTimer.rectTransform.anchorMax = new Vector2(Mathf.Clamp01(callTimer / answerSeconds), 1f);\n            bool canAnswer = rig.CurrentMode == PlayerRig.Mode.Seated && !phone.IsExposed;\n            if (phone.IsExposed) questionStatus.text = \"PUT THE PHONE DOWN to answer!  (release Right Mouse)\";\n            else if (rig.CurrentMode != PlayerRig.Mode.Seated) questionStatus.text = \"SIT UP to answer!  [Space]\";\n            else questionStatus.text = \"Press 1, 2 or 3\";\n            if (canAnswer)\n            {\n                int d = GameInput.DigitDown();\n                if (d >= 1 && d <= 3) { EndCall(d - 1 == question.correct, false); return; }\n            }\n            if (callTimer <= 0f) EndCall(false, true);\n        }\n\n        void StartCall()\n        {\n            question = PickQuestion();\n            if (question == null) { nextCall = 10f; return; }\n            calling = true;\n            callTimer = answerSeconds;\n            teacher.CallOn(rig.transform);\n            Authority(Name + \".  \" + question.question, answerSeconds + 1f, true);\n            string q = question.question + \"\\n\";\n            for (int i = 0; i < question.options.Length; i++) q += \"\\n\" + (i + 1) + \"    \" + question.options[i];\n            ShowQuestion(q);\n        }\n\n        LessonQuestion PickQuestion()\n        {\n            List<int> pool = new List<int>();\n            for (int i = 0; i < teacher.questions.Count; i++)\n                if (teacher.questions[i].aboutLine <= linesSaid && !asked.Contains(i)) pool.Add(i);\n            if (pool.Count == 0)\n            {\n                asked.Clear();\n                for (int i = 0; i < teacher.questions.Count; i++) if (teacher.questions[i].aboutLine <= linesSaid) pool.Add(i);\n            }\n            if (pool.Count == 0) return null;\n            int pick = pool[Random.Range(0, pool.Count)];\n            foreach (int i in pool) if (teacher.questions[i].aboutLine >= 0 && Random.value < 0.7f) { pick = i; break; }\n            asked.Add(pick);\n            return teacher.questions[pick];\n        }\n\n        void EndCall(bool correct, bool timedOut)\n        {\n            calling = false;\n            questionBox.SetActive(false);\n            teacher.EndCall();\n            nextCall = Random.Range(callInterval.x, callInterval.y);\n            if (correct) Authority(\"...Correct. You listen. Like I did.\", 4f, true);\n            else if (timedOut) Strike(\"I asked you a question, \" + Name + \".\");\n            else Strike(\"Wrong. Nobody in that seat has ever been wrong.\");\n        }\n    }\n}\n"},"LevelDirectorBase":{"path":"Assets/Game/Scripts/LevelDirectorBase.cs","role":"Shared chapter rules: subtitles, HUD, look-at interaction, danger and warnings, cards and fades.","source":"// @role Shared chapter rules: subtitles, HUD, look-at interaction, danger and warnings, cards and fades.\n// @calls PlayerRig, PhoneController, AmbientAudio, DangerFX, AudioSynth, UIFactory, GameInput, Interactable, RichText, GameFlow\n// @tune chances:int:1-5:Warnings before the phone is taken.\n// @tune noticeSeconds:float:0.5-6:Seconds seen with the phone before danger is full.\n// @tune dangerDecayPerSecond:float:0.05-2:How fast danger drains when nobody is looking.\n// @tune graceAfterWarning:float:0-10:Seconds of safety after a warning.\n// @tune interactDistance:float:0.5-4:Metres for the look-at interaction ray.\n// @tune teacherLineSeconds:float:2-15:Default seconds for an authority line.\n// @tune thoughtSeconds:float:2-15:Default seconds for a thought line.\n// @tune gapBetweenLines:float:0-5:Silence between subtitle lines.\n// @tune typeCharsPerSecond:float:10-150:Typewriter speed for subtitles.\n\nusing System.Collections;\nusing System.Collections.Generic;\nusing Unity.AI.Navigation;\nusing UnityEngine;\nusing UnityEngine.UI;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Everything the four chapters share:\n    ///  - ONE subtitle at a time: authority / students / PA at the top, the player's thoughts bottom-left.\n    ///    Text is typed in (typewriter), with a small \"voice\" blip per speaker.\n    ///  - Interaction ray (look at something + E), prompts.\n    ///  - Danger: while a watcher can see what you're doing, the phone shakes and turns red, the screen edges\n    ///    go red and the music turns sour. Full = a warning. Three warnings, never shown as numbers.\n    ///  - Warning feedback: red \"WARNING\" flash, a low hit, and sudden silence.\n    ///  - Chapter cards, fades, finishing the level.\n    /// </summary>\n    public abstract class LevelDirectorBase : MonoBehaviour\n    {\n        [Header(\"Core references (filled by the scene builder)\")]\n        public PlayerRig rig;\n        public PhoneController phone;\n        public NavMeshSurface navSurface;\n        public Transform phoneExposurePoint;\n\n        [Header(\"Rules\")]\n        public int chances = 3;\n        [Tooltip(\"Seconds of being seen with the phone until he notices (phone fully red).\")]\n        public float noticeSeconds = 2.5f;\n        public float dangerDecayPerSecond = 0.35f;\n        public float graceAfterWarning = 3f;\n        public float interactDistance = 1.8f;\n\n        [Header(\"Subtitle timing (seconds)\")]\n        public float teacherLineSeconds = 7.5f;\n        public float thoughtSeconds = 7.5f;\n        public float gapBetweenLines = 1.4f;\n        public float typeCharsPerSecond = 55f;\n        public bool voiceBlips = true;\n\n        protected enum Who { Authority, Student, Thought, PA }\n        protected class Line { public Who who; public string speaker; public string text; public float seconds; public float gap; }\n\n        protected int strikes;\n        protected float danger, grace;\n        protected bool ended;\n        protected AmbientAudio ambient;\n        protected DangerFX dangerFx;\n        /// <summary>Label shown above the authority's lines (\"TEACHER\", \"LUNCH MONITOR\"...).</summary>\n        protected string authorityLabel = \"TEACHER\";\n        protected float authorityPitch = 0.8f;\n        protected string Name { get { return GameFlow.playerName; } }\n\n        readonly Queue<Line> queue = new Queue<Line>();\n        Line current;\n        float currentLeft, gapLeft, reveal;\n        int revealedShown;\n        string currentFull = \"\";\n\n        // HUD\n        protected Image fade, questionTimer;\n        protected Text speechText, speechWho, thoughtText, prompt, caption, questionText, questionStatus;\n        protected GameObject questionBox, speechBox, thoughtBox, promptBox;\n        Image speechBg, speechAccent, paStripe;\n        Text warningText;\n        float warningT;\n        GameObject chapterRoot;\n        Text chapterLabelText, chapterTitleText, chapterTimeText, chapterSloganText;\n        Image lidTop, lidBottom, lidDark;\n        Text objectiveText, objectiveLabel;\n        Image objectiveBg, objectiveDivider;\n        RectTransform objectivePanel;\n        float objectiveFlash;\n        string actionShown = \"\";\n        static readonly Color PanelBg = new Color(0.05f, 0.055f, 0.06f, 0.9f);\n        static readonly Color Amber = new Color(1f, 0.8f, 0.45f);\n        const float PanelW = 380f, PanelPad = 20f;\n        float lids;\n\n        static readonly Color SpeechBg = new Color(0.07f, 0.08f, 0.09f, 0.88f);\n        static readonly Color SpeechInk = new Color(0.96f, 0.94f, 0.9f);\n        static readonly Color Red = new Color(0.78f, 0.12f, 0.1f);\n\n        // ------------------------------------------------------------------ lifecycle\n        protected virtual void Awake()\n        {\n            RemoveOtherCameras();\n            BuildHUD();\n            ambient = AmbientAudio.Create(transform);\n            dangerFx = DangerFX.Create(transform);\n        }\n\n        protected virtual void Start()\n        {\n            Cursor.lockState = CursorLockMode.Locked;\n            Cursor.visible = false;\n            if (navSurface != null) navSurface.BuildNavMesh();\n        }\n\n        protected virtual void Update()\n        {\n            if (GameInput.EscDown()) { Cursor.lockState = CursorLockMode.None; Cursor.visible = true; }\n            if (GameInput.LeftDown() && Cursor.lockState != CursorLockMode.Locked) { Cursor.lockState = CursorLockMode.Locked; Cursor.visible = false; }\n            if (GameInput.SkipDown() && !ended) { StopAllCoroutines(); StartCoroutine(FinishLevel(\"skip\", 0.4f)); }\n            TickDialogue();\n            TickHUD();\n            PlacePrompt();\n            LevelAlways();\n            if (ended)\n            {\n                if (phone != null) phone.danger = 0f;\n                danger = Mathf.MoveTowards(danger, 0f, Time.deltaTime);\n                ambient.dangerLevel = 0f;\n                dangerFx.level = 0f;\n                return;\n            }\n            LevelUpdate();\n            ambient.dangerLevel = danger;\n            dangerFx.level = danger;\n        }\n\n        /// <summary>Runs every frame, even after the level has ended.</summary>\n        protected virtual void LevelAlways() { }\n\n        /// <summary>Runs every frame while the level is being played.</summary>\n        protected abstract void LevelUpdate();\n\n        /// <summary>Third warning: what happens when they take the phone. Must end with GameFlow.EndLevel.</summary>\n        protected abstract IEnumerator OnCaught();\n\n        /// <summary>Gameplay is always seen through the player's eyes; any other camera (e.g. a FlyCamera) is removed.</summary>\n        void RemoveOtherCameras()\n        {\n            Transform mine = rig != null ? rig.transform : transform;\n            foreach (Camera c in FindObjectsByType<Camera>(FindObjectsInactive.Include, FindObjectsSortMode.None))\n            {\n                if (c.transform.IsChildOf(mine)) continue;\n                GameObject root = c.gameObject;\n                foreach (MonoBehaviour mb in c.GetComponentsInParent<MonoBehaviour>(true))\n                    if (mb != null && mb.GetType().Name == \"FlyCameraController\") { root = mb.gameObject; break; }\n                root.SetActive(false);\n                Destroy(root);\n            }\n            foreach (AudioListener l in FindObjectsByType<AudioListener>(FindObjectsInactive.Include, FindObjectsSortMode.None))\n                if (!l.transform.IsChildOf(mine)) Destroy(l);\n            if (rig != null && rig.eye != null)\n            {\n                Camera own = rig.eye.GetComponent<Camera>();\n                if (own != null) { own.enabled = true; own.gameObject.tag = \"MainCamera\"; }\n            }\n        }\n\n        // ------------------------------------------------------------------ dialogue: one line at a time\n        protected void Say(Who who, string speaker, string text, float seconds, bool interrupt = false, float gap = -1f)\n        {\n            Line l = new Line { who = who, speaker = speaker, text = text, seconds = seconds, gap = gap >= 0f ? gap : gapBetweenLines };\n            if (interrupt) { queue.Clear(); Show(l); }\n            else queue.Enqueue(l);\n        }\n\n        protected void Authority(string text, float seconds = -1f, bool interrupt = false, float gap = -1f)\n        {\n            Say(Who.Authority, authorityLabel, text, seconds > 0f ? seconds : teacherLineSeconds, interrupt, gap);\n        }\n\n        protected void Thought(string text, float seconds = -1f, bool interrupt = false, float gap = -1f)\n        {\n            Say(Who.Thought, \"\", text, seconds > 0f ? seconds : thoughtSeconds, interrupt, gap);\n        }\n\n        protected void PA(string text, float seconds = -1f, bool interrupt = false, float gap = -1f)\n        {\n            Say(Who.PA, \"PA SYSTEM\", text, seconds > 0f ? seconds : teacherLineSeconds, interrupt, gap);\n        }\n\n        protected void StudentSay(string speaker, string text, float seconds, bool interrupt = false, float gap = -1f)\n        {\n            Say(Who.Student, speaker, text, seconds, interrupt, gap);\n        }\n\n        void Show(Line l)\n        {\n            current = l;\n            currentLeft = l.seconds;\n            currentFull = l.text ?? \"\";\n            reveal = 0f;\n            revealedShown = 0;\n            bool speech = l.who != Who.Thought;\n            speechBox.SetActive(speech);\n            thoughtBox.SetActive(!speech);\n            if (speech)\n            {\n                // PA announcements use the same dark subtitle as everyone else (a white box read like a phone notification)\n                bool pa = l.who == Who.PA;\n                speechBg.color = SpeechBg;\n                speechAccent.color = pa ? new Color(0.6f, 0.62f, 0.66f) : Red;\n                paStripe.enabled = false;\n                speechWho.text = pa ? \"LOUDSPEAKER  (school announcement)\" : (l.speaker ?? \"\").ToUpper();\n                speechWho.color = pa ? new Color(0.72f, 0.74f, 0.78f) : new Color(1f, 0.45f, 0.38f);\n                speechText.color = SpeechInk;\n                speechText.text = \"\";\n                if (pa) ambient.Play(AudioSynth.Chime(), 0.35f);\n            }\n            else thoughtText.text = \"\";\n        }\n\n        protected void ClearLine()\n        {\n            gapLeft = current != null ? current.gap : gapBetweenLines;\n            current = null;\n            speechBox.SetActive(false);\n            thoughtBox.SetActive(false);\n        }\n\n        void TickDialogue()\n        {\n            if (current != null)\n            {\n                int total = RichText.VisibleLength(currentFull);\n                if (revealedShown < total)\n                {\n                    // PA lines wait for the chime before they start typing\n                    float delay = current.who == Who.PA ? 0.6f : 0f;\n                    reveal += Time.deltaTime * typeCharsPerSecond;\n                    int shown = Mathf.Clamp(Mathf.FloorToInt(reveal - delay * typeCharsPerSecond), 0, total);\n                    if (shown != revealedShown)\n                    {\n                        for (int i = revealedShown; i < shown; i++) Voice(current, i);\n                        revealedShown = shown;\n                        string s = shown >= total ? currentFull : RichText.Reveal(currentFull, shown);\n                        if (current.who == Who.Thought) thoughtText.text = s; else speechText.text = s;\n                    }\n                }\n                currentLeft -= Time.deltaTime;\n                if (currentLeft <= 0f) ClearLine();\n                return;\n            }\n            if (gapLeft > 0f) { gapLeft -= Time.deltaTime; return; }\n            if (queue.Count > 0) Show(queue.Dequeue());\n        }\n\n        void Voice(Line l, int index)\n        {\n            if (!voiceBlips) return;\n            char ch = RichText.VisibleChar(currentFull, index);\n            if (!char.IsLetter(ch)) return;\n            if (l.who == Who.Thought)\n            {\n                if (index % 3 == 0) ambient.Play(AudioSynth.Tick(), 0.08f, Random.Range(0.9f, 1.1f));\n                return;\n            }\n            if (index % 3 != 0) return;\n            float p = l.who == Who.Authority ? authorityPitch : (l.who == Who.PA ? 1.25f : 1.35f);\n            ambient.Play(AudioSynth.Blip(), l.who == Who.PA ? 0.12f : 0.17f, p * Random.Range(0.93f, 1.07f));\n        }\n\n        protected bool DialogueIdle { get { return current == null && queue.Count == 0 && gapLeft <= 0f; } }\n\n        protected IEnumerator WaitIdle() { while (!DialogueIdle) yield return null; }\n\n        /// <summary>When something else should keep a reminder quiet (questions, roll call...).</summary>\n        protected virtual bool ReminderBlocked() { return false; }\n\n        /// <summary>Repeats a thought every 'every' seconds (only when nothing else is being said) until 'done'.</summary>\n        protected IEnumerator Reminder(string text, System.Func<bool> done, float every)\n        {\n            while (!ended && !done())\n            {\n                while (!ended && !done() && (!DialogueIdle || ReminderBlocked())) yield return null;\n                if (ended || done()) yield break;\n                Thought(text);\n                float t = 0f;\n                while (t < every && !done()) { t += Time.deltaTime; yield return null; }\n            }\n        }\n\n        /// <summary>Rules in the player's thoughts are highlighted so they stand out.</summary>\n        protected static string Rule(string s) { return \"<b><color=#ff9a6e>\" + s + \"</color></b>\"; }\n\n        // ------------------------------------------------------------------ interaction\n        /// <summary>Raycast from the eye; returns the prompt to show (or null) and uses the thing on [E].</summary>\n        protected string RaycastInteract()\n        {\n            if (rig == null || rig.eye == null) return null;\n            if (phone != null && phone.IsExposed) return null;\n            RaycastHit[] hits = Physics.RaycastAll(rig.eye.position, rig.eye.forward, interactDistance, ~0, QueryTriggerInteraction.Collide);\n            System.Array.Sort(hits, (a, b) => a.distance.CompareTo(b.distance));\n            foreach (RaycastHit hit in hits)\n            {\n                if (hit.transform.IsChildOf(rig.transform)) continue;\n                Interactable it = hit.collider.GetComponentInParent<Interactable>();\n                if (it != null && it.active && it.onUse != null)\n                {\n                    if (GameInput.InteractDown()) it.onUse();\n                    return \"[E]  \" + it.prompt;\n                }\n                if (!hit.collider.isTrigger) return null;   // something solid is in front\n            }\n            return null;\n        }\n\n        /// <summary>\n        /// What you can do right now ([E] ..., phone hints): under the crosshair. While the phone is up the box\n        /// slides to the right of the phone, so it never covers the screen.\n        /// </summary>\n        protected void SetPrompt(string p)\n        {\n            string t = p ?? \"\";\n            if (t == actionShown) return;\n            actionShown = t;\n            prompt.text = t;\n            promptBox.SetActive(t.Length > 0);\n            if (t.Length > 0)\n            {\n                float w = Mathf.Clamp(prompt.preferredWidth + 48f, 260f, 640f);\n                RectTransform rt = (RectTransform)promptBox.transform;\n                rt.sizeDelta = new Vector2(w, 10f);\n                rt.sizeDelta = new Vector2(w, Mathf.Ceil(prompt.preferredHeight) + 22f);\n            }\n        }\n\n        void PlacePrompt()\n        {\n            if (promptBox == null || !promptBox.activeSelf) return;\n            RectTransform rt = (RectTransform)promptBox.transform;\n            bool phoneUp = phone != null && phone.IsExposed;\n            Vector2 want = phoneUp ? new Vector2(270f + rt.sizeDelta.x * 0.5f, -150f) : new Vector2(0f, -90f);\n            rt.anchoredPosition = Vector2.Lerp(rt.anchoredPosition, want, 1f - Mathf.Exp(-Time.unscaledDeltaTime * 14f));\n        }\n\n        /// <summary>Sizes the panel to its text, so nothing ever runs outside the background.</summary>\n        void LayoutPanel()\n        {\n            if (objectivePanel == null) return;\n            bool hasObj = !string.IsNullOrEmpty(objectiveText.text);\n            objectiveLabel.gameObject.SetActive(hasObj);\n            objectiveDivider.gameObject.SetActive(hasObj);\n            objectiveText.gameObject.SetActive(hasObj);\n            float y = 12f;\n            if (hasObj)\n            {\n                y = 46f;\n                float oh = Mathf.Ceil(objectiveText.preferredHeight) + 2f;\n                objectiveText.rectTransform.anchoredPosition = new Vector2(PanelPad, -y);\n                objectiveText.rectTransform.sizeDelta = new Vector2(PanelW - PanelPad * 2f, oh);\n                y += oh + 12f;\n            }\n            objectivePanel.sizeDelta = new Vector2(PanelW, y);\n            objectivePanel.gameObject.SetActive(hasObj);\n        }\n\n        // ------------------------------------------------------------------ danger & warnings\n        /// <summary>\n        /// rate = how fast he notices (1/seconds); 0 = nobody is looking (it drains back).\n        /// Returns true when the danger is full: a warning must be given.\n        /// </summary>\n        protected bool AccumulateDanger(float rate)\n        {\n            if (grace > 0f) grace -= Time.deltaTime;\n            if (rate > 0f && grace <= 0f) danger += Time.deltaTime * rate;\n            else danger -= Time.deltaTime * dangerDecayPerSecond;\n            danger = Mathf.Clamp01(danger);\n            if (phone != null) phone.danger = phone.IsExposed ? danger : 0f;\n            if (danger >= 1f)\n            {\n                danger = 0f;\n                grace = graceAfterWarning;\n                if (phone != null) phone.Flash();\n                return true;\n            }\n            return false;\n        }\n\n        /// <summary>The warning count spoken after the line (never shown as a number on screen).</summary>\n        protected virtual string StrikeSuffix(int n, bool pa)\n        {\n            if (pa) return n == 1 ? \"  This is your first reminder. You will receive three.\" : \"  This is your second reminder. There is no fourth reminder.\";\n            return n == 1 ? \"  That's one warning. You get three.\" : \"  That's two. One more, and whatever you're hiding is mine.\";\n        }\n\n        /// <summary>One of the three chances is used. Only the voices tell the player.</summary>\n        protected void Strike(string line, bool pa = false)\n        {\n            if (ended) return;\n            strikes++;\n            warningT = 1.6f;\n            dangerFx.Flash();\n            ambient.Play(AudioSynth.Stinger(), 0.7f);\n            ambient.Duck(1.6f);\n            if (strikes >= chances) { ended = true; StartCoroutine(OnCaught()); return; }\n            if (pa) PA(line + StrikeSuffix(strikes, true), 7.5f, true);\n            else Authority(line + StrikeSuffix(strikes, false), 7f, true);\n        }\n\n        // ------------------------------------------------------------------ cards, fades, endings\n        protected IEnumerator Fade(float from, float to, float seconds)\n        {\n            for (float t = 0f; t < seconds; t += Time.unscaledDeltaTime)\n            {\n                Color c = fade.color; c.a = Mathf.Lerp(from, to, t / seconds); fade.color = c;\n                yield return null;\n            }\n            Color e = fade.color; e.a = to; fade.color = e;\n        }\n\n        /// <summary>Black card with typed chapter info, then fades into the level. Any key skips the wait.</summary>\n        protected IEnumerator ChapterCard(string label, string title, string time, float hold = 2.2f)\n        {\n            Color fc = fade.color; fc.a = 1f; fade.color = fc;\n            chapterRoot.SetActive(true);\n            chapterLabelText.text = \"\"; chapterTitleText.text = \"\"; chapterTimeText.text = \"\"; chapterSloganText.text = \"\";\n            yield return TypeInto(chapterLabelText, label, 30f);\n            yield return TypeInto(chapterTitleText, title, 18f);\n            yield return TypeInto(chapterTimeText, time, 30f);\n            chapterSloganText.text = \"CLEARVIEW ACADEMY  -  WHAT IS SEEN, IS SAFE.\";\n            float t = 0f;\n            while (t < hold && !GameInput.AnyKeyDown()) { t += Time.deltaTime; yield return null; }\n            chapterRoot.SetActive(false);\n            yield return Fade(1f, 0f, 1.2f);\n        }\n\n        IEnumerator TypeInto(Text t, string s, float cps)\n        {\n            for (int i = 1; i <= s.Length; i++)\n            {\n                t.text = s.Substring(0, i);\n                if (char.IsLetterOrDigit(s[i - 1])) ambient.Play(AudioSynth.Tick(), 0.12f, Random.Range(0.9f, 1.1f));\n                float w = 1f / cps;\n                while (w > 0f) { w -= Time.deltaTime; yield return null; }\n            }\n        }\n\n        /// <summary>Fade out and report a win to the game flow.</summary>\n        protected IEnumerator FinishLevel(string reason, float fadeSeconds = 1.4f)\n        {\n            ended = true;\n            SetObjective(\"\");\n            yield return Fade(0f, 1f, fadeSeconds);\n            GameFlow.EndLevel(LessonResult.Win, reason);\n        }\n\n        protected IEnumerator Caught(string reason, float fadeSeconds = 1.2f)\n        {\n            ended = true;\n            SetObjective(\"\");\n            yield return Fade(0f, 1f, fadeSeconds);\n            GameFlow.EndLevel(LessonResult.Caught, reason);\n        }\n\n        /// <summary>\n        /// The current goal, always visible top-left (what to do + where). Changing it flashes the box and chimes,\n        /// so the player never has to guess the next step. null/empty hides it.\n        /// </summary>\n        protected void SetObjective(string text)\n        {\n            if (objectiveText == null) return;\n            string t = text ?? \"\";\n            if (objectiveText.text == t) return;\n            objectiveText.text = t;\n            LayoutPanel();\n            if (t.Length > 0) { objectiveFlash = 1.2f; ambient.Play(AudioSynth.Confirm(), 0.18f, 1.3f); }\n        }\n\n        /// <summary>Buzz in your pocket (phone notification).</summary>\n        protected void PhoneBuzz()\n        {\n            ambient.Play(AudioSynth.Vibrate(), 0.5f);\n        }\n\n        /// <summary>Eyelids: 0 = open, 1 = shut (lying down in bed).</summary>\n        protected void SetLids(float v) { lids = Mathf.Clamp01(v); }\n\n        protected void ShowQuestion(string text)\n        {\n            questionText.text = text;\n            questionStatus.text = \"\";\n            questionTimer.rectTransform.anchorMax = Vector2.one;\n            questionBox.SetActive(true);\n        }\n\n        // ------------------------------------------------------------------ HUD\n        void TickHUD()\n        {\n            if (warningT > 0f)\n            {\n                warningT -= Time.unscaledDeltaTime;\n                bool on = Mathf.Repeat(warningT, 0.4f) > 0.15f;\n                warningText.enabled = warningT > 0f && on;\n            }\n            else warningText.enabled = false;\n\n            if (objectiveFlash > 0f)\n            {\n                objectiveFlash -= Time.unscaledDeltaTime;\n                bool on = Mathf.Repeat(objectiveFlash, 0.3f) > 0.12f;\n                objectiveBg.color = on ? new Color(0.42f, 0.09f, 0.07f, 0.94f) : PanelBg;\n            }\n            else if (objectiveBg != null) objectiveBg.color = PanelBg;\n\n            float h = Mathf.Lerp(0f, 560f, lids);\n            lidTop.rectTransform.sizeDelta = new Vector2(0f, h);\n            lidBottom.rectTransform.sizeDelta = new Vector2(0f, h);\n            lidDark.color = new Color(0f, 0f, 0f, lids * 0.55f);\n        }\n\n        void BuildHUD()\n        {\n            Canvas canvas = UIFactory.MakeCanvas(\"HUD\", 40);   // above the phone, so subtitles are never covered\n            canvas.transform.SetParent(transform, false);\n            Transform root = canvas.transform;\n\n            // eyelids (lying in bed)\n            lidDark = UIFactory.AddImage(UIFactory.Stretch(\"LidDark\", root), new Color(0f, 0f, 0f, 0f));\n            lidTop = UIFactory.AddImage(UIFactory.Rect(\"LidTop\", root, new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0.5f, 1f), Vector2.zero, Vector2.zero), Color.black);\n            lidBottom = UIFactory.AddImage(UIFactory.Rect(\"LidBottom\", root, new Vector2(0f, 0f), new Vector2(1f, 0f), new Vector2(0.5f, 0f), Vector2.zero, Vector2.zero), Color.black);\n\n            UIFactory.AddImage(UIFactory.Centered(\"Crosshair\", root, 0f, 0f, 6f, 6f), new Color(1f, 1f, 1f, 0.75f));\n\n            // OBJECTIVE + what you can do now - top-left panel that grows with its text\n            objectivePanel = UIFactory.Rect(\"Objective\", root, new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(28f, -170f), new Vector2(PanelW, 100f));\n            objectiveBg = UIFactory.AddImage(objectivePanel, PanelBg);\n            UIFactory.AddImage(UIFactory.Rect(\"Bar\", objectivePanel, new Vector2(0f, 0f), new Vector2(0f, 1f), new Vector2(0f, 0.5f), Vector2.zero, new Vector2(5f, 0f)), Amber);\n            objectiveLabel = UIFactory.AddText(UIFactory.TopLeft(\"Label\", objectivePanel, PanelPad, 12f, PanelW - 2f * PanelPad, 22f), \"OBJECTIVE\", 16, Amber, TextAnchor.UpperLeft);\n            objectiveLabel.fontStyle = FontStyle.Bold;\n            objectiveDivider = UIFactory.AddImage(UIFactory.TopLeft(\"Divider\", objectivePanel, PanelPad, 37f, PanelW - 2f * PanelPad, 1f), new Color(1f, 0.8f, 0.45f, 0.35f));\n            objectiveText = UIFactory.AddText(UIFactory.TopLeft(\"Text\", objectivePanel, PanelPad, 46f, PanelW - 2f * PanelPad, 40f), \"\", 19, new Color(0.95f, 0.94f, 0.9f), TextAnchor.UpperLeft);\n            objectiveText.lineSpacing = 1.1f;\n            // interaction / keyboard prompt - under the crosshair (moves beside the phone while it is up)\n            RectTransform pb = UIFactory.Centered(\"Prompt\", root, 0f, -90f, 420f, 52f);\n            UIFactory.AddImage(pb, new Color(0.05f, 0.055f, 0.06f, 0.82f));\n            UIFactory.AddImage(UIFactory.Rect(\"Bar\", pb, new Vector2(0f, 0f), new Vector2(0f, 1f), new Vector2(0f, 0.5f), Vector2.zero, new Vector2(4f, 0f)), Amber);\n            prompt = UIFactory.AddText(UIFactory.Rect(\"Text\", pb, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), new Vector2(2f, 0f), new Vector2(-28f, -12f)), \"\", 22, Color.white, TextAnchor.MiddleCenter);\n            prompt.fontStyle = FontStyle.Bold;\n            prompt.horizontalOverflow = HorizontalWrapMode.Wrap;\n            promptBox = pb.gameObject;\n            promptBox.SetActive(false);\n            objectivePanel.gameObject.SetActive(false);\n\n            // SPEECH / PA - top\n            RectTransform sb = UIFactory.Rect(\"Speech\", root, new Vector2(0.5f, 1f), new Vector2(0.5f, 1f), new Vector2(0.5f, 1f), new Vector2(0f, -36f), new Vector2(1500f, 118f));\n            speechBg = UIFactory.AddImage(sb, SpeechBg);\n            speechAccent = UIFactory.AddImage(UIFactory.Rect(\"Accent\", sb, new Vector2(0f, 0f), new Vector2(0f, 1f), new Vector2(0f, 0.5f), Vector2.zero, new Vector2(10f, 0f)), Red);\n            paStripe = UIFactory.AddImage(UIFactory.Rect(\"PaStripe\", sb, new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0.5f, 1f), Vector2.zero, new Vector2(0f, 6f)), new Color(0.62f, 0.85f, 0.76f));\n            speechWho = UIFactory.AddText(UIFactory.TopLeft(\"Who\", sb, 30f, 10f, 1200f, 30f), \"\", 21, new Color(1f, 0.45f, 0.38f), TextAnchor.UpperLeft);\n            speechWho.fontStyle = FontStyle.Bold;\n            speechText = UIFactory.AddText(UIFactory.Rect(\"Text\", sb, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), new Vector2(6f, -12f), new Vector2(-60f, -44f)), \"\", 28, SpeechInk, TextAnchor.MiddleCenter);\n            speechBox = sb.gameObject;\n            speechBox.SetActive(false);\n\n            // WARNING flash\n            warningText = UIFactory.AddText(UIFactory.Rect(\"Warning\", root, new Vector2(0.5f, 1f), new Vector2(0.5f, 1f), new Vector2(0.5f, 1f), new Vector2(0f, -190f), new Vector2(900f, 90f)), \"WARNING\", 72, new Color(1f, 0.12f, 0.08f), TextAnchor.MiddleCenter);\n            warningText.fontStyle = FontStyle.Bold;\n            UIFactory.AddShadow(warningText, new Color(0f, 0f, 0f, 0.9f), 3f);\n            warningText.enabled = false;\n\n            // PLAYER thoughts / instructions - bottom left (the phone sits bottom centre)\n            RectTransform tb = UIFactory.Rect(\"Thoughts\", root, new Vector2(0f, 0f), new Vector2(0f, 0f), new Vector2(0f, 0f), new Vector2(40f, 40f), new Vector2(660f, 160f));\n            UIFactory.AddImage(tb, new Color(0.08f, 0.06f, 0.02f, 0.82f));\n            UIFactory.AddImage(UIFactory.Rect(\"Accent\", tb, new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0.5f, 1f), Vector2.zero, new Vector2(0f, 4f)), new Color(1f, 0.8f, 0.45f, 0.8f));\n            thoughtText = UIFactory.AddText(UIFactory.Rect(\"Text\", tb, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(-40f, -26f)), \"\", 26, new Color(1f, 0.86f, 0.5f), TextAnchor.MiddleLeft);\n            thoughtText.fontStyle = FontStyle.Italic;\n            thoughtBox = tb.gameObject;\n            thoughtBox.SetActive(false);\n\n            // question / roll-call answer / choices - left middle\n            RectTransform qb = UIFactory.Rect(\"Question\", root, new Vector2(0f, 0.5f), new Vector2(0f, 0.5f), new Vector2(0f, 0.5f), new Vector2(40f, -70f), new Vector2(640f, 310f));\n            UIFactory.AddImage(qb, new Color(0.05f, 0.05f, 0.06f, 0.92f));\n            UIFactory.AddImage(UIFactory.Rect(\"Bar\", qb, new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0.5f, 1f), Vector2.zero, new Vector2(0f, 6f)), Red);\n            questionText = UIFactory.AddText(UIFactory.TopLeft(\"Q\", qb, 24f, 22f, 592f, 200f), \"\", 26, Color.white, TextAnchor.UpperLeft);\n            questionStatus = UIFactory.AddText(UIFactory.TopLeft(\"Status\", qb, 24f, 236f, 592f, 40f), \"\", 22, new Color(1f, 0.7f, 0.4f), TextAnchor.UpperLeft);\n            questionStatus.fontStyle = FontStyle.Bold;\n            RectTransform tbar = UIFactory.TopLeft(\"TimerBG\", qb, 24f, 284f, 592f, 10f);\n            UIFactory.AddImage(tbar, new Color(1f, 1f, 1f, 0.15f));\n            questionTimer = UIFactory.AddImage(UIFactory.Rect(\"Timer\", tbar, Vector2.zero, Vector2.one, new Vector2(0f, 0.5f), Vector2.zero, Vector2.zero), new Color(1f, 0.4f, 0.3f));\n            questionBox = qb.gameObject;\n            questionBox.SetActive(false);\n\n            fade = UIFactory.AddImage(UIFactory.Stretch(\"Fade\", root), Color.black);\n            caption = UIFactory.AddText(UIFactory.Centered(\"Caption\", root, 0f, 0f, 1400f, 100f), \"\", 40, new Color(0.9f, 0.9f, 0.9f), TextAnchor.MiddleCenter);\n\n            // chapter card (on top of the fade)\n            RectTransform cr = UIFactory.Stretch(\"ChapterCard\", root);\n            chapterRoot = cr.gameObject;\n            chapterLabelText = UIFactory.AddText(UIFactory.Centered(\"Label\", cr, 0f, 120f, 1400f, 50f), \"\", 28, new Color(0.6f, 0.6f, 0.6f), TextAnchor.MiddleCenter);\n            chapterTitleText = UIFactory.AddText(UIFactory.Centered(\"Title\", cr, 0f, 30f, 1600f, 120f), \"\", 92, new Color(0.94f, 0.92f, 0.86f), TextAnchor.MiddleCenter);\n            chapterTitleText.fontStyle = FontStyle.Bold;\n            chapterTimeText = UIFactory.AddText(UIFactory.Centered(\"Time\", cr, 0f, -70f, 1400f, 50f), \"\", 30, new Color(0.7f, 0.7f, 0.7f), TextAnchor.MiddleCenter);\n            chapterSloganText = UIFactory.AddText(UIFactory.Rect(\"Slogan\", cr, new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0f, 60f), new Vector2(1400f, 40f)), \"\", 20, new Color(0.75f, 0.2f, 0.18f), TextAnchor.MiddleCenter);\n            chapterRoot.SetActive(false);\n        }\n    }\n}\n"},"PatrolAI":{"path":"Assets/Game/Scripts/PatrolAI.cs","role":"NavMesh watcher: roams random points, follows level routes, approaches or holds to look at you.","source":"// @role NavMesh watcher: roams random points, follows level routes, approaches or holds to look at you.\n// @tune waitTime:Vector2:0-10:Seconds waiting at a roam point (x to y).\n// @tune scanAngle:float:0-120:Degrees the head sweeps while waiting.\n// @tune scanSpeed:float:0.1-2:Head sweep speed.\n\nusing System.Collections.Generic;\nusing UnityEngine;\nusing UnityEngine.AI;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// A walking watcher on a NavMesh (lunch monitor, night warden): goes around furniture, never through it.\n    ///   ROAM  - picks random points inside roamRect, waits there and looks around.\n    ///   ROUTE - follows a list of points given by the level (waits + facing per point), then reports back.\n    ///   APPROACH / HOLD - the level takes over (coming to take the phone, staring at you...).\n    /// </summary>\n    [RequireComponent(typeof(NavMeshAgent))]\n    public class PatrolAI : MonoBehaviour\n    {\n        [Tooltip(\"Random points are picked inside this rectangle (x min, z min, x max, z max).\")]\n        public Vector4 roamRect = new Vector4(15f, 0.8f, 29f, 9.5f);\n        public Vector2 waitTime = new Vector2(2f, 4.5f);\n        [Tooltip(\"While waiting, the head sweeps left/right by this many degrees.\")]\n        public float scanAngle = 55f;\n        public float scanSpeed = 0.6f;\n        public bool roamOnBegin = true;\n\n        public bool Running { get; private set; }\n        public bool HasArrived { get { return arrived; } }\n        public bool RouteDone { get { return route == null; } }\n\n        NavMeshAgent agent;\n        Transform visual;\n        bool arrived, holding, waiting;\n        float waitLeft, baseYaw, scanT, sinceGo;\n        Transform lookAt;\n        Vector3[] route;\n        float[] routeWaits, routeYaws;\n        int routeIndex;\n        System.Action onRouteDone;\n\n        void Awake()\n        {\n            agent = GetComponent<NavMeshAgent>();\n            agent.enabled = false;   // enabled after the NavMesh is built\n            visual = new GameObject(\"Visual\").transform;\n            List<Transform> kids = new List<Transform>();\n            foreach (Transform c in transform) kids.Add(c);\n            visual.SetParent(transform, false);\n            foreach (Transform c in kids) c.SetParent(visual, false);\n        }\n\n        public void Begin()\n        {\n            agent.enabled = true;\n            NavMeshHit hit;\n            if (NavMesh.SamplePosition(transform.position, out hit, 2f, NavMesh.AllAreas)) agent.Warp(hit.position);\n            Running = true;\n            if (roamOnBegin) NextRoam();\n            else { arrived = true; waiting = true; waitLeft = 9999f; baseYaw = transform.eulerAngles.y; }\n        }\n\n        /// <summary>Walk a list of points. waits[i] = seconds at point i; yaws[i] = facing there (NaN = keep).</summary>\n        public void RunRoute(Vector3[] points, float[] waits, float[] yaws, System.Action done)\n        {\n            holding = false;\n            lookAt = null;\n            route = points;\n            routeWaits = waits;\n            routeYaws = yaws;\n            routeIndex = 0;\n            onRouteDone = done;\n            Go(route[0]);\n        }\n\n        public void Approach(Vector3 point, Transform look)\n        {\n            route = null;\n            holding = true;\n            lookAt = look;\n            Go(point);\n        }\n\n        public void Hold(Transform look)\n        {\n            route = null;\n            holding = true;\n            lookAt = look;\n            Stop();\n        }\n\n        public void ResumeRoam()\n        {\n            holding = false;\n            lookAt = null;\n            route = null;\n            NextRoam();\n        }\n\n        void Update()\n        {\n            if (!Running || !agent.enabled) return;\n            sinceGo += Time.deltaTime;\n\n            if (!arrived && sinceGo > 0.3f && !agent.pathPending && agent.remainingDistance <= agent.stoppingDistance + 0.05f)\n            {\n                arrived = true;\n                agent.isStopped = true;\n                OnArrive();\n            }\n\n            if (holding)\n            {\n                if (arrived && lookAt != null) Face(lookAt.position - transform.position, 220f);\n                return;\n            }\n\n            if (arrived && waiting)\n            {\n                scanT += Time.deltaTime * scanSpeed;\n                float yawNow = baseYaw + Mathf.Sin(scanT * Mathf.PI) * scanAngle;\n                transform.rotation = Quaternion.RotateTowards(transform.rotation, Quaternion.Euler(0f, yawNow, 0f), 140f * Time.deltaTime);\n                waitLeft -= Time.deltaTime;\n                if (waitLeft <= 0f) Next();\n            }\n        }\n\n        void OnArrive()\n        {\n            if (holding) return;\n            waiting = true;\n            scanT = 0f;\n            baseYaw = transform.eulerAngles.y;\n            if (route != null)\n            {\n                float y = (routeYaws != null && routeIndex < routeYaws.Length) ? routeYaws[routeIndex] : float.NaN;\n                if (!float.IsNaN(y)) baseYaw = y;\n                waitLeft = (routeWaits != null && routeIndex < routeWaits.Length) ? routeWaits[routeIndex] : 0f;\n            }\n            else waitLeft = Random.Range(waitTime.x, waitTime.y);\n        }\n\n        void Next()\n        {\n            waiting = false;\n            if (route != null)\n            {\n                routeIndex++;\n                if (routeIndex < route.Length) { Go(route[routeIndex]); return; }\n                route = null;\n                System.Action cb = onRouteDone;\n                onRouteDone = null;\n                arrived = true; waiting = true; waitLeft = 9999f;\n                if (cb != null) cb();\n                return;\n            }\n            NextRoam();\n        }\n\n        void NextRoam() { Go(RandomPoint()); }\n\n        void Face(Vector3 dir, float speed)\n        {\n            dir.y = 0f;\n            if (dir.sqrMagnitude < 0.001f) return;\n            transform.rotation = Quaternion.RotateTowards(transform.rotation, Quaternion.LookRotation(dir), speed * Time.deltaTime);\n        }\n\n        void Go(Vector3 p)\n        {\n            NavMeshHit hit;\n            if (NavMesh.SamplePosition(p, out hit, 1.2f, NavMesh.AllAreas)) p = hit.position;\n            agent.isStopped = false;\n            agent.SetDestination(p);\n            arrived = false;\n            waiting = false;\n            sinceGo = 0f;\n        }\n\n        void Stop()\n        {\n            if (agent.enabled) { agent.isStopped = true; agent.ResetPath(); }\n            arrived = true;\n        }\n\n        Vector3 RandomPoint()\n        {\n            for (int i = 0; i < 25; i++)\n            {\n                Vector3 p = new Vector3(Random.Range(roamRect.x, roamRect.z), transform.position.y, Random.Range(roamRect.y, roamRect.w));\n                NavMeshHit hit;\n                if (!NavMesh.SamplePosition(p, out hit, 0.6f, NavMesh.AllAreas)) continue;\n                NavMeshPath path = new NavMeshPath();\n                if (agent.CalculatePath(hit.position, path) && path.status == NavMeshPathStatus.PathComplete) return hit.position;\n            }\n            return transform.position;\n        }\n\n        void LateUpdate()\n        {\n            // keep the visible body on the real floor (the NavMesh floats a few cm above it)\n            if (visual == null) return;\n            RaycastHit hit;\n            Vector3 from = transform.position + Vector3.up * 0.8f;\n            if (Physics.Raycast(from, Vector3.down, out hit, 2f, ~(1 << gameObject.layer), QueryTriggerInteraction.Ignore))\n            {\n                // only small corrections: never climb onto a chair, bench or desk the ray happens to hit\n                float want = Mathf.Clamp(hit.point.y - transform.position.y, -0.12f, 0.17f);\n                Vector3 lp = visual.localPosition;\n                lp.y = Mathf.MoveTowards(lp.y, want, 1f * Time.deltaTime);\n                visual.localPosition = lp;\n            }\n        }\n    }\n}\n"},"PhoneController":{"path":"Assets/Game/Scripts/PhoneController.cs","role":"The inherited phone: lock codes, apps, photos, messages, contacts, tasks and danger shake.","source":"// @role The inherited phone: lock codes, apps, photos, messages, contacts, tasks and danger shake.\n// @calls UIFactory, GameInput\n// @tune bootSeconds:float:1-15:Seconds the old phone takes to start up.\n// @tune raiseSeconds:float:0.05-1:Seconds to raise the phone.\n// @tune lowerSeconds:float:0.05-1:Seconds to lower the phone.\n// @tune readCharsPerSecond:float:5-80:Message typewriter speed.\n// @tune glowIntensity:float:0-5:Screen glow light intensity in the dark.\n\nusing System.Collections.Generic;\nusing UnityEngine;\nusing UnityEngine.UI;\n\nnamespace PhoneGame\n{\n    [System.Serializable]\n    public class PhoneContact\n    {\n        public string name;\n        public string year;\n        [TextArea] public string note;\n        public PhoneContact(string n, string y, string no) { name = n; year = y; note = no; }\n    }\n\n    public class PhoneMsg\n    {\n        public string from;\n        public string text;\n        public bool mine;\n        public float shown;   // characters read so far\n    }\n\n    /// <summary>Something the level wants the player to do in Messages: reply, or forward to a contact.</summary>\n    public class PhoneTask\n    {\n        public bool forward;\n        public string header = \"Reply\";\n        public string[] options;\n        public int correct = -1;\n        public string wrongText = \"Not them. They're not part of this.\";\n        public string sendText;\n        public string toLabel;\n        /// <summary>Returns null if the choice can be sent now, or a reason it can't (\"No signal...\").</summary>\n        public System.Func<int, string> check;\n        public System.Action<int> onDone;\n        public float typeSeconds = 3f;\n    }\n\n    /// <summary>\n    /// The inherited phone (screen-space UI).\n    ///   Hold RIGHT MOUSE = phone up.  Release = put it down (hide).\n    ///   LOCK SCREEN  : 4-digit code with the number keys. Backspace deletes. (1952 - the year it all began)\n    ///   STARTING UP  : old phone, bootSeconds (5 s). Keep it up the WHOLE time - put it down and it locks again.\n    ///   HOME         : Photos, Camera, Contacts, Messages, Search. A / D choose, Left Mouse / Enter open.\n    ///                  Every app has its own code (heard somewhere in the school) and its own loading time,\n    ///                  with the same rule: put the phone down while it loads and it locks again.\n    ///   PHOTOS       : A / D browse, Q back.\n    ///   MESSAGES     : new messages are read only while you look at them. Replies / forwards: A / D choose,\n    ///                  Left Mouse select, then HOLD Left Mouse to type and send.\n    ///   CONTACTS     : A / D browse names left by everyone who had this phone before you.\n    /// </summary>\n    public class PhoneController : MonoBehaviour\n    {\n        public enum PhoneScreen { Lock, Booting, Home, AppLock, AppLoading, Photos, Messages, Contacts }\n        public const int AppPhotos = 0, AppCamera = 1, AppContacts = 2, AppMessages = 3, AppSearch = 4;\n\n        [Header(\"Codes & timing\")]\n        public string phoneCode = \"1952\";\n        public string phoneHint = \"Hint: the year it all began\";\n        [TextArea] public string lockNotification = \"1 new message\\nUnknown: congrats on the worst seat in the whole school :)\";\n        public float bootSeconds = 5f;\n        public float raiseSeconds = 0.25f;\n        public float lowerSeconds = 0.3f;\n        public string[] appNames = { \"Photos\", \"Camera\", \"Contacts\", \"Messages\", \"Search\" };\n        public string[] appCodes = { \"2100\", \"\", \"0304\", \"1240\", \"\" };\n        public string[] appHints =\n        {\n            \"Hint: lights out (24-hour clock)\",\n            \"Hint: ???\",\n            \"Hint: where you sleep (room number)\",\n            \"Hint: when we eat (24-hour clock)\",\n            \"Hint: ???\",\n        };\n        public float[] appLoadSeconds = { 7f, 5f, 5f, 5f, 5f };\n        public bool[] appUnlocked = new bool[5];\n\n        [Header(\"Phone look\")]\n        public string phoneClock = \"10:05\";\n\n        [Header(\"Messages\")]\n        public float readCharsPerSecond = 22f;\n        public List<PhoneContact> contacts = DefaultContacts();\n\n        [Header(\"Photos\")]\n        [Tooltip(\"Shows the 1979 photo (The Inspector).\")]\n        public bool showOldPhoto;\n\n        [Header(\"Screen glow (Lights Out)\")]\n        public Light glowLight;\n        public float glowIntensity = 1.6f;\n        [HideInInspector] public float glowBoost;\n\n        [Header(\"State (set by the level)\")]\n        public bool hasPhone;\n        public bool allowRaise;\n        [Tooltip(\"The level holds the phone up for you (the ending).\")]\n        public bool forceRaise;\n        [Tooltip(\"0..1 - how close the watcher is to noticing. The phone shakes and turns red.\")]\n        public float danger;\n\n        public static List<PhoneContact> DefaultContacts()\n        {\n            return new List<PhoneContact>\n            {\n                new PhoneContact(\"Seat 31 · '79\", \"1979\", \"\\\"If you are reading this, keep going.\\\"\\n(last seen: gave it back, 1980)\"),\n                new PhoneContact(\"Mom (not mine)\", \"2009\", \"Do not call. It rings in the front office.\"),\n                new PhoneContact(\"Don't Reply\", \"2016\", \"Seriously. Don't.\"),\n                new PhoneContact(\"Lent Me An Eraser\", \"2018\", \"Still owes me an eraser.\"),\n                new PhoneContact(\"Bus 14\", \"2019\", \"Left in spring. Didn't say goodbye.\"),\n                new PhoneContact(\"Triangle\", \"2021\", \"The one with the chalk triangle. One of us.\"),\n                new PhoneContact(\"Hums When Scared\", \"2021\", \"Window tables. Lunch.\"),\n                new PhoneContact(\"Never Blinks\", \"2022\", \"Room 304. Across from you.\"),\n            };\n        }\n\n        public PhoneScreen Screen { get; private set; }\n        public bool IsExposed { get { return raise > 0.001f; } }\n        public bool IsUp { get { return raise >= 0.999f; } }\n        public bool IsHeld { get { return held; } }\n        /// <summary>Unlocked and past the start-up screen.</summary>\n        public bool ScreenOn { get { return Screen != PhoneScreen.Lock && Screen != PhoneScreen.Booting; } }\n        public bool ClueFound { get; private set; }\n        public bool OldPhotoFound { get; private set; }\n        public bool FirstContactSeen { get; private set; }\n        public bool RaisedOnce { get; private set; }\n        public float BootSecondsElapsed { get { return Screen == PhoneScreen.Booting ? loadT : 0f; } }\n        public float AppLoadingElapsed { get { return Screen == PhoneScreen.AppLoading ? loadT : 0f; } }\n        public PhoneTask Task { get { return task; } }\n        public int OpenApp { get { return openApp; } }\n        public bool IsUnlocked(int app) { return app >= 0 && app < appUnlocked.Length && appUnlocked[app]; }\n        public System.Action onMessageArrived;\n\n        public int UnreadCount\n        {\n            get\n            {\n                int n = 0;\n                foreach (PhoneMsg m in msgs) if (!m.mine && m.shown < m.text.Length) n++;\n                return n;\n            }\n        }\n\n        float raise, loadT, noticeTimer, viewTimer, typeProgress;\n        bool held, typing;\n        string entry = \"\";\n        string notice = \"\";\n        int selectedApp, openApp, photoIndex, contactIndex, choice;\n        readonly List<PhoneMsg> msgs = new List<PhoneMsg>();\n        PhoneTask task;\n\n        // UI\n        RectTransform panel;\n        GameObject lockRoot, loadRoot, homeRoot, photosRoot, msgRoot, contactsRoot;\n        Text lockTitle, lockDots, loadTitle, loadPercent, homeClock, photoCaption, photoCounter, footer;\n        Text msgHeader, taskHeader, taskBody, taskHelp, contactName, contactYear, contactNote, contactCounter;\n        RectTransform loadFill, typeFill;\n        GameObject taskRoot, typeBarRoot;\n        Image[] appTiles;\n        Text[] appLabels;\n        GameObject[] photos;\n        Image[] bubbleBg;\n        Text[] bubbleFrom, bubbleText;\n        const int Bubbles = 4;\n        // new-message notification that peeks up from the bottom of the screen while the phone is down\n        RectTransform notif;\n        Text notifFrom, notifText, notifCount;\n        float notifT;\n        const float NotifHidden = -140f, NotifShown = 24f;\n        const float HiddenY = -950f, ShownY = -40f;   // low on the screen, partly \"under the desk\"\n        const float PanelScale = 1.1f;\n        Image dangerTint;\n        float flashT;\n        Text lockHint, lockNote;\n        GameObject lockNoteRoot;\n        static readonly Color Ink = new Color(0.12f, 0.12f, 0.14f);\n        static readonly Color ScreenColor = new Color(0.95f, 0.91f, 0.82f);\n\n        // Photos and their captions are defined together here (in code), so a picture and its caption\n        // can never get out of step. Index 3 (the chalk triangle) is the clue for the student in front.\n        const int cluePhoto = 3;\n        const int oldPhoto = 5;\n        static readonly string[] photoCaptions =\n        {\n            \"2009. Back row, by the window.\\nSame seat. (Nice haircut, me.)\",\n            \"2016. \\\"Keep the screen low.\\nThey watch the light.\\\"\",\n            \"2018. Proof that he sneezes like a cat.\\nDelete before he sees.\",\n            \"2021. The one in front with the triangle\\nis one of us. Tap their shoulder twice.\",\n            \"Lights out. 21:00. Exactly.\",\n            \"1979. Back row, by the window. Same seat.\\nIn pencil, under the photo: VOSS.\",\n        };\n        int PhotoCount { get { return showOldPhoto ? 6 : 5; } }\n\n        void Awake() { BuildUI(); Screen = PhoneScreen.Lock; }\n\n        // ------------------------------------------------------------------ public API for levels\n        public void Receive(string from, string text)\n        {\n            msgs.Add(new PhoneMsg { from = from, text = text, mine = false, shown = 0f });\n            if (notifFrom != null && hasPhone)\n            {\n                notifFrom.text = from.ToUpper();\n                notifText.text = text.Length > 40 ? text.Substring(0, 38) + \"...\" : text;\n                notifT = 4.5f;\n            }\n            if (onMessageArrived != null) onMessageArrived();\n        }\n\n        /// <summary>A message that is already read (history from earlier days).</summary>\n        public void AddHistory(string from, string text, bool mine)\n        {\n            msgs.Add(new PhoneMsg { from = from, text = text, mine = mine, shown = text.Length });\n        }\n\n        public void StartTask(PhoneTask t)\n        {\n            task = t;\n            choice = 0;\n            typing = false;\n            typeProgress = 0f;\n        }\n\n        public void CancelTask() { task = null; typing = false; }\n\n        /// <summary>Skip the lock screen (cutscenes): the phone is on and showing an app.</summary>\n        public void ForceOpen(int app)\n        {\n            hasPhone = true;\n            if (app >= 0 && app < appUnlocked.Length) appUnlocked[app] = true;\n            openApp = app;\n            Screen = app == AppMessages ? PhoneScreen.Messages : (app == AppContacts ? PhoneScreen.Contacts : (app == AppPhotos ? PhoneScreen.Photos : PhoneScreen.Home));\n        }\n\n        /// <summary>A strike: the phone jolts and flashes red.</summary>\n        public void Flash() { flashT = 1f; }\n\n        // ------------------------------------------------------------------ update\n        void Update()\n        {\n            held = forceRaise || (hasPhone && allowRaise && GameInput.RightHeld());\n            float speed = held ? 1f / Mathf.Max(0.01f, raiseSeconds) : 1f / Mathf.Max(0.01f, lowerSeconds);\n            raise = Mathf.MoveTowards(raise, held ? 1f : 0f, speed * Time.deltaTime);\n            if (raise > 0.5f) RaisedOnce = true;\n            float e = raise * raise * (3f - 2f * raise);\n            // danger: shake + red, stronger the closer he is to noticing\n            if (flashT > 0f) flashT -= Time.deltaTime * 1.5f;\n            float d = Mathf.Clamp01(danger);\n            Vector2 shake = Random.insideUnitCircle * (d * d * 18f + Mathf.Max(0f, flashT) * 26f);\n            panel.anchoredPosition = new Vector2(0f, Mathf.Lerp(HiddenY, ShownY, e)) + shake;\n            dangerTint.color = new Color(0.85f, 0.05f, 0.05f, Mathf.Max(d * 0.65f, Mathf.Max(0f, flashT) * 0.75f));\n\n            if (glowLight != null)\n            {\n                if (glowBoost > 0f) glowBoost = Mathf.Max(0f, glowBoost - Time.deltaTime * 3f);\n                glowLight.intensity = raise * glowIntensity * (1f + glowBoost * 3f);\n                glowLight.enabled = raise > 0.01f;\n            }\n\n            // Leaving the phone during a loading screen resets it.\n            if (!held && Screen == PhoneScreen.Booting) { Screen = PhoneScreen.Lock; entry = \"\"; Notice(\"The phone locked itself again.\"); }\n            if (!held && Screen == PhoneScreen.AppLoading) { Screen = PhoneScreen.AppLock; entry = \"\"; Notice(appNames[openApp] + \" locked again.\"); }\n\n            if (notif != null)\n            {\n                if (notifT > 0f) notifT -= Time.deltaTime;\n                int unread = UnreadCount;\n                bool show = hasPhone && raise < 0.05f && (notifT > 0f || unread > 0);\n                float target = show ? NotifShown : NotifHidden;\n                Vector2 np = notif.anchoredPosition;\n                np.y = Mathf.Lerp(np.y, target, 1f - Mathf.Exp(-Time.deltaTime * 10f));\n                notif.anchoredPosition = np;\n                notifCount.text = unread > 1 ? unread + \" new messages\" : (unread == 1 ? \"1 new message\" : \"\");\n                // a quick nudge when it arrives\n                notif.localRotation = Quaternion.Euler(0f, 0f, notifT > 4.1f ? Mathf.Sin(Time.time * 60f) * 1.5f : 0f);\n            }\n\n            if (noticeTimer > 0f) noticeTimer -= Time.deltaTime;\n            if (IsUp) Tick();\n            Refresh();\n        }\n\n        void Tick()\n        {\n            float dt = Time.deltaTime;\n            switch (Screen)\n            {\n                case PhoneScreen.Lock:\n                case PhoneScreen.AppLock:\n                    if (Screen == PhoneScreen.AppLock && GameInput.BackDown()) { Screen = PhoneScreen.Home; entry = \"\"; break; }\n                    int dg = GameInput.DigitDown();\n                    if (dg >= 0 && entry.Length < 4) entry += dg.ToString();\n                    if (GameInput.BackspaceDown() && entry.Length > 0) entry = entry.Substring(0, entry.Length - 1);\n                    if (entry.Length == 4) CheckCode();\n                    break;\n\n                case PhoneScreen.Booting:\n                    loadT += dt;\n                    if (loadT >= bootSeconds) { Screen = PhoneScreen.Home; selectedApp = 0; }\n                    break;\n\n                case PhoneScreen.Home:\n                    if (GameInput.LeftKeyDown()) selectedApp = (selectedApp + appNames.Length - 1) % appNames.Length;\n                    if (GameInput.RightKeyDown()) selectedApp = (selectedApp + 1) % appNames.Length;\n                    if (GameInput.LeftDown() || GameInput.EnterDown())\n                    {\n                        openApp = selectedApp;\n                        entry = \"\";\n                        if (IsUnlocked(openApp)) OpenUnlockedApp();\n                        else Screen = PhoneScreen.AppLock;\n                    }\n                    break;\n\n                case PhoneScreen.AppLoading:\n                    loadT += dt;\n                    if (loadT >= appLoadSeconds[openApp])\n                    {\n                        appUnlocked[openApp] = true;\n                        OpenUnlockedApp();\n                    }\n                    break;\n\n                case PhoneScreen.Photos:\n                    if (GameInput.LeftKeyDown()) { photoIndex = (photoIndex + PhotoCount - 1) % PhotoCount; viewTimer = 0f; }\n                    if (GameInput.RightKeyDown()) { photoIndex = (photoIndex + 1) % PhotoCount; viewTimer = 0f; }\n                    if (GameInput.BackDown()) Screen = PhoneScreen.Home;\n                    viewTimer += dt;\n                    if (viewTimer > 1.5f)\n                    {\n                        if (photoIndex == cluePhoto) ClueFound = true;\n                        if (photoIndex == oldPhoto) OldPhotoFound = true;\n                    }\n                    break;\n\n                case PhoneScreen.Contacts:\n                    if (contacts.Count > 0)\n                    {\n                        if (GameInput.LeftKeyDown()) { contactIndex = (contactIndex + contacts.Count - 1) % contacts.Count; viewTimer = 0f; }\n                        if (GameInput.RightKeyDown()) { contactIndex = (contactIndex + 1) % contacts.Count; viewTimer = 0f; }\n                    }\n                    if (GameInput.BackDown()) Screen = PhoneScreen.Home;\n                    viewTimer += dt;\n                    if (contactIndex == 0 && viewTimer > 1.5f) FirstContactSeen = true;\n                    break;\n\n                case PhoneScreen.Messages:\n                    TickMessages(dt);\n                    break;\n            }\n        }\n\n        void OpenUnlockedApp()\n        {\n            viewTimer = 0f;\n            if (openApp == AppPhotos) { Screen = PhoneScreen.Photos; photoIndex = 0; }\n            else if (openApp == AppContacts) { Screen = PhoneScreen.Contacts; contactIndex = 0; }\n            else if (openApp == AppMessages) Screen = PhoneScreen.Messages;\n            else { Screen = PhoneScreen.Home; Notice(\"This app doesn't open. Yet.\"); }\n        }\n\n        void TickMessages(float dt)\n        {\n            if (GameInput.BackDown() && !forceRaise) { Screen = PhoneScreen.Home; return; }\n            // read the first unread message\n            foreach (PhoneMsg m in msgs)\n            {\n                if (m.mine || m.shown >= m.text.Length) continue;\n                m.shown = Mathf.Min(m.text.Length, m.shown + readCharsPerSecond * dt);\n                return;\n            }\n            if (task == null) return;\n            if (!typing)\n            {\n                int n = task.options != null ? task.options.Length : 0;\n                if (n > 0)\n                {\n                    if (GameInput.LeftKeyDown()) choice = (choice + n - 1) % n;\n                    if (GameInput.RightKeyDown()) choice = (choice + 1) % n;\n                }\n                if (GameInput.LeftDown() && n > 0)\n                {\n                    if (task.correct >= 0 && choice != task.correct) { Notice(task.wrongText); return; }\n                    if (task.check != null)\n                    {\n                        string err = task.check(choice);\n                        if (!string.IsNullOrEmpty(err)) { Notice(err); return; }\n                    }\n                    typing = true;\n                    typeProgress = 0f;\n                }\n                return;\n            }\n            if (GameInput.LeftHeld()) typeProgress = Mathf.Min(1f, typeProgress + dt / Mathf.Max(0.1f, task.typeSeconds));\n            if (typeProgress >= 1f)\n            {\n                PhoneTask done = task;\n                int c = choice;\n                string sent = done.forward ? done.sendText : done.options[c];\n                msgs.Add(new PhoneMsg { from = \"me\", text = sent, mine = true, shown = sent.Length });\n                task = null;\n                typing = false;\n                Notice(\"Delivered.\");\n                if (done.onDone != null) done.onDone(c);\n            }\n        }\n\n        void CheckCode()\n        {\n            if (Screen == PhoneScreen.Lock)\n            {\n                if (entry == phoneCode) { Screen = PhoneScreen.Booting; loadT = 0f; Notice(\"Don't put it down.\"); }\n                else Notice(\"Wrong passcode.\");\n            }\n            else\n            {\n                string code = (openApp >= 0 && openApp < appCodes.Length) ? appCodes[openApp] : \"\";\n                if (!string.IsNullOrEmpty(code) && entry == code) { Screen = PhoneScreen.AppLoading; loadT = 0f; Notice(\"Don't put it down.\"); }\n                else Notice(\"Wrong passcode.\");\n            }\n            entry = \"\";\n        }\n\n        void Notice(string s) { notice = s; noticeTimer = 2.5f; }\n\n        // ------------------------------------------------------------------ drawing\n        void Refresh()\n        {\n            bool isLock = Screen == PhoneScreen.Lock || Screen == PhoneScreen.AppLock;\n            bool isLoad = Screen == PhoneScreen.Booting || Screen == PhoneScreen.AppLoading;\n            lockRoot.SetActive(isLock);\n            loadRoot.SetActive(isLoad);\n            homeRoot.SetActive(Screen == PhoneScreen.Home);\n            photosRoot.SetActive(Screen == PhoneScreen.Photos);\n            msgRoot.SetActive(Screen == PhoneScreen.Messages);\n            contactsRoot.SetActive(Screen == PhoneScreen.Contacts);\n\n            string hint = \"\";\n            if (isLock)\n            {\n                lockTitle.text = Screen == PhoneScreen.Lock ? \"Enter passcode\" : appNames[openApp] + \" is locked\\nEnter passcode\";\n                string dots = \"\";\n                for (int i = 0; i < 4; i++) dots += (i < entry.Length ? \"*\" : \"_\") + (i < 3 ? \"  \" : \"\");\n                lockDots.text = dots;\n                lockHint.text = Screen == PhoneScreen.Lock ? phoneHint : (openApp < appHints.Length ? appHints[openApp] : \"Hint: ???\");\n                lockNoteRoot.SetActive(Screen == PhoneScreen.Lock);\n                lockNote.text = LockNotificationText();\n                hint = Screen == PhoneScreen.Lock ? \"Number keys: type    Backspace: delete\" : \"Number keys: type    Q: back\";\n            }\n            else if (isLoad)\n            {\n                float total = Screen == PhoneScreen.Booting ? bootSeconds : appLoadSeconds[openApp];\n                float p = Mathf.Clamp01(loadT / Mathf.Max(0.1f, total));\n                loadTitle.text = Screen == PhoneScreen.Booting ? \"STARTING UP\" : \"OPENING \" + appNames[openApp].ToUpper();\n                loadPercent.text = Mathf.FloorToInt(p * 100f) + \"%\";\n                loadFill.anchorMax = new Vector2(p, 1f);\n                hint = \"Keep holding Right Mouse.\";\n            }\n            else if (Screen == PhoneScreen.Home)\n            {\n                homeClock.text = phoneClock;\n                int unread = UnreadCount;\n                for (int i = 0; i < appTiles.Length; i++)\n                {\n                    bool on = i == selectedApp;\n                    appTiles[i].color = on ? new Color(0.20f, 0.20f, 0.22f) : new Color(0f, 0f, 0f, 0.12f);\n                    appLabels[i].color = on ? new Color(0.98f, 0.9f, 0.7f) : Ink;\n                    string extra = !IsUnlocked(i) ? \"\\n(locked)\" : (i == AppMessages && unread > 0 ? \"\\n(\" + unread + \" new)\" : \"\");\n                    appLabels[i].text = appNames[i] + extra;\n                }\n                hint = \"A / D: choose app    Left Mouse: open\";\n            }\n            else if (Screen == PhoneScreen.Photos)\n            {\n                for (int i = 0; i < photos.Length; i++) photos[i].SetActive(i == photoIndex);\n                photoCaption.text = photoIndex < photoCaptions.Length ? photoCaptions[photoIndex] : \"\";\n                photoCounter.text = (photoIndex + 1) + \" / \" + PhotoCount;\n                hint = \"A / D: browse    Q: back\";\n            }\n            else if (Screen == PhoneScreen.Contacts)\n            {\n                if (contacts.Count > 0)\n                {\n                    PhoneContact c = contacts[Mathf.Clamp(contactIndex, 0, contacts.Count - 1)];\n                    contactName.text = c.name;\n                    contactYear.text = \"saved in \" + c.year;\n                    contactNote.text = c.note;\n                    contactCounter.text = (contactIndex + 1) + \" / \" + contacts.Count;\n                }\n                hint = \"A / D: browse    Q: back\";\n            }\n            else if (Screen == PhoneScreen.Messages)\n            {\n                hint = RefreshMessages();\n            }\n            footer.text = noticeTimer > 0f ? notice : hint;\n            footer.color = noticeTimer > 0f ? new Color(0.75f, 0.2f, 0.15f) : new Color(0.35f, 0.35f, 0.37f);\n        }\n\n        string LockNotificationText()\n        {\n            foreach (PhoneMsg m in msgs)\n            {\n                if (m.mine || m.shown >= m.text.Length) continue;\n                int n = UnreadCount;\n                string preview = m.text.Length > 46 ? m.text.Substring(0, 46) + \"...\" : m.text;\n                return n + (n == 1 ? \" new message\\n\" : \" new messages\\n\") + m.from + \": \" + preview;\n            }\n            return lockNotification;\n        }\n\n        string RefreshMessages()\n        {\n            int unread = UnreadCount;\n            msgHeader.text = \"Messages\" + (unread > 0 ? \"   (\" + unread + \" new)\" : \"\");\n\n            // show messages up to the one being read\n            int last = msgs.Count - 1;\n            for (int i = 0; i < msgs.Count; i++)\n            {\n                if (!msgs[i].mine && msgs[i].shown < msgs[i].text.Length) { last = i; break; }\n            }\n            int first = Mathf.Max(0, last - Bubbles + 1);\n            for (int s = 0; s < Bubbles; s++)\n            {\n                int i = first + s;\n                bool on = i <= last && i < msgs.Count;\n                bubbleBg[s].gameObject.SetActive(on);\n                if (!on) continue;\n                PhoneMsg m = msgs[i];\n                int shown = Mathf.FloorToInt(m.shown);\n                bool reading = !m.mine && shown < m.text.Length;\n                bubbleFrom[s].text = m.mine ? \"me\" : m.from;\n                bubbleText[s].text = (reading ? m.text.Substring(0, shown) + \"_\" : m.text);\n                bubbleBg[s].color = m.mine ? new Color(0.22f, 0.24f, 0.26f, 0.95f) : new Color(0f, 0f, 0f, 0.09f);\n                bubbleText[s].color = m.mine ? new Color(0.95f, 0.92f, 0.82f) : Ink;\n                bubbleFrom[s].color = m.mine ? new Color(0.9f, 0.75f, 0.5f) : new Color(0.45f, 0.3f, 0.2f);\n                bubbleFrom[s].alignment = m.mine ? TextAnchor.UpperRight : TextAnchor.UpperLeft;\n                bubbleText[s].alignment = m.mine ? TextAnchor.UpperRight : TextAnchor.UpperLeft;\n            }\n\n            bool showTask = task != null && unread == 0;\n            taskRoot.SetActive(showTask);\n            if (unread > 0) return \"reading...  (keep the phone up)\";\n            if (!showTask) return \"Q: back\";\n            typeBarRoot.SetActive(typing);\n            if (!typing)\n            {\n                taskHeader.text = task.header;\n                string opt = task.options != null && task.options.Length > 0 ? task.options[Mathf.Clamp(choice, 0, task.options.Length - 1)] : \"\";\n                taskBody.text = \"<  \" + opt + \"  >\";\n                taskHelp.text = \"A / D: choose    Left Mouse: select\";\n                return \"\";\n            }\n            string text = task.forward ? task.sendText : task.options[choice];\n            taskHeader.text = task.forward ? \"To: \" + task.options[choice] : (string.IsNullOrEmpty(task.toLabel) ? \"Reply\" : task.toLabel);\n            int n = Mathf.FloorToInt(typeProgress * text.Length);\n            taskBody.text = text.Substring(0, Mathf.Clamp(n, 0, text.Length)) + \"_\";\n            typeFill.anchorMax = new Vector2(typeProgress, 1f);\n            taskHelp.text = \"HOLD Left Mouse: type & send\";\n            return \"\";\n        }\n\n        // ------------------------------------------------------------------ UI\n        /// <summary>The phone's own notification: a dark banner with the sender and the first words, plus \"hold right mouse\".</summary>\n        void BuildNotification(Transform canvasRoot)\n        {\n            notif = UIFactory.Rect(\"Notification\", canvasRoot, new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0f, NotifHidden), new Vector2(520f, 104f));\n            UIFactory.AddImage(notif, new Color(0.06f, 0.06f, 0.07f, 0.96f));\n            UIFactory.AddImage(UIFactory.Rect(\"Edge\", notif, new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0.5f, 1f), Vector2.zero, new Vector2(0f, 3f)), new Color(0.95f, 0.86f, 0.62f));\n            RectTransform icon = UIFactory.TopLeft(\"Icon\", notif, 16f, 18f, 46f, 46f);\n            UIFactory.AddImage(icon, new Color(0.95f, 0.86f, 0.62f));\n            UIFactory.AddText(UIFactory.Stretch(\"Glyph\", icon), \"...\", 26, new Color(0.1f, 0.1f, 0.12f), TextAnchor.MiddleCenter).fontStyle = FontStyle.Bold;\n            Text app = UIFactory.AddText(UIFactory.TopLeft(\"App\", notif, 76f, 10f, 300f, 22f), \"MESSAGES  -  now\", 15, new Color(0.65f, 0.65f, 0.68f), TextAnchor.UpperLeft);\n            app.fontStyle = FontStyle.Bold;\n            notifCount = UIFactory.AddText(UIFactory.TopLeft(\"Count\", notif, 260f, 10f, 244f, 22f), \"\", 15, new Color(0.95f, 0.86f, 0.62f), TextAnchor.UpperRight);\n            notifFrom = UIFactory.AddText(UIFactory.TopLeft(\"From\", notif, 76f, 32f, 430f, 24f), \"\", 18, Color.white, TextAnchor.UpperLeft);\n            notifFrom.fontStyle = FontStyle.Bold;\n            notifText = UIFactory.AddText(UIFactory.TopLeft(\"Text\", notif, 76f, 56f, 430f, 24f), \"\", 17, new Color(0.85f, 0.85f, 0.85f), TextAnchor.UpperLeft);\n            notifText.horizontalOverflow = HorizontalWrapMode.Overflow;\n            UIFactory.AddText(UIFactory.TopLeft(\"Hint\", notif, 76f, 80f, 430f, 20f), \"HOLD RIGHT MOUSE to read\", 14, new Color(0.95f, 0.86f, 0.62f, 0.8f), TextAnchor.UpperLeft);\n        }\n\n        void BuildUI()\n        {\n            Canvas canvas = UIFactory.MakeCanvas(\"PhoneCanvas\", 30);\n            canvas.transform.SetParent(transform, false);\n\n            panel = UIFactory.Rect(\"Phone\", canvas.transform, new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0.5f, 0f),\n                                   new Vector2(0f, HiddenY), new Vector2(440f, 780f));\n            panel.localScale = Vector3.one * PanelScale;\n            BuildNotification(canvas.transform);\n            UIFactory.AddImage(panel, new Color(0.05f, 0.05f, 0.06f));\n            RectTransform screen = UIFactory.Rect(\"Screen\", panel, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(-36f, -36f));\n            UIFactory.AddImage(screen, ScreenColor);\n\n            // a crack across the screen protector - someone else's damage\n            RectTransform crack = UIFactory.Centered(\"Crack\", screen, 60f, 150f, 520f, 2f);\n            crack.localRotation = Quaternion.Euler(0f, 0f, 38f);\n            UIFactory.AddImage(crack, new Color(0f, 0f, 0f, 0.18f));\n\n            // --- passcode (phone lock + app lock)\n            lockRoot = UIFactory.Stretch(\"Passcode\", screen).gameObject;\n            RectTransform note = UIFactory.TopLeft(\"Notification\", lockRoot.transform, 14f, 14f, 376f, 78f);\n            UIFactory.AddImage(note, new Color(0f, 0f, 0f, 0.12f));\n            lockNote = UIFactory.AddText(UIFactory.Rect(\"T\", note, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(-20f, -10f)), \"\", 17, Ink, TextAnchor.MiddleLeft);\n            lockNoteRoot = note.gameObject;\n            lockTitle = UIFactory.AddText(UIFactory.TopLeft(\"Title\", lockRoot.transform, 18f, 100f, 368f, 70f), \"\", 26, Ink, TextAnchor.MiddleCenter);\n            lockDots = UIFactory.AddText(UIFactory.TopLeft(\"Dots\", lockRoot.transform, 18f, 168f, 368f, 50f), \"\", 44, Ink, TextAnchor.MiddleCenter);\n            lockHint = UIFactory.AddText(UIFactory.TopLeft(\"Hint\", lockRoot.transform, 18f, 222f, 368f, 34f), \"\", 18, new Color(0.55f, 0.3f, 0.15f), TextAnchor.MiddleCenter);\n            string[] keys = { \"1\", \"2\", \"3\", \"4\", \"5\", \"6\", \"7\", \"8\", \"9\", \"\", \"0\", \"\" };\n            for (int i = 0; i < keys.Length; i++)\n            {\n                if (keys[i] == \"\") continue;\n                int col = i % 3, row = i / 3;\n                RectTransform k = UIFactory.TopLeft(\"Key\" + keys[i], lockRoot.transform, 52f + col * 104f, 272f + row * 84f, 88f, 70f);\n                UIFactory.AddImage(k, new Color(0f, 0f, 0f, 0.08f));\n                UIFactory.AddText(UIFactory.Stretch(\"T\", k), keys[i], 32, Ink, TextAnchor.MiddleCenter);\n            }\n\n            // --- loading (boot + app)\n            loadRoot = UIFactory.Stretch(\"Loading\", screen).gameObject;\n            UIFactory.AddImage((RectTransform)loadRoot.transform, new Color(0.04f, 0.04f, 0.05f));\n            Color dim = new Color(0.8f, 0.78f, 0.72f);\n            loadTitle = UIFactory.AddText(UIFactory.TopLeft(\"Title\", loadRoot.transform, 18f, 260f, 368f, 50f), \"\", 26, dim, TextAnchor.MiddleCenter);\n            RectTransform bar = UIFactory.TopLeft(\"Bar\", loadRoot.transform, 60f, 330f, 284f, 10f);\n            UIFactory.AddImage(bar, new Color(1f, 1f, 1f, 0.15f));\n            loadFill = UIFactory.Rect(\"Fill\", bar, Vector2.zero, new Vector2(0f, 1f), new Vector2(0f, 0.5f), Vector2.zero, Vector2.zero);\n            UIFactory.AddImage(loadFill, new Color(0.95f, 0.75f, 0.45f));\n            loadPercent = UIFactory.AddText(UIFactory.TopLeft(\"Percent\", loadRoot.transform, 18f, 350f, 368f, 40f), \"\", 22, dim, TextAnchor.MiddleCenter);\n\n            // --- home\n            homeRoot = UIFactory.Stretch(\"Home\", screen).gameObject;\n            homeClock = UIFactory.AddText(UIFactory.TopLeft(\"Clock\", homeRoot.transform, 18f, 40f, 368f, 100f), \"\", 72, Ink, TextAnchor.MiddleCenter);\n            appTiles = new Image[appNames.Length];\n            appLabels = new Text[appNames.Length];\n            for (int i = 0; i < appNames.Length; i++)\n            {\n                int col = i % 3, row = i / 3;\n                RectTransform t = UIFactory.TopLeft(\"App_\" + appNames[i], homeRoot.transform, 22f + col * 122f, 200f + row * 150f, 110f, 130f);\n                appTiles[i] = UIFactory.AddImage(t, Color.clear);\n                RectTransform icon = UIFactory.TopLeft(\"Icon\", t, 25f, 12f, 60f, 60f);\n                UIFactory.AddImage(icon, Color.HSVToRGB(i * 0.17f, 0.35f, 0.65f));\n                appLabels[i] = UIFactory.AddText(UIFactory.TopLeft(\"Label\", t, 0f, 76f, 110f, 54f), appNames[i], 16, Ink, TextAnchor.UpperCenter);\n            }\n\n            // --- photos\n            photosRoot = UIFactory.Stretch(\"Photos\", screen).gameObject;\n            RectTransform frame = UIFactory.TopLeft(\"Frame\", photosRoot.transform, 18f, 40f, 368f, 320f);\n            UIFactory.AddImage(frame, new Color(0.1f, 0.1f, 0.1f));\n            photos = new GameObject[6];\n            photos[0] = PhotoClass(frame, \"Photo_Class2009\", new Color(0.55f, 0.58f, 0.6f), new Color(0.18f, 0.18f, 0.2f), new Color(0.25f, 0.27f, 0.32f), null);\n            photos[1] = PhotoHand(frame);\n            photos[2] = PhotoSneeze(frame);\n            photos[3] = PhotoTriangle(frame);\n            photos[4] = PhotoNight(frame);\n            photos[5] = PhotoClass(frame, \"Photo_Class1979\", new Color(0.62f, 0.52f, 0.38f), new Color(0.3f, 0.22f, 0.15f), new Color(0.4f, 0.31f, 0.21f), \"VOSS\");\n            photoCaption = UIFactory.AddText(UIFactory.TopLeft(\"Caption\", photosRoot.transform, 18f, 375f, 368f, 140f), \"\", 18, Ink, TextAnchor.UpperLeft);\n            photoCounter = UIFactory.AddText(UIFactory.TopLeft(\"Counter\", photosRoot.transform, 18f, 8f, 368f, 30f), \"\", 16, Ink, TextAnchor.MiddleRight);\n\n            // --- messages\n            msgRoot = UIFactory.Stretch(\"Messages\", screen).gameObject;\n            msgHeader = UIFactory.AddText(UIFactory.TopLeft(\"Header\", msgRoot.transform, 18f, 10f, 368f, 34f), \"Messages\", 22, Ink, TextAnchor.MiddleLeft);\n            msgHeader.fontStyle = FontStyle.Bold;\n            UIFactory.AddImage(UIFactory.TopLeft(\"Divider\", msgRoot.transform, 18f, 46f, 368f, 2f), new Color(0f, 0f, 0f, 0.25f));\n            bubbleBg = new Image[Bubbles];\n            bubbleFrom = new Text[Bubbles];\n            bubbleText = new Text[Bubbles];\n            for (int i = 0; i < Bubbles; i++)\n            {\n                RectTransform b = UIFactory.TopLeft(\"Bubble\" + i, msgRoot.transform, 14f, 56f + i * 112f, 376f, 106f);\n                bubbleBg[i] = UIFactory.AddImage(b, new Color(0f, 0f, 0f, 0.09f));\n                bubbleFrom[i] = UIFactory.AddText(UIFactory.TopLeft(\"From\", b, 10f, 4f, 356f, 22f), \"\", 15, Ink, TextAnchor.UpperLeft);\n                bubbleFrom[i].fontStyle = FontStyle.Bold;\n                bubbleText[i] = UIFactory.AddText(UIFactory.TopLeft(\"Text\", b, 10f, 26f, 356f, 78f), \"\", 17, Ink, TextAnchor.UpperLeft);\n            }\n            taskRoot = UIFactory.TopLeft(\"Task\", msgRoot.transform, 14f, 504f, 376f, 160f).gameObject;\n            UIFactory.AddImage((RectTransform)taskRoot.transform, new Color(0.2f, 0.12f, 0.08f, 0.12f));\n            taskHeader = UIFactory.AddText(UIFactory.TopLeft(\"Header\", taskRoot.transform, 10f, 6f, 356f, 26f), \"\", 17, new Color(0.45f, 0.25f, 0.12f), TextAnchor.UpperLeft);\n            taskHeader.fontStyle = FontStyle.Bold;\n            taskBody = UIFactory.AddText(UIFactory.TopLeft(\"Body\", taskRoot.transform, 10f, 34f, 356f, 80f), \"\", 19, Ink, TextAnchor.UpperCenter);\n            typeBarRoot = UIFactory.TopLeft(\"TypeBar\", taskRoot.transform, 10f, 118f, 356f, 8f).gameObject;\n            UIFactory.AddImage((RectTransform)typeBarRoot.transform, new Color(0f, 0f, 0f, 0.15f));\n            typeFill = UIFactory.Rect(\"Fill\", typeBarRoot.transform, Vector2.zero, new Vector2(0f, 1f), new Vector2(0f, 0.5f), Vector2.zero, Vector2.zero);\n            UIFactory.AddImage(typeFill, new Color(0.85f, 0.45f, 0.15f));\n            taskHelp = UIFactory.AddText(UIFactory.TopLeft(\"Help\", taskRoot.transform, 10f, 132f, 356f, 24f), \"\", 14, new Color(0.35f, 0.35f, 0.37f), TextAnchor.UpperCenter);\n            taskRoot.SetActive(false);\n\n            // --- contacts\n            contactsRoot = UIFactory.Stretch(\"Contacts\", screen).gameObject;\n            UIFactory.AddText(UIFactory.TopLeft(\"Header\", contactsRoot.transform, 18f, 10f, 368f, 34f), \"Contacts\", 22, Ink, TextAnchor.MiddleLeft).fontStyle = FontStyle.Bold;\n            contactCounter = UIFactory.AddText(UIFactory.TopLeft(\"Counter\", contactsRoot.transform, 18f, 10f, 368f, 34f), \"\", 16, Ink, TextAnchor.MiddleRight);\n            RectTransform card = UIFactory.TopLeft(\"Card\", contactsRoot.transform, 18f, 70f, 368f, 420f);\n            UIFactory.AddImage(card, new Color(0f, 0f, 0f, 0.08f));\n            RectTransform avatar = UIFactory.TopLeft(\"Avatar\", card, 134f, 24f, 100f, 100f);\n            UIFactory.AddImage(avatar, new Color(0.6f, 0.58f, 0.52f));\n            UIFactory.AddText(UIFactory.Stretch(\"Q\", avatar), \"?\", 54, new Color(0.95f, 0.92f, 0.85f), TextAnchor.MiddleCenter);\n            contactName = UIFactory.AddText(UIFactory.TopLeft(\"Name\", card, 10f, 140f, 348f, 44f), \"\", 25, Ink, TextAnchor.MiddleCenter);\n            contactName.fontStyle = FontStyle.Bold;\n            contactYear = UIFactory.AddText(UIFactory.TopLeft(\"Year\", card, 10f, 186f, 348f, 28f), \"\", 16, new Color(0.45f, 0.3f, 0.2f), TextAnchor.MiddleCenter);\n            contactNote = UIFactory.AddText(UIFactory.TopLeft(\"Note\", card, 20f, 236f, 328f, 160f), \"\", 19, Ink, TextAnchor.UpperCenter);\n\n            footer = UIFactory.AddText(UIFactory.TopLeft(\"Footer\", screen, 18f, 680f, 368f, 50f), \"\", 16, Ink, TextAnchor.UpperCenter);\n\n            dangerTint = UIFactory.AddImage(UIFactory.Stretch(\"DangerRed\", screen), new Color(0.85f, 0.05f, 0.05f, 0f));\n        }\n\n        // Photos are drawn with simple shapes - replace with real images later.\n        static RectTransform Box(Transform parent, float x, float y, float w, float h, Color c)\n        {\n            RectTransform r = UIFactory.TopLeft(\"Shape\", parent, x, y, w, h);\n            UIFactory.AddImage(r, c);\n            return r;\n        }\n\n        GameObject PhotoClass(RectTransform frame, string name, Color wall, Color head, Color body, string pencil)\n        {\n            GameObject p = UIFactory.Stretch(name, frame).gameObject;\n            Box(p.transform, 0f, 0f, 368f, 320f, wall);\n            Box(p.transform, 0f, 250f, 368f, 70f, new Color(wall.r * 0.6f, wall.g * 0.6f, wall.b * 0.6f));\n            for (int row = 0; row < 3; row++)\n                for (int i = 0; i < 5; i++)\n                {\n                    float x = 40f + i * 62f + row * 6f, y = 60f + row * 62f;\n                    Box(p.transform, x, y, 22f, 22f, head);\n                    Box(p.transform, x - 6f, y + 24f, 34f, 30f, body);\n                }\n            // circled: back row, window side\n            float cx = 34f, cy = 54f;\n            Color y1 = pencil == null ? new Color(1f, 0.8f, 0.2f) : new Color(0.15f, 0.12f, 0.1f);\n            Box(p.transform, cx, cy, 34f, 3f, y1); Box(p.transform, cx, cy + 62f, 34f, 3f, y1);\n            Box(p.transform, cx, cy, 3f, 64f, y1); Box(p.transform, cx + 32f, cy, 3f, 64f, y1);\n            if (pencil != null)\n            {\n                Text t = UIFactory.AddText(UIFactory.TopLeft(\"Pencil\", p.transform, 14f, 268f, 200f, 40f), pencil, 26, new Color(0.18f, 0.14f, 0.1f), TextAnchor.MiddleLeft);\n                t.fontStyle = FontStyle.Italic;\n                Box(p.transform, 0f, 0f, 368f, 320f, new Color(0.4f, 0.3f, 0.1f, 0.12f));   // age\n            }\n            return p;\n        }\n\n        GameObject PhotoHand(RectTransform frame)\n        {\n            GameObject p = UIFactory.Stretch(\"Photo_Hand2016\", frame).gameObject;\n            Box(p.transform, 0f, 0f, 368f, 320f, new Color(0.22f, 0.16f, 0.11f));\n            Box(p.transform, 0f, 40f, 368f, 18f, new Color(0.4f, 0.3f, 0.2f));\n            Box(p.transform, 130f, 150f, 120f, 70f, new Color(0.75f, 0.6f, 0.48f));\n            Box(p.transform, 160f, 110f, 46f, 84f, new Color(0.05f, 0.05f, 0.06f));\n            Box(p.transform, 164f, 114f, 38f, 70f, new Color(0.95f, 0.85f, 0.6f));\n            return p;\n        }\n\n        GameObject PhotoSneeze(RectTransform frame)\n        {\n            GameObject p = UIFactory.Stretch(\"Photo_Sneeze2018\", frame).gameObject;\n            Box(p.transform, 0f, 0f, 368f, 320f, new Color(0.3f, 0.36f, 0.32f));        // blackboard\n            Box(p.transform, 140f, 90f, 90f, 230f, new Color(0.55f, 0.18f, 0.16f));     // teacher, blurred mid-sneeze\n            Box(p.transform, 158f, 40f, 54f, 54f, new Color(0.8f, 0.65f, 0.55f));\n            Box(p.transform, 150f, 30f, 70f, 10f, new Color(1f, 1f, 1f, 0.35f));       // motion blur\n            Box(p.transform, 230f, 50f, 40f, 4f, new Color(1f, 1f, 1f, 0.6f));\n            Box(p.transform, 236f, 62f, 30f, 4f, new Color(1f, 1f, 1f, 0.5f));\n            return p;\n        }\n\n        GameObject PhotoTriangle(RectTransform frame)\n        {\n            GameObject p = UIFactory.Stretch(\"Photo_Triangle2021\", frame).gameObject;\n            Box(p.transform, 0f, 0f, 368f, 320f, new Color(0.5f, 0.5f, 0.5f));\n            Box(p.transform, 74f, 40f, 220f, 200f, new Color(0.45f, 0.33f, 0.22f));   // chair back\n            Box(p.transform, 90f, 240f, 20f, 80f, new Color(0.35f, 0.25f, 0.17f));\n            Box(p.transform, 258f, 240f, 20f, 80f, new Color(0.35f, 0.25f, 0.17f));\n            // chalk triangle: three bars around the centre of the chair back\n            Triangle(p.transform, new Vector2(184f, -140f), 110f, 6f, new Color(0.95f, 0.95f, 0.9f));\n            return p;\n        }\n\n        GameObject PhotoNight(RectTransform frame)\n        {\n            GameObject p = UIFactory.Stretch(\"Photo_Night\", frame).gameObject;\n            Box(p.transform, 0f, 0f, 368f, 320f, new Color(0.03f, 0.03f, 0.05f));\n            Box(p.transform, 250f, 60f, 60f, 80f, new Color(0.95f, 0.8f, 0.45f));\n            return p;\n        }\n\n        /// <summary>Outline triangle centred at 'center' (top-left space: x right, y negative down).</summary>\n        public static void Triangle(Transform parent, Vector2 center, float side, float thick, Color c)\n        {\n            float h = side * 0.866f;\n            Vector2 a = center + new Vector2(-side * 0.5f, -h / 3f);\n            Vector2 b = center + new Vector2(side * 0.5f, -h / 3f);\n            Vector2 top = center + new Vector2(0f, h * 2f / 3f);\n            Bar(parent, a, b, thick, c);\n            Bar(parent, b, top, thick, c);\n            Bar(parent, top, a, thick, c);\n        }\n\n        static void Bar(Transform parent, Vector2 from, Vector2 to, float thick, Color c)\n        {\n            Vector2 mid = (from + to) * 0.5f;\n            Vector2 d = to - from;\n            RectTransform r = UIFactory.Rect(\"Bar\", parent, new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(0.5f, 0.5f), mid, new Vector2(d.magnitude, thick));\n            r.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(d.y, d.x) * Mathf.Rad2Deg);\n            UIFactory.AddImage(r, c);\n        }\n    }\n}\n"},"PixelSprites":{"path":"Assets/Game/Scripts/PixelSprites.cs","role":"Pixel-art heart, broken heart and eye sprites generated in code.","source":"// @role Pixel-art heart, broken heart and eye sprites generated in code.\n\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>Tiny pixel-art sprites made in code (no image files needed): heart, broken heart, eye.</summary>\n    public static class PixelSprites\n    {\n        static readonly string[] HeartRows =\n        {\n            \" XX   XX \",\n            \"XXXX XXXX\",\n            \"XXXXXXXXX\",\n            \"XXXXXXXXX\",\n            \" XXXXXXX \",\n            \"  XXXXX  \",\n            \"   XXX   \",\n            \"    X    \",\n        };\n\n        // Column of the crack in each row (top to bottom) - a zig-zag down the middle.\n        static readonly int[] Crack = { 4, 5, 4, 3, 4, 5, 4, 4 };\n\n        static readonly string[] EyeRows =\n        {\n            \"     XXXXX     \",\n            \"   XX     XX   \",\n            \" XX   XXX   XX \",\n            \"X    XXXXX    X\",\n            \" XX   XXX   XX \",\n            \"   XX     XX   \",\n            \"     XXXXX     \",\n        };\n\n        static Sprite heart, broken, eye;\n\n        public static Sprite Heart { get { if (heart == null) heart = FromRows(HeartRows, false); return heart; } }\n        public static Sprite BrokenHeart { get { if (broken == null) broken = FromRows(HeartRows, true); return broken; } }\n        public static Sprite Eye { get { if (eye == null) eye = FromRows(EyeRows, false); return eye; } }\n\n        static Sprite FromRows(string[] rows, bool cracked)\n        {\n            int h = rows.Length;\n            int w = rows[0].Length + (cracked ? 2 : 0);\n            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);\n            tex.filterMode = FilterMode.Point;\n            tex.wrapMode = TextureWrapMode.Clamp;\n            Color32 clear = new Color32(0, 0, 0, 0), white = new Color32(255, 255, 255, 255);\n            for (int y = 0; y < h; y++) for (int x = 0; x < w; x++) tex.SetPixel(x, y, clear);\n\n            for (int r = 0; r < h; r++)\n            {\n                string row = rows[r];\n                int py = h - 1 - r;   // texture rows go bottom-up\n                for (int c = 0; c < row.Length; c++)\n                {\n                    if (row[c] != 'X') continue;\n                    if (!cracked) { tex.SetPixel(c, py, white); continue; }\n                    int crack = Crack[Mathf.Min(r, Crack.Length - 1)];\n                    if (c == crack) continue;                 // the crack itself\n                    int px = c < crack ? c : c + 2;           // halves pushed apart\n                    tex.SetPixel(px, py, white);\n                }\n            }\n            tex.Apply();\n            return Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f), 10f);\n        }\n    }\n}\n"},"PlayerRig":{"path":"Assets/Game/Scripts/PlayerRig.cs","role":"First-person body with walk, pulled, seated, inspect, placing, lying and locked modes.","source":"// @role First-person body with walk, pulled, seated, inspect, placing, lying and locked modes.\n// @calls GameInput\n// @tune walkSpeed:float:1-5:Walking speed.\n// @tune runSpeed:float:1-8:Running speed with Shift.\n// @tune gravity:float:-40--5:Gravity while walking.\n// @tune standingEye:float:0.8-2:Eye height when standing.\n// @tune pullSpeed:float:0.5-4:Speed when pulled to the seat.\n// @tune sensitivity:float:1-15:Mouse look sensitivity.\n// @tune inspectPitch:float:-30-45:Pitch when looking into the desk.\n// @tune placingPitch:float:0-90:Pitch when looking at the desk top.\n// @tune lyingPitch:float:-60-10:Pitch when lying in bed.\n\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// The main character.\n    ///   WALK    - free first-person walking (hallway, cafeteria).\n    ///   PULLED  - the game takes control and walks you somewhere (to your seat).\n    ///   SEATED  - can't get up by yourself. Mouse looks around (head turn is limited).\n    ///   INSPECT - leaning down to look inside the desk cubby.\n    ///   PLACING - looking down at the desk top.\n    ///   LYING   - lying in bed, pretending to sleep (Lights Out).\n    ///   LOCKED  - no control (cutscenes, game over).\n    /// </summary>\n    [RequireComponent(typeof(CharacterController))]\n    public class PlayerRig : MonoBehaviour\n    {\n        public enum Mode { Walk, Pulled, Seated, Inspect, Placing, Lying, Locked }\n\n        public Transform eye;\n        [Header(\"Walking\")]\n        public float walkSpeed = 2.8f;\n        public float runSpeed = 4.2f;\n        public float gravity = -20f;\n        public float standingEye = 1.5f;\n        public float pullSpeed = 1.3f;\n        [Tooltip(\"Set by the level, e.g. while you are looking at the phone you stand still.\")]\n        public bool freezeMovement;\n        [Header(\"Look\")]\n        public float sensitivity = 5f;\n        [Header(\"Seated eye positions (local to the seat)\")]\n        public Vector3 seatedEye = new Vector3(0f, 1.25f, 0.05f);   // same eye height as the seated NPCs\n        public Vector3 inspectEye = new Vector3(0f, 0.64f, 0.12f);\n        public float inspectPitch = 8f;\n        public Vector3 placingEye = new Vector3(0f, 1.15f, 0.22f);\n        public float placingPitch = 55f;\n        [Header(\"Lying in bed\")]\n        public Vector3 lyingEye = new Vector3(0f, 0.72f, -0.45f);\n        public float lyingPitch = -28f;\n\n        public Mode CurrentMode { get; private set; }\n\n        CharacterController cc;\n        float yaw, pitch, vy;\n        float headYaw, headPitch, basePitch, basePitchTarget;\n        float yawLimit = 100f, pitchMin = -55f, pitchMax = 60f;\n        Vector3 eyeTarget;\n        Vector3[] path;\n        int pathIndex;\n        Vector3 seatPosition;\n        float seatYaw;\n        System.Action onSeated;\n        float eyeSpeed = 1.5f;\n\n        void Awake()\n        {\n            cc = GetComponent<CharacterController>();\n            CurrentMode = Mode.Walk;\n            yaw = transform.eulerAngles.y;\n            eyeTarget = new Vector3(0f, standingEye, 0f);\n            if (eye != null) eye.localPosition = eyeTarget;\n        }\n\n        void Update()\n        {\n            switch (CurrentMode)\n            {\n                case Mode.Walk: UpdateWalk(); break;\n                case Mode.Pulled: UpdatePull(); break;\n                case Mode.Seated:\n                case Mode.Inspect:\n                case Mode.Lying: UpdateHead(); break;\n                case Mode.Placing: ApplyHead(); break;\n            }\n            if (eye != null) eye.localPosition = Vector3.MoveTowards(eye.localPosition, eyeTarget, eyeSpeed * Time.deltaTime);\n        }\n\n        // ------------------------------------------------------------------ walking\n        void UpdateWalk()\n        {\n            Vector2 d = GameInput.MouseDelta() * sensitivity;\n            yaw += d.x;\n            pitch = Mathf.Clamp(pitch - d.y, -80f, 80f);\n            transform.rotation = Quaternion.Euler(0f, yaw, 0f);\n            if (eye != null) eye.localRotation = Quaternion.Euler(pitch, 0f, 0f);\n\n            Vector2 mv = freezeMovement ? Vector2.zero : GameInput.Move();\n            Vector3 dir = transform.right * mv.x + transform.forward * mv.y;\n            if (dir.sqrMagnitude > 1f) dir.Normalize();\n            float speed = GameInput.RunHeld() ? runSpeed : walkSpeed;\n            if (!cc.enabled) return;\n            if (cc.isGrounded) vy = -1f;\n            vy += gravity * Time.deltaTime;\n            cc.Move((dir * speed + Vector3.up * vy) * Time.deltaTime);\n        }\n\n        /// <summary>Take control away and walk the character along 'points' to the seat.</summary>\n        public void PullToSeat(Vector3[] points, Vector3 seatPos, float seatFacingYaw, System.Action seated)\n        {\n            CurrentMode = Mode.Pulled;\n            cc.enabled = false;\n            pullSpeedNow = 0.4f;\n            path = points;\n            pathIndex = 0;\n            seatPosition = seatPos;\n            seatYaw = seatFacingYaw;\n            onSeated = seated;\n        }\n\n        [Header(\"Being pulled to the seat\")]\n        [Tooltip(\"Direction the eyes drift towards while walking in (0 = the front of the class).\")]\n        public float pullLookYaw = 0f;\n        [Range(0f, 1f)] public float pullLookBias = 0.55f;\n        float pullSpeedNow;\n\n        void UpdatePull()\n        {\n            if (path == null || pathIndex >= path.Length) { SitDown(); return; }\n            bool last = pathIndex == path.Length - 1;\n            Vector3 target = path[pathIndex];\n            target.y = transform.position.y;\n            Vector3 to = target - transform.position;\n            float dist = to.magnitude;\n\n            // ease in, ease out on the last stretch\n            float top = last ? Mathf.Lerp(0.35f, pullSpeed, Mathf.Clamp01(dist / 0.8f)) : pullSpeed;\n            pullSpeedNow = Mathf.MoveTowards(pullSpeedNow, top, 1.2f * Time.deltaTime);\n            transform.position = Vector3.MoveTowards(transform.position, target, pullSpeedNow * Time.deltaTime);\n\n            // look: partly where you walk, partly at the class staring back at you - never straight into a wall\n            if (dist > 0.05f)\n            {\n                float walkYaw = Mathf.Atan2(to.x, to.z) * Mathf.Rad2Deg;\n                float want = Mathf.LerpAngle(walkYaw, pullLookYaw, last ? 0.85f : pullLookBias);\n                yaw = Mathf.MoveTowardsAngle(yaw, want, 70f * Time.deltaTime);\n            }\n            transform.rotation = Quaternion.Euler(0f, yaw, 0f);\n            pitch = Mathf.MoveTowards(pitch, 6f, 30f * Time.deltaTime);\n            if (eye != null) eye.localRotation = Quaternion.Euler(pitch, 0f, 0f);\n\n            // cut corners: move on to the next point a little before reaching this one\n            if (dist < (last ? 0.02f : 0.45f)) pathIndex++;\n        }\n\n        void SitDown()\n        {\n            transform.position = seatPosition;\n            yaw = seatYaw;\n            transform.rotation = Quaternion.Euler(0f, seatYaw, 0f);\n            headYaw = 0f; headPitch = pitch; basePitch = 0f; basePitchTarget = 0f;\n            BackToSeat();\n            if (onSeated != null) onSeated();\n        }\n\n        // ------------------------------------------------------------------ seated\n        /// <summary>Put the character straight into a seat (level start, bench, bed).</summary>\n        public void SitAt(Vector3 pos, float facingYaw)\n        {\n            cc.enabled = false;\n            transform.position = pos;\n            yaw = facingYaw;\n            transform.rotation = Quaternion.Euler(0f, facingYaw, 0f);\n            headYaw = 0f; headPitch = 0f; pitch = 0f; basePitch = 0f; basePitchTarget = 0f;\n            BackToSeat();\n            if (eye != null) { eye.localPosition = seatedEye; eye.localRotation = Quaternion.identity; }\n        }\n\n        /// <summary>Stand up and walk again from 'pos'.</summary>\n        public void StandUpAt(Vector3 pos)\n        {\n            transform.position = pos;\n            yaw = transform.eulerAngles.y + headYaw;\n            pitch = 0f;\n            transform.rotation = Quaternion.Euler(0f, yaw, 0f);\n            cc.enabled = true;\n            eyeTarget = new Vector3(0f, standingEye, 0f);\n            CurrentMode = Mode.Walk;\n        }\n\n        /// <summary>Move a walking character somewhere else instantly (e.g. sent back by the PA).</summary>\n        public void Teleport(Vector3 pos, float facingYaw)\n        {\n            bool was = cc.enabled;\n            cc.enabled = false;\n            transform.position = pos;\n            yaw = facingYaw;\n            transform.rotation = Quaternion.Euler(0f, yaw, 0f);\n            cc.enabled = was;\n        }\n\n        public void BackToSeat()\n        {\n            CurrentMode = Mode.Seated;\n            eyeTarget = seatedEye;\n            eyeSpeed = 1.5f;\n            basePitchTarget = 0f;\n            yawLimit = 100f; pitchMin = -60f; pitchMax = 60f;\n        }\n\n        public void EnterInspect()\n        {\n            CurrentMode = Mode.Inspect;\n            eyeTarget = inspectEye;\n            basePitchTarget = inspectPitch;\n            headYaw = 0f; headPitch = 0f;\n            yawLimit = 40f; pitchMin = -25f; pitchMax = 30f;\n        }\n\n        public void EnterPlacing()\n        {\n            CurrentMode = Mode.Placing;\n            eyeTarget = placingEye;\n            basePitchTarget = placingPitch;\n            headYaw = 0f; headPitch = 0f;\n        }\n\n        /// <summary>Lie down in bed (pretend to sleep). SitUp() = BackToSeat().</summary>\n        public void LieDown()\n        {\n            CurrentMode = Mode.Lying;\n            eyeTarget = lyingEye;\n            eyeSpeed = 2.4f;\n            basePitchTarget = lyingPitch;\n            headYaw = Mathf.Clamp(headYaw, -35f, 35f);\n            headPitch = 0f;\n            yawLimit = 35f; pitchMin = -15f; pitchMax = 15f;\n        }\n\n        public void SitUp() { BackToSeat(); eyeSpeed = 2.4f; }\n\n        public void Lock() { CurrentMode = Mode.Locked; }\n\n        /// <summary>Hand walking control (back) to the player - used at the very start, once the teacher has called you in.</summary>\n        public void AllowWalk() { CurrentMode = Mode.Walk; }\n\n        public bool IsSeatedMode { get { return CurrentMode == Mode.Seated || CurrentMode == Mode.Inspect || CurrentMode == Mode.Placing; } }\n\n        /// <summary>Where the head is turned relative to the seat (degrees).</summary>\n        public float HeadYaw { get { return headYaw; } }\n\n        void UpdateHead()\n        {\n            Vector2 d = GameInput.MouseDelta() * sensitivity;\n            headYaw = Mathf.Clamp(headYaw + d.x, -yawLimit, yawLimit);\n            headPitch = Mathf.Clamp(headPitch - d.y, pitchMin, pitchMax);\n            ApplyHead();\n        }\n\n        void ApplyHead()\n        {\n            basePitch = Mathf.MoveTowards(basePitch, basePitchTarget, 150f * Time.deltaTime);\n            if (eye != null) eye.localRotation = Quaternion.Euler(basePitch + headPitch, headYaw, 0f);\n        }\n    }\n}\n"},"RichText":{"path":"Assets/Game/Scripts/RichText.cs","role":"Typewriter reveal that keeps Unity rich-text tags intact and closes any tag left open.","source":"// @role Typewriter reveal that keeps Unity rich-text tags intact and closes any tag left open.\n\nusing System.Collections.Generic;\nusing System.Text;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Typewriter reveal that understands Unity rich-text tags (b, i, color):\n    /// tags are never cut in half, and any tag still open at the cut is closed.\n    /// </summary>\n    public static class RichText\n    {\n        public static int VisibleLength(string s)\n        {\n            if (string.IsNullOrEmpty(s)) return 0;\n            int n = 0;\n            for (int i = 0; i < s.Length; i++)\n            {\n                if (s[i] == '<')\n                {\n                    int j = s.IndexOf('>', i);\n                    if (j > i) { i = j; continue; }\n                }\n                n++;\n            }\n            return n;\n        }\n\n        public static string Reveal(string s, int visible)\n        {\n            if (string.IsNullOrEmpty(s)) return \"\";\n            StringBuilder sb = new StringBuilder();\n            Stack<string> open = new Stack<string>();\n            int shown = 0, i = 0;\n            while (i < s.Length && shown < visible)\n            {\n                if (s[i] == '<')\n                {\n                    int j = s.IndexOf('>', i);\n                    if (j > i)\n                    {\n                        string tag = s.Substring(i, j - i + 1);\n                        sb.Append(tag);\n                        if (tag.StartsWith(\"</\")) { if (open.Count > 0) open.Pop(); }\n                        else\n                        {\n                            string name = tag.Substring(1, tag.Length - 2);\n                            int eq = name.IndexOf('=');\n                            if (eq >= 0) name = name.Substring(0, eq);\n                            open.Push(name);\n                        }\n                        i = j + 1;\n                        continue;\n                    }\n                }\n                sb.Append(s[i]);\n                shown++;\n                i++;\n            }\n            while (open.Count > 0) sb.Append(\"</\").Append(open.Pop()).Append('>');\n            return sb.ToString();\n        }\n\n        /// <summary>The visible character at position 'index' (tags skipped), or '\\0'.</summary>\n        public static char VisibleChar(string s, int index)\n        {\n            if (string.IsNullOrEmpty(s)) return '\\0';\n            int n = 0;\n            for (int i = 0; i < s.Length; i++)\n            {\n                if (s[i] == '<')\n                {\n                    int j = s.IndexOf('>', i);\n                    if (j > i) { i = j; continue; }\n                }\n                if (n == index) return s[i];\n                n++;\n            }\n            return '\\0';\n        }\n    }\n}\n"},"SeatedLook":{"path":"Assets/Game/Scripts/SeatedLook.cs","role":"Seated head turn with clamped yaw and pitch, so you cannot look straight behind you.","source":"// @role Seated head turn with clamped yaw and pitch, so you cannot look straight behind you.\n// @calls GameInput\n// @tune sensitivity:float:1-15:Mouse look sensitivity.\n// @tune maxYaw:float:0-180:Maximum head turn from centre.\n// @tune minPitch:float:-90-0:Maximum look down.\n// @tune maxPitch:float:0-90:Maximum look up.\n\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// The player is seated: the body never moves, the head turns (Watch).\n    /// Turning is limited like a real seated person - you cannot look straight behind you.\n    /// </summary>\n    public class SeatedLook : MonoBehaviour\n    {\n        public Transform eye;\n        public float sensitivity = 5f;\n        public float maxYaw = 100f;\n        public float minPitch = -55f;\n        public float maxPitch = 60f;\n        public bool canLook = true;\n\n        float yaw, pitch;\n\n        void Update()\n        {\n            if (!canLook || eye == null) return;\n            Vector2 d = GameInput.MouseDelta() * sensitivity;\n            yaw = Mathf.Clamp(yaw + d.x, -maxYaw, maxYaw);\n            pitch = Mathf.Clamp(pitch - d.y, minPitch, maxPitch);\n            eye.localRotation = Quaternion.Euler(pitch, yaw, 0f);\n        }\n    }\n}\n"},"SweepRotate":{"path":"Assets/Blockout/Runtime/SweepRotate.cs","role":"Sweeps an object left and right around its starting yaw, used by the cafeteria security camera.","source":"// @role Sweeps an object left and right around its starting yaw, used by the cafeteria security camera.\n// @tune amplitude:float:0-180:Degrees swept to each side of the starting direction.\n// @tune period:float:1-60:Seconds for one full left-right-left sweep.\n\nusing UnityEngine;\n\nnamespace Blockout\n{\n    /// <summary>\n    /// Swings an object left/right around its starting Y rotation.\n    /// Used by the cafeteria security camera (Challenge 4: \"the environment itself can watch\").\n    /// </summary>\n    public class SweepRotate : MonoBehaviour\n    {\n        [Tooltip(\"Degrees to each side of the starting direction.\")]\n        public float amplitude = 35f;\n\n        [Tooltip(\"Seconds for one full left-right-left sweep.\")]\n        public float period = 10f;\n\n        float baseYaw;\n\n        void Start()\n        {\n            baseYaw = transform.localEulerAngles.y;\n        }\n\n        void Update()\n        {\n            if (period <= 0.01f) return;\n            float t = Time.time * 2f * Mathf.PI / period;\n            Vector3 e = transform.localEulerAngles;\n            e.y = baseYaw + Mathf.Sin(t) * amplitude;\n            transform.localEulerAngles = e;\n        }\n    }\n}\n"},"TeacherAI":{"path":"Assets/Game/Scripts/TeacherAI.cs","role":"NavMesh teacher routine: lecture, board writing and wandering, with call-on and approach interrupts.","source":"// @role NavMesh teacher routine: lecture, board writing and wandering, with call-on and approach interrupts.\n// @calls LessonLine\n// @tune lectureTime:Vector2:3-20:Lecture duration range (x to y).\n// @tune boardTime:Vector2:2-15:Board-writing duration range (x to y).\n// @tune lookAroundTime:Vector2:1-8:Look-around duration range (x to y).\n// @tune lectureWeight:float:0-1:Chance the next activity is lecturing.\n// @tune boardWeight:float:0-1:Chance the next activity is writing on the board.\n\nusing System.Collections.Generic;\nusing UnityEngine;\nusing UnityEngine.AI;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// The teacher. Walks on a NavMesh (so he goes AROUND desks and students, never through them) and\n    /// picks his next activity at random:\n    ///   LECTURE    - stands at the front facing the class (dangerous)\n    ///   BOARD      - writes on the blackboard with his back to the class (safe window)\n    ///   WANDER     - walks to a random spot in the room, then looks around\n    /// The level director can interrupt him to CALL ON the player, or to come and TAKE the phone.\n    /// What he SAYS is in LessonScript (lines + questions) and is shown as subtitles by the director.\n    /// </summary>\n    [RequireComponent(typeof(NavMeshAgent))]\n    public class TeacherAI : MonoBehaviour\n    {\n        public enum Activity { Idle, Lecture, Board, Wander, LookAround, Calling, Approach }\n\n        [Header(\"Spots (world positions on the classroom floor)\")]\n        public Vector3 lectureSpot = new Vector3(3.2f, 0.15f, 10.0f);\n        public float lectureFacingYaw = 180f;\n        public Vector3 boardSpot = new Vector3(3.6f, 0.15f, 11.3f);\n        public float boardFacingYaw = 0f;\n        [Tooltip(\"Random wander points are picked inside this rectangle (x min, z min, x max, z max).\")]\n        public Vector4 roomRect = new Vector4(0.4f, 0.5f, 9.6f, 11.4f);\n\n        [Header(\"Timing (seconds)\")]\n        public Vector2 lectureTime = new Vector2(7f, 11f);\n        public Vector2 boardTime = new Vector2(5f, 8f);\n        public Vector2 lookAroundTime = new Vector2(2f, 4f);\n        [Range(0f, 1f)] public float lectureWeight = 0.35f;\n        [Range(0f, 1f)] public float boardWeight = 0.3f;\n\n        [Header(\"Speech\")]\n        public List<LessonLine> lines = LessonDefaults.Lines();\n        public List<LessonQuestion> questions = LessonDefaults.Questions();\n\n        public Activity Current { get; private set; }\n        public bool Running { get; private set; }\n        /// <summary>True when he is facing the board (his back to the class).</summary>\n        public bool IsWritingOnBoard { get { return Current == Activity.Board && arrived; } }\n\n        NavMeshAgent agent;\n        float timer;\n        bool arrived;\n        float targetYaw;\n        bool hasTargetYaw;\n        Transform faceTarget;\n        float sinceGo;\n        Transform visual;   // all his visible parts; kept on the real floor (the NavMesh floats a little above it)\n\n        void Awake()\n        {\n            agent = GetComponent<NavMeshAgent>();\n            agent.enabled = false;   // enabled after the NavMesh is built\n\n            visual = new GameObject(\"Visual\").transform;\n            List<Transform> kids = new List<Transform>();\n            foreach (Transform c in transform) kids.Add(c);\n            visual.SetParent(transform, false);\n            foreach (Transform c in kids) c.SetParent(visual, false);\n        }\n\n        /// <summary>Call after the NavMesh exists.</summary>\n        public void Begin()\n        {\n            agent.enabled = true;\n            NavMeshHit hit;\n            if (NavMesh.SamplePosition(transform.position, out hit, 2f, NavMesh.AllAreas)) agent.Warp(hit.position);\n            Running = true;\n            StartActivity(Activity.Board);\n        }\n\n        public void CallOn(Transform player)\n        {\n            Current = Activity.Calling;\n            faceTarget = player;\n            hasTargetYaw = false;\n            Stop();\n        }\n\n        public void EndCall()\n        {\n            faceTarget = null;\n            PickNext();\n        }\n\n        /// <summary>Walk over to the player (used when taking the phone away).</summary>\n        public void Approach(Vector3 standPoint, Transform lookAt)\n        {\n            Current = Activity.Approach;\n            faceTarget = lookAt;\n            Go(standPoint);\n        }\n\n        public bool HasArrived { get { return arrived; } }\n\n        /// <summary>Go back to his normal random lesson routine.</summary>\n        public void Resume() { EndCall(); }\n\n        /// <summary>Stop where he is and face a direction (e.g. the board) until Resume().</summary>\n        public void HoldFacing(float yaw)\n        {\n            Current = Activity.Calling;\n            faceTarget = null;\n            hasTargetYaw = true;\n            targetYaw = yaw;\n            Stop();\n        }\n\n        /// <summary>Walk to a point, then face a direction and stay there until Resume().</summary>\n        public void WalkToAndFace(Vector3 point, float yaw)\n        {\n            Current = Activity.Approach;\n            faceTarget = null;\n            hasTargetYaw = true;\n            targetYaw = yaw;\n            Go(point);\n        }\n\n        void Update()\n        {\n            if (!Running || !agent.enabled) return;\n\n            sinceGo += Time.deltaTime;\n            if (!arrived && sinceGo > 0.3f && !agent.pathPending && agent.remainingDistance <= agent.stoppingDistance + 0.05f)\n            {\n                arrived = true;\n                agent.isStopped = true;\n                timer = DurationFor(Current);\n            }\n\n            if (arrived || Current == Activity.Calling)\n            {\n                Vector3 dir = Vector3.zero;\n                if (faceTarget != null) { dir = faceTarget.position - transform.position; dir.y = 0f; }\n                else if (hasTargetYaw) dir = Quaternion.Euler(0f, targetYaw, 0f) * Vector3.forward;\n                if (dir.sqrMagnitude > 0.001f)\n                    transform.rotation = Quaternion.RotateTowards(transform.rotation, Quaternion.LookRotation(dir), 220f * Time.deltaTime);\n            }\n\n            if (Current == Activity.Calling || Current == Activity.Approach) return;\n\n            if (arrived)\n            {\n                timer -= Time.deltaTime;\n                if (timer <= 0f)\n                {\n                    if (Current == Activity.Wander) StartActivity(Activity.LookAround);\n                    else PickNext();\n                }\n            }\n        }\n\n        void LateUpdate()\n        {\n            if (visual == null) return;\n            RaycastHit hit;\n            Vector3 from = transform.position + Vector3.up * 0.8f;\n            if (Physics.Raycast(from, Vector3.down, out hit, 2f, ~(1 << gameObject.layer), QueryTriggerInteraction.Ignore))\n            {\n                // only small corrections: never climb onto a chair, bench or desk the ray happens to hit\n                float want = Mathf.Clamp(hit.point.y - transform.position.y, -0.12f, 0.17f);\n                Vector3 lp = visual.localPosition;\n                lp.y = Mathf.MoveTowards(lp.y, want, 1f * Time.deltaTime);\n                visual.localPosition = lp;\n            }\n        }\n\n        void PickNext()\n        {\n            float r = Random.value;\n            if (r < lectureWeight) StartActivity(Activity.Lecture);\n            else if (r < lectureWeight + boardWeight) StartActivity(Activity.Board);\n            else StartActivity(Activity.Wander);\n        }\n\n        void StartActivity(Activity a)\n        {\n            Current = a;\n            faceTarget = null;\n            switch (a)\n            {\n                case Activity.Lecture:\n                    hasTargetYaw = true; targetYaw = lectureFacingYaw;\n                    Go(lectureSpot);\n                    break;\n                case Activity.Board:\n                    hasTargetYaw = true; targetYaw = boardFacingYaw;\n                    Go(boardSpot);\n                    break;\n                case Activity.Wander:\n                    hasTargetYaw = false;\n                    Go(RandomPoint());\n                    break;\n                case Activity.LookAround:\n                    hasTargetYaw = true; targetYaw = Random.Range(0f, 360f);\n                    arrived = true;\n                    timer = DurationFor(a);\n                    break;\n            }\n        }\n\n        void Go(Vector3 p)\n        {\n            NavMeshHit hit;\n            if (NavMesh.SamplePosition(p, out hit, 1.0f, NavMesh.AllAreas)) p = hit.position;\n            agent.isStopped = false;\n            agent.SetDestination(p);\n            arrived = false;\n            sinceGo = 0f;\n        }\n\n        void Stop()\n        {\n            if (agent.enabled) { agent.isStopped = true; agent.ResetPath(); }\n            arrived = true;\n        }\n\n        Vector3 RandomPoint()\n        {\n            for (int i = 0; i < 20; i++)\n            {\n                Vector3 p = new Vector3(Random.Range(roomRect.x, roomRect.z), transform.position.y, Random.Range(roomRect.y, roomRect.w));\n                NavMeshHit hit;\n                if (!NavMesh.SamplePosition(p, out hit, 0.6f, NavMesh.AllAreas)) continue;\n                NavMeshPath path = new NavMeshPath();\n                if (agent.CalculatePath(hit.position, path) && path.status == NavMeshPathStatus.PathComplete) return hit.position;\n            }\n            return lectureSpot;\n        }\n\n        float DurationFor(Activity a)\n        {\n            switch (a)\n            {\n                case Activity.Lecture: return Random.Range(lectureTime.x, lectureTime.y);\n                case Activity.Board: return Random.Range(boardTime.x, boardTime.y);\n                case Activity.LookAround: return Random.Range(lookAroundTime.x, lookAroundTime.y);\n                case Activity.Wander: return 0.2f;\n                default: return 1f;\n            }\n        }\n    }\n}\n"},"TeacherPatrol":{"path":"Assets/Blockout/Runtime/TeacherPatrol.cs","role":"Blockout-only patrol between waypoints with pauses and facing, with no AI or detection.","source":"// @role Blockout-only patrol between waypoints with pauses and facing, with no AI or detection.\n// @calls BlockoutWaypoint\n// @tune walkSpeed:float:0.2-4:Metres per second along the route.\n// @tune turnSpeed:float:30-720:Degrees per second when turning.\n\nusing UnityEngine;\n\nnamespace Blockout\n{\n    /// <summary>\n    /// Blockout-only patrol: walks the watcher between waypoints, pauses, and faces the\n    /// waypoint's forward direction while paused. No AI, no detection - it only exists so the\n    /// patrol RHYTHM (Challenge 1: \"a patrolling teacher with a learnable rhythm\") can be\n    /// seen and timed in the fly-through, and the route can be changed cheaply.\n    /// </summary>\n    public class TeacherPatrol : MonoBehaviour\n    {\n        public BlockoutWaypoint[] waypoints = new BlockoutWaypoint[0];\n\n        [Tooltip(\"Metres per second. ~1.2 is a slow classroom stroll.\")]\n        public float walkSpeed = 1.2f;\n\n        [Tooltip(\"Degrees per second.\")]\n        public float turnSpeed = 240f;\n\n        [Tooltip(\"Waypoint the patrol starts from.\")]\n        public int startIndex = 0;\n\n        [Tooltip(\"On: snap to the start waypoint and wait there. Off: walk to it from where he stands now.\")]\n        public bool teleportToStart = true;\n\n        [Header(\"Read-only (for playtest notes)\")]\n        public string currentNote = \"\";\n\n        int index;\n        bool waiting;\n        float waitTimer;\n\n        void Start()\n        {\n            if (waypoints == null || waypoints.Length == 0) return;\n            index = Mathf.Clamp(startIndex, 0, waypoints.Length - 1);\n            if (teleportToStart)\n            {\n                transform.position = waypoints[index].transform.position;\n                BeginWait(waypoints[index]);\n            }\n            else\n            {\n                waiting = false;\n                currentNote = \"walking\";\n            }\n        }\n\n        void Update()\n        {\n            if (waypoints == null || waypoints.Length == 0) return;\n            BlockoutWaypoint wp = waypoints[index];\n            if (wp == null) { Advance(); return; }\n\n            if (waiting)\n            {\n                Vector3 look = Flat(wp.transform.forward);\n                if (look.sqrMagnitude > 0.0001f)\n                {\n                    Quaternion target = Quaternion.LookRotation(look);\n                    transform.rotation = Quaternion.RotateTowards(transform.rotation, target, turnSpeed * Time.deltaTime);\n                }\n                waitTimer -= Time.deltaTime;\n                if (waitTimer <= 0f) Advance();\n                return;\n            }\n\n            Vector3 goal = wp.transform.position;\n            Vector3 dir = Flat(goal - transform.position);\n            if (dir.sqrMagnitude > 0.0001f)\n            {\n                Quaternion target = Quaternion.LookRotation(dir);\n                transform.rotation = Quaternion.RotateTowards(transform.rotation, target, turnSpeed * Time.deltaTime);\n            }\n            transform.position = Vector3.MoveTowards(transform.position, goal, walkSpeed * Time.deltaTime);\n            if ((transform.position - goal).sqrMagnitude < 0.0004f) BeginWait(wp);\n        }\n\n        void BeginWait(BlockoutWaypoint wp)\n        {\n            waiting = true;\n            waitTimer = wp.waitSeconds;\n            currentNote = wp.note;\n        }\n\n        void Advance()\n        {\n            waiting = false;\n            index = (index + 1) % waypoints.Length;\n            currentNote = \"walking\";\n        }\n\n        static Vector3 Flat(Vector3 v) { v.y = 0f; return v; }\n\n        void OnDrawGizmos()\n        {\n            if (waypoints == null || waypoints.Length < 2) return;\n            Gizmos.color = new Color(1f, 0.55f, 0.1f);\n            for (int i = 0; i < waypoints.Length; i++)\n            {\n                BlockoutWaypoint a = waypoints[i];\n                BlockoutWaypoint b = waypoints[(i + 1) % waypoints.Length];\n                if (a == null || b == null) continue;\n                Gizmos.DrawLine(a.transform.position + Vector3.up * 0.1f, b.transform.position + Vector3.up * 0.1f);\n            }\n        }\n    }\n}\n"},"TeacherVision":{"path":"Assets/Game/Scripts/TeacherVision.cs","role":"Line-of-sight watcher: range, view cone and solid cover checks for teacher, monitor, warden and cameras.","source":"// @role Line-of-sight watcher: range, view cone and solid cover checks for teacher, monitor, warden and cameras.\n// @tune viewAngle:float:20-180:Full width of the view cone in degrees.\n// @tune viewRange:float:2-30:How far the watcher can see.\n// @tune eyeHeight:float:0-3:Eye height above the watcher's feet.\n\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Can this watcher (teacher, monitor, warden, security camera) see a point? Three checks:\n    ///   1. within range   2. inside the view cone (in front of him)   3. nothing solid in between\n    /// (classmates, book stacks, desks, pillars all block - that is what \"cover\" means mechanically).\n    /// 'ignoreRoot' = the player: their own body never blocks the view of their own phone.\n    /// </summary>\n    public class TeacherVision : MonoBehaviour\n    {\n        [Tooltip(\"Full width of the view cone in degrees.\")]\n        public float viewAngle = 90f;\n        public float viewRange = 12f;\n        [Tooltip(\"Height of his eyes above his feet (0 for a camera head: the eye is the object itself).\")]\n        public float eyeHeight = 1.6f;\n        [Tooltip(\"Off = this watcher sees nothing (switched off).\")]\n        public bool active = true;\n\n        public Vector3 EyePosition { get { return transform.position + Vector3.up * eyeHeight; } }\n\n        public bool CanSee(Vector3 point) { return CanSee(point, null, -1f); }\n\n        public bool CanSee(Vector3 point, Transform ignoreRoot, float rangeOverride = -1f)\n        {\n            if (!active || !isActiveAndEnabled) return false;\n            Vector3 eye = EyePosition;\n            Vector3 to = point - eye;\n            float dist = to.magnitude;\n            float range = rangeOverride > 0f ? rangeOverride : viewRange;\n            if (dist > range || dist < 0.001f) return false;\n\n            Vector3 flat = new Vector3(to.x, 0f, to.z);\n            Vector3 fwd = transform.forward; fwd.y = 0f;\n            if (flat.sqrMagnitude > 0.0001f && fwd.sqrMagnitude > 0.0001f && Vector3.Angle(fwd, flat) > viewAngle * 0.5f) return false;\n\n            RaycastHit[] hits = Physics.RaycastAll(eye, to / dist, dist - 0.02f, ~0, QueryTriggerInteraction.Ignore);\n            foreach (RaycastHit h in hits)\n            {\n                if (h.transform.IsChildOf(transform)) continue;\n                if (ignoreRoot != null && h.transform.IsChildOf(ignoreRoot)) continue;\n                return false;   // something is in the way\n            }\n            return true;\n        }\n\n        void OnDrawGizmosSelected()\n        {\n            Gizmos.color = new Color(1f, 0.3f, 0.3f);\n            Vector3 e = EyePosition;\n            Quaternion l = Quaternion.Euler(0f, -viewAngle * 0.5f, 0f), r = Quaternion.Euler(0f, viewAngle * 0.5f, 0f);\n            Gizmos.DrawLine(e, e + l * transform.forward * viewRange);\n            Gizmos.DrawLine(e, e + r * transform.forward * viewRange);\n        }\n    }\n}\n"},"TitleScreen":{"path":"Assets/Game/Scripts/TitleScreen.cs","role":"Title page: CCTV overlay, New Game name entry, Continue, chapter select and Quit.","source":"// @role Title page: CCTV overlay, New Game name entry, Continue, chapter select and Quit.\n// @calls GameFlow, UIFactory, AmbientAudio, AudioSynth, GameInput\n\nusing System.Collections;\nusing UnityEngine;\nusing UnityEngine.EventSystems;\nusing UnityEngine.UI;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Title page (builds its own UI): a CCTV-style frame (REC dot, timestamp, scanlines) over the school's motto.\n    ///  New Game -> \"What is your name?\" (the teacher reads it in the roll call) -> Chapter 1.\n    ///  Continue -> the furthest chapter reached.   Chapters -> any chapter (for playtests / demos).   Quit.\n    /// </summary>\n    public class TitleScreen : MonoBehaviour\n    {\n        static readonly Color Paper = new Color(0.93f, 0.90f, 0.82f);\n        static readonly Color Red = new Color(0.86f, 0.18f, 0.14f);\n\n        GameObject namePanel, chapterPanel;\n        InputField nameField;\n        Image recDot;\n        Text stamp, warning;\n        RectTransform scan;\n        AmbientAudio audioOut;\n\n        void Start()\n        {\n            Time.timeScale = 1f;\n            AudioListener.volume = 1f;\n            Cursor.lockState = CursorLockMode.None;\n            Cursor.visible = true;\n            GameFlow.LoadSavedName();\n            UIFactory.EnsureEventSystem();\n            audioOut = AmbientAudio.Create(transform);\n            audioOut.droneVolume = 0.1f;\n            audioOut.ventVolume = 0.06f;\n            Build();\n        }\n\n        void Update()\n        {\n            if (recDot != null) recDot.enabled = Mathf.Repeat(Time.time, 1.2f) < 0.7f;\n            if (stamp != null) stamp.text = \"CAM 01   SEAT 31   \" + System.DateTime.Now.ToString(\"HH:mm:ss\");\n            if (scan != null) scan.anchoredPosition = new Vector2(0f, -Mathf.Repeat(Time.time * 140f, 1200f));\n            if (warning != null) warning.enabled = Mathf.Repeat(Time.time, 2f) < 1.6f;\n            if (namePanel != null && namePanel.activeSelf && GameInput.EnterDown()) Begin();\n            if (GameInput.EscDown()) { if (namePanel != null) namePanel.SetActive(false); if (chapterPanel != null) chapterPanel.SetActive(false); }\n        }\n\n        void Build()\n        {\n            Canvas canvas = UIFactory.MakeCanvas(\"TitleCanvas\", 10);\n            Transform root = canvas.transform;\n            UIFactory.AddImage(UIFactory.Stretch(\"BG\", root), new Color(0.11f, 0.13f, 0.13f));\n            // pale institutional \"wall\" band + dado, like the corridors\n            UIFactory.AddImage(UIFactory.Rect(\"Dado\", root, Vector2.zero, new Vector2(1f, 0f), new Vector2(0.5f, 0f), Vector2.zero, new Vector2(0f, 300f)), new Color(0.2f, 0.3f, 0.28f));\n            UIFactory.AddImage(UIFactory.Rect(\"DadoLine\", root, Vector2.zero, new Vector2(1f, 0f), new Vector2(0.5f, 0f), new Vector2(0f, 300f), new Vector2(0f, 6f)), new Color(0.55f, 0.5f, 0.32f));\n\n            Text est = UIFactory.AddText(UIFactory.Centered(\"Est\", root, 0f, 330f, 1400f, 40f), \"CLEARVIEW ACADEMY  -  EST. 1952\", 26, new Color(0.68f, 0.74f, 0.7f), TextAnchor.MiddleCenter);\n            est.fontStyle = FontStyle.Bold;\n            Text title = UIFactory.AddText(UIFactory.Centered(\"Title\", root, 0f, 220f, 1400f, 190f), \"COVER\", 180, Paper, TextAnchor.MiddleCenter);\n            title.fontStyle = FontStyle.Bold;\n            UIFactory.AddShadow(title, new Color(0f, 0f, 0f, 0.6f), 5f);\n            UIFactory.AddText(UIFactory.Centered(\"Sub\", root, 0f, 105f, 1400f, 40f), \"a phone, passed down through the same seat\", 28, new Color(0.8f, 0.78f, 0.72f), TextAnchor.MiddleCenter).fontStyle = FontStyle.Italic;\n            warning = UIFactory.AddText(UIFactory.Centered(\"Motto\", root, 0f, 50f, 1400f, 40f), \"WHAT IS SEEN, IS SAFE.\", 26, Red, TextAnchor.MiddleCenter);\n            warning.fontStyle = FontStyle.Bold;\n\n            float y = -40f;\n            Button start = UIFactory.MakeButton(\"NewGame\", root, \"New Game\", 0f, y, 420f, 74f);\n            start.onClick.AddListener(ShowNamePanel);\n            y -= 88f;\n            if (GameFlow.ReachedLevel > 0)\n            {\n                Button cont = UIFactory.MakeButton(\"Continue\", root, \"Continue  -  Ch. \" + (GameFlow.ReachedLevel + 1), 0f, y, 420f, 74f);\n                cont.onClick.AddListener(GameFlow.ContinueGame);\n                y -= 88f;\n            }\n            Button chapters = UIFactory.MakeButton(\"Chapters\", root, \"Chapters\", 0f, y, 420f, 74f);\n            chapters.onClick.AddListener(() => chapterPanel.SetActive(true));\n            y -= 88f;\n            Button quit = UIFactory.MakeButton(\"Quit\", root, \"Quit\", 0f, y, 420f, 74f);\n            quit.onClick.AddListener(Quit);\n\n            UIFactory.AddText(UIFactory.Rect(\"Credits\", root, new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0f, 24f), new Vector2(1600f, 34f)),\n                \"A game by Ariel & Nina  -  CGDD 2026  -  WASD / Mouse / E / Hold Right Mouse: phone\", 20, new Color(0.72f, 0.74f, 0.7f), TextAnchor.MiddleCenter);\n\n            // CCTV overlay\n            RectTransform scanRoot = UIFactory.Stretch(\"Scan\", root);\n            scan = UIFactory.Rect(\"Line\", scanRoot, new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0.5f, 1f), Vector2.zero, new Vector2(0f, 90f));\n            UIFactory.AddImage(scan, new Color(1f, 1f, 1f, 0.025f)).raycastTarget = false;\n            for (int i = 0; i < 4; i++)\n            {\n                Vector2 a = new Vector2(i % 2, i / 2);\n                RectTransform c = UIFactory.Rect(\"Corner\" + i, root, a, a, a, new Vector2(a.x > 0 ? -40f : 40f, a.y > 0 ? -40f : 40f), new Vector2(70f, 70f));\n                Image h = UIFactory.AddImage(UIFactory.Rect(\"H\", c, a, a, a, Vector2.zero, new Vector2(70f, 4f)), new Color(1f, 1f, 1f, 0.5f));\n                Image v = UIFactory.AddImage(UIFactory.Rect(\"V\", c, a, a, a, Vector2.zero, new Vector2(4f, 70f)), new Color(1f, 1f, 1f, 0.5f));\n                h.raycastTarget = v.raycastTarget = false;\n            }\n            recDot = UIFactory.AddImage(UIFactory.Rect(\"Rec\", root, new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(70f, -66f), new Vector2(22f, 22f)), Red);\n            recDot.raycastTarget = false;\n            UIFactory.AddText(UIFactory.Rect(\"RecText\", root, new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(102f, -60f), new Vector2(200f, 34f)), \"REC\", 26, Red, TextAnchor.MiddleLeft).raycastTarget = false;\n            stamp = UIFactory.AddText(UIFactory.Rect(\"Stamp\", root, new Vector2(1f, 1f), new Vector2(1f, 1f), new Vector2(1f, 1f), new Vector2(-70f, -60f), new Vector2(600f, 34f)), \"\", 24, new Color(1f, 1f, 1f, 0.7f), TextAnchor.MiddleRight);\n            stamp.raycastTarget = false;\n\n            BuildNamePanel(root);\n            BuildChapterPanel(root);\n        }\n\n        void ShowNamePanel()\n        {\n            namePanel.SetActive(true);\n            nameField.text = GameFlow.playerName == \"Student\" ? \"\" : GameFlow.playerName;\n            if (EventSystem.current != null) EventSystem.current.SetSelectedGameObject(nameField.gameObject);\n            nameField.ActivateInputField();\n        }\n\n        void Begin()\n        {\n            string n = nameField.text != null ? nameField.text.Trim() : \"\";\n            GameFlow.SaveName(n);\n            GameFlow.StartNewGame();\n        }\n\n        RectTransform Panel(string name, Transform root)\n        {\n            RectTransform panel = UIFactory.Stretch(name, root);\n            Image bg = UIFactory.AddImage(panel, new Color(0.04f, 0.045f, 0.05f, 0.97f));\n            bg.raycastTarget = true;   // blocks the buttons behind it\n            return panel;\n        }\n\n        void BuildNamePanel(Transform root)\n        {\n            RectTransform panel = Panel(\"NamePanel\", root);\n            UIFactory.AddText(UIFactory.Centered(\"Notice\", panel, 0f, 270f, 1400f, 90f),\n                \"NOTICE TO NEW STUDENTS: Devices are not permitted. Every device is monitored.\\nThis is for your safety. Thank you for being safe.\", 24, new Color(0.75f, 0.3f, 0.26f), TextAnchor.MiddleCenter);\n            UIFactory.AddText(UIFactory.Centered(\"Ask\", panel, 0f, 140f, 1200f, 90f), \"Roll call is in a minute.\\nWhat is your name?\", 40, Paper, TextAnchor.MiddleCenter);\n\n            RectTransform box = UIFactory.Centered(\"NameField\", panel, 0f, 10f, 560f, 80f);\n            Image fieldBg = UIFactory.AddImage(box, Paper);\n            fieldBg.raycastTarget = true;\n            Text txt = UIFactory.AddText(UIFactory.Rect(\"Text\", box, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(-40f, -10f)), \"\", 38, new Color(0.08f, 0.08f, 0.1f), TextAnchor.MiddleCenter);\n            txt.supportRichText = false;\n            Text ph = UIFactory.AddText(UIFactory.Rect(\"Placeholder\", box, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(-40f, -10f)), \"type your name\", 34, new Color(0.45f, 0.43f, 0.4f), TextAnchor.MiddleCenter);\n            ph.fontStyle = FontStyle.Italic;\n            nameField = box.gameObject.AddComponent<InputField>();\n            nameField.textComponent = txt;\n            nameField.placeholder = ph;\n            nameField.targetGraphic = fieldBg;\n            nameField.characterLimit = 16;\n\n            Button go = UIFactory.MakeButton(\"EnterClassButton\", panel, \"Go to class\", 0f, -120f, 360f, 84f);\n            go.onClick.AddListener(Begin);\n            UIFactory.AddText(UIFactory.Centered(\"EnterHint\", panel, 0f, -200f, 800f, 40f), \"(Enter)    -    Esc: back\", 22, new Color(0.6f, 0.6f, 0.62f), TextAnchor.MiddleCenter);\n            namePanel = panel.gameObject;\n            namePanel.SetActive(false);\n        }\n\n        void BuildChapterPanel(Transform root)\n        {\n            RectTransform panel = Panel(\"ChapterPanel\", root);\n            UIFactory.AddText(UIFactory.Centered(\"Head\", panel, 0f, 300f, 1200f, 70f), \"CHAPTERS\", 56, Paper, TextAnchor.MiddleCenter).fontStyle = FontStyle.Bold;\n            for (int i = 0; i < GameFlow.Levels.Length; i++)\n            {\n                int idx = i;\n                Button b = UIFactory.MakeButton(\"Chapter\" + i, panel, GameFlow.LevelTitles[i], 0f, 170f - i * 100f, 640f, 80f);\n                b.onClick.AddListener(() => GameFlow.LoadLevel(idx));\n            }\n            Button back = UIFactory.MakeButton(\"Back\", panel, \"Back\", 0f, -290f, 300f, 74f);\n            back.onClick.AddListener(() => chapterPanel.SetActive(false));\n            chapterPanel = panel.gameObject;\n            chapterPanel.SetActive(false);\n        }\n\n        void Quit()\n        {\n#if UNITY_EDITOR\n            UnityEditor.EditorApplication.isPlaying = false;\n#else\n            Application.Quit();\n#endif\n        }\n    }\n}\n"},"TypewriterFont":{"path":"Assets/Game/Scripts/TypewriterFont.cs","role":"Swaps UI Text under this object to the monospace typewriter font at runtime.","source":"// @role Swaps UI Text under this object to the monospace typewriter font at runtime.\n// @calls UIFactory\n\nusing UnityEngine;\nusing UnityEngine.UI;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Scenes built in the editor can only save the built-in font. At runtime this swaps every UI Text under\n    /// this object to the typewriter (monospace) font, for the \"typed in a professional, almost robotic way\" look.\n    /// </summary>\n    public class TypewriterFont : MonoBehaviour\n    {\n        void Awake()\n        {\n            Font mono = UIFactory.MonoFont;\n            if (mono == null) return;\n            foreach (Text t in GetComponentsInChildren<Text>(true))\n            {\n                if (t.font == UIFactory.DefaultFont) t.font = mono;\n            }\n        }\n    }\n}\n"},"UIFactory":{"path":"Assets/Game/Scripts/UIFactory.cs","role":"uGUI construction helpers for canvases, rects, images, text and buttons.","source":"// @role uGUI construction helpers for canvases, rects, images, text and buttons.\n\nusing UnityEngine;\nusing UnityEngine.EventSystems;\nusing UnityEngine.UI;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Small helpers for building uGUI by code (used by the scene builder AND at runtime by the HUD / phone).\n    /// Fonts: in the editor only the built-in font can be saved into scenes; at runtime UI uses a typewriter\n    /// (monospace) font taken from the computer (Courier New / Menlo...), falling back to the built-in one.\n    /// </summary>\n    public static class UIFactory\n    {\n        static Font font, mono;\n        static bool monoTried;\n\n        public static Font DefaultFont\n        {\n            get\n            {\n                if (font == null) font = Resources.GetBuiltinResource<Font>(\"LegacyRuntime.ttf\");\n                return font;\n            }\n        }\n\n        /// <summary>Typewriter font (runtime only). Falls back to the built-in font.</summary>\n        public static Font MonoFont\n        {\n            get\n            {\n                if (mono == null && !monoTried)\n                {\n                    monoTried = true;\n                    try\n                    {\n                        mono = Font.CreateDynamicFontFromOSFont(new[] { \"Courier New\", \"Courier\", \"Menlo\", \"Monaco\", \"Consolas\", \"Liberation Mono\", \"DejaVu Sans Mono\" }, 32);\n                    }\n                    catch (System.Exception) { mono = null; }\n                }\n                return mono != null ? mono : DefaultFont;\n            }\n        }\n\n        /// <summary>The font new Text gets: typewriter while playing, built-in while building scenes in the editor.</summary>\n        public static Font TextFont { get { return Application.isPlaying ? MonoFont : DefaultFont; } }\n\n        public static Canvas MakeCanvas(string name, int sortOrder)\n        {\n            GameObject go = new GameObject(name, typeof(RectTransform), typeof(Canvas), typeof(CanvasScaler), typeof(GraphicRaycaster));\n            Canvas c = go.GetComponent<Canvas>();\n            c.renderMode = RenderMode.ScreenSpaceOverlay;\n            c.sortingOrder = sortOrder;\n            CanvasScaler s = go.GetComponent<CanvasScaler>();\n            s.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;\n            s.referenceResolution = new Vector2(1920f, 1080f);\n            s.matchWidthOrHeight = 0.5f;\n            return c;\n        }\n\n        /// <summary>A canvas that lives in the 3D world (posters, signs). 1 px = 1 mm.</summary>\n        public static Canvas MakeWorldCanvas(string name, Transform parent, Vector3 worldPos, Quaternion rot, float widthMeters, float heightMeters)\n        {\n            GameObject go = new GameObject(name, typeof(RectTransform), typeof(Canvas), typeof(CanvasScaler));\n            go.transform.SetParent(parent, true);\n            Canvas c = go.GetComponent<Canvas>();\n            c.renderMode = RenderMode.WorldSpace;\n            RectTransform rt = (RectTransform)go.transform;\n            rt.sizeDelta = new Vector2(widthMeters * 1000f, heightMeters * 1000f);\n            rt.position = worldPos;\n            rt.rotation = rot;\n            rt.localScale = Vector3.one * 0.001f;\n            CanvasScaler s = go.GetComponent<CanvasScaler>();\n            s.dynamicPixelsPerUnit = 3f;\n            return c;\n        }\n\n        public static RectTransform Rect(string name, Transform parent, Vector2 anchorMin, Vector2 anchorMax, Vector2 pivot, Vector2 pos, Vector2 size)\n        {\n            GameObject go = new GameObject(name, typeof(RectTransform));\n            RectTransform rt = (RectTransform)go.transform;\n            rt.SetParent(parent, false);\n            rt.anchorMin = anchorMin;\n            rt.anchorMax = anchorMax;\n            rt.pivot = pivot;\n            rt.anchoredPosition = pos;\n            rt.sizeDelta = size;\n            return rt;\n        }\n\n        /// <summary>Rect anchored to the parent's top-left corner; pos is (x right, y down) in pixels.</summary>\n        public static RectTransform TopLeft(string name, Transform parent, float x, float y, float w, float h)\n        {\n            return Rect(name, parent, new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(x, -y), new Vector2(w, h));\n        }\n\n        public static RectTransform Centered(string name, Transform parent, float x, float y, float w, float h)\n        {\n            Vector2 c = new Vector2(0.5f, 0.5f);\n            return Rect(name, parent, c, c, c, new Vector2(x, y), new Vector2(w, h));\n        }\n\n        public static RectTransform Stretch(string name, Transform parent)\n        {\n            return Rect(name, parent, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), Vector2.zero, Vector2.zero);\n        }\n\n        public static Image AddImage(RectTransform rt, Color color)\n        {\n            Image img = rt.gameObject.AddComponent<Image>();\n            img.color = color;\n            img.raycastTarget = false;\n            return img;\n        }\n\n        public static Text AddText(RectTransform rt, string text, int size, Color color, TextAnchor align)\n        {\n            Text t = rt.gameObject.AddComponent<Text>();\n            t.font = TextFont;\n            t.text = text;\n            t.fontSize = size;\n            t.color = color;\n            t.alignment = align;\n            t.horizontalOverflow = HorizontalWrapMode.Wrap;\n            t.verticalOverflow = VerticalWrapMode.Overflow;\n            t.raycastTarget = false;\n            return t;\n        }\n\n        public static void AddShadow(Graphic g, Color c, float distance)\n        {\n            Shadow s = g.gameObject.AddComponent<Shadow>();\n            s.effectColor = c;\n            s.effectDistance = new Vector2(distance, -distance);\n        }\n\n        public static Button MakeButton(string name, Transform parent, string label, float x, float y, float w, float h)\n        {\n            RectTransform rt = Centered(name, parent, x, y, w, h);\n            Image img = AddImage(rt, new Color(0.93f, 0.90f, 0.82f, 1f));\n            img.raycastTarget = true;\n            Button b = rt.gameObject.AddComponent<Button>();\n            b.targetGraphic = img;\n            ColorBlock cb = b.colors;\n            cb.highlightedColor = new Color(1f, 0.82f, 0.45f);\n            cb.pressedColor = new Color(0.8f, 0.65f, 0.35f);\n            cb.disabledColor = new Color(0.45f, 0.45f, 0.45f, 0.6f);\n            b.colors = cb;\n            AddText(Stretch(\"Label\", rt), label, 34, new Color(0.08f, 0.08f, 0.1f), TextAnchor.MiddleCenter);\n            return b;\n        }\n\n        public static void EnsureEventSystem()\n        {\n            if (Object.FindFirstObjectByType<EventSystem>() != null) return;\n            GameObject go = new GameObject(\"EventSystem\", typeof(EventSystem));\n#if ENABLE_LEGACY_INPUT_MANAGER\n            go.AddComponent<StandaloneInputModule>();\n#elif ENABLE_INPUT_SYSTEM\n            UnityEngine.InputSystem.UI.InputSystemUIInputModule m = go.AddComponent<UnityEngine.InputSystem.UI.InputSystemUIInputModule>();\n            m.AssignDefaultActions();\n#endif\n        }\n    }\n}\n"},"WallClock":{"path":"Assets/Game/Scripts/WallClock.cs","role":"Institutional wall clock: hour and minute hands turn at a configurable game speed.","source":"// @role Institutional wall clock: hour and minute hands turn at a configurable game speed.\n// @tune startHour:float:0-24:Hour shown when the level starts.\n// @tune minutesPerSecond:float:0-2:Game minutes per real second, 1/60 = real time.\n\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>Institutional wall clock. Hands turn around the clock's local Z axis.</summary>\n    public class WallClock : MonoBehaviour\n    {\n        public Transform hourHand;\n        public Transform minuteHand;\n        [Tooltip(\"Time shown when the level starts, in hours (8.9167 = 8:55).\")]\n        public float startHour = 8.9167f;\n        [Tooltip(\"Game minutes per real second. 1/60 = real time.\")]\n        public float minutesPerSecond = 1f / 60f;\n\n        float t0;\n\n        void Start() { t0 = Time.time; }\n\n        void Update()\n        {\n            float hours = startHour + (Time.time - t0) * minutesPerSecond / 60f;\n            float minutes = (hours - Mathf.Floor(hours)) * 60f;\n            if (hourHand != null) hourHand.localRotation = Quaternion.Euler(0f, 0f, -(hours % 12f) * 30f);\n            if (minuteHand != null) minuteHand.localRotation = Quaternion.Euler(0f, 0f, -minutes * 6f);\n        }\n    }\n}\n"}}};
